{
	"name": "node",
	"platforms": {
		"win32-x64": {
			"sha256": "edaca9bd58ec8e92037dac4e877d52f6b8f430b81c18b57e264b4e2fb111cd56",
			"url": "https://nodejs.org/dist/v24.16.0/node-v24.16.0-win-x64.zip"
		}
