#!/usr/bin/env node
import { existsSync, mkdirSync, readFileSync, renameSync, rmSync, statSync, writeFileSync } from "node:fs";
import { stdin as processStdin, stdout as processStdout } from "node:process";

import { runSubagentStopHook } from "./codex-hook.js";
import type { HookFileSystem } from "./types.js";

const nodeFileSystem: HookFileSystem = {
	existsSync,
	mkdirSync,
	readFileSync,
	renameSync,
	rmSync,
	statSync,
	writeFileSync,
};

const command = process.argv[2];
const subcommand = process.argv[3];

if (command === "hook" && subcommand === "subagent-stop") {
	await runHookCli();
} else {
	process.stderr.write("Usage: lazycodex-executor-verify hook subagent-stop\n");
	process.exitCode = 1;
}

async function runHookCli(): Promise<void> {
	const raw = await readStdin();
	if (raw.trim().length === 0) return;
	const parsed = parseHookInput(raw);
	const output = runSubagentStopHook(parsed, nodeFileSystem);
	if (output.length > 0) processStdout.write(output);
}

function parseHookInput(raw: string): unknown | undefined {
	try {
		const parsed: unknown = JSON.parse(raw);
		return parsed;
	} catch (error) {
		if (error instanceof SyntaxError) return undefined;
		throw error;
	}
}

function readStdin(): Promise<string> {
	return new Promise((resolve) => {
		let data = "";
		processStdin.setEncoding("utf8");
		processStdin.on("data", (chunk: string) => {
			data += chunk;
		});
		processStdin.once("error", () => resolve(data));
		processStdin.once("end", () => resolve(data));
	});
}

import { lstatSync as nodeLstatSync, realpathSync as nodeRealpathSync } from "node:fs";
import { isAbsolute, relative, resolve } from "node:path";

import { renderDirective } from "./directive.js";
import { clearAttemptState, MAX_ATTEMPTS, readAttemptState, writeAttemptState } from "./state.js";
import type { HookFileSystem, StopHookOutput, SubagentStopInput } from "./types.js";
import { SUBAGENT_STOP_EVENT } from "./types.js";

const LAZYCODEX_EXECUTOR_AGENT = "lazycodex-executor";

export function runSubagentStopHook(input: unknown, fs: HookFileSystem): string {
	if (!isSubagentStopInput(input)) return "";
	if (input.agent_type !== LAZYCODEX_EXECUTOR_AGENT) return "";
	if (transcriptHasContextPressureMarker(input.transcript_path, fs)) return "";
	if (hasValidEvidenceReceipt(input, fs)) {
		clearAttemptState(input.cwd, input.session_id, input.agent_id, fs);
		return "";
	}
	const state = readAttemptState(input.cwd, input.session_id, input.agent_id, fs);
	if (state.attempts >= MAX_ATTEMPTS) {
		clearAttemptState(input.cwd, input.session_id, input.agent_id, fs);
		return "";
	}
	const attempts = state.attempts + 1;
	writeAttemptState(input.cwd, input.session_id, input.agent_id, { attempts }, fs);
	return JSON.stringify({
		decision: "block",
		reason: renderDirective(attempts, input.last_assistant_message),
	} satisfies StopHookOutput);
}

const CONTEXT_PRESSURE_MARKERS = [
	"context compacted",
	"context_length_exceeded",
	"skill descriptions were shortened",
	"context_too_large",
	"codex ran out of room in the model's context window",
	"your input exceeds the context window",
	"long threads and multiple compactions",
] as const;

function transcriptHasContextPressureMarker(transcriptPath: string, fs: HookFileSystem): boolean {
	try {
		const transcript = fs.readFileSync(transcriptPath, "utf8").toLowerCase();
		return CONTEXT_PRESSURE_MARKERS.some((marker) => transcript.includes(marker));
	} catch (error) {
		if (error instanceof Error) return false;
		throw error;
	}
}

function hasValidEvidenceReceipt(input: SubagentStopInput, fs: HookFileSystem): boolean {
	const receiptPath = extractEvidencePath(input.last_assistant_message);
	if (receiptPath === null) return false;
	const evidenceRoot = resolve(input.cwd, ".omo", "evidence");
	const resolvedPath = isAbsolute(receiptPath) ? resolve(receiptPath) : resolve(input.cwd, receiptPath);
	if (!isPathInsideDirectory(resolvedPath, evidenceRoot)) return false;
	try {
		return isNonEmptyFileInsideEvidenceRoot(resolvedPath, evidenceRoot, input.cwd, fs);
	} catch (error) {
		if (error instanceof Error) return false;
		throw error;
	}
}

function isPathInsideDirectory(filePath: string, directoryPath: string): boolean {
	const relativePath = relative(directoryPath, filePath);
	return relativePath !== "" && !relativePath.startsWith("..") && !isAbsolute(relativePath);
}

function isNonEmptyFileInsideEvidenceRoot(
	filePath: string,
	evidenceRoot: string,
	cwd: string,
	fs: HookFileSystem,
): boolean {
	if (!fs.existsSync(filePath)) return false;
	const realCwd = realPath(cwd, fs);
	const realEvidenceRoot = realPath(evidenceRoot, fs);
	const realFilePath = realPath(filePath, fs);
	if (!isPathInsideDirectory(realEvidenceRoot, realCwd)) return false;
	if (!isPathInsideDirectory(realFilePath, realEvidenceRoot)) return false;
	return isNonEmptyFile(filePath, fs);
}

function isNonEmptyFile(filePath: string, fs: HookFileSystem): boolean {
	if (!fs.existsSync(filePath)) return false;
	const linkStat = fs.lstatSync?.(filePath) ?? nodeLstatSync(filePath);
	if (linkStat.isSymbolicLink?.() === true) return false;
	const stat = fs.statSync(filePath);
	if (stat.size <= 0) return false;
	return stat.isFile?.() ?? true;
}

function realPath(path: string, fs: HookFileSystem): string {
	return fs.realpathSync?.(path) ?? nodeRealpathSync(path);
}

function extractEvidencePath(message: string | undefined): string | null {
	if (message === undefined) return null;
	const match = /EVIDENCE_RECORDED:\s*(\S+)/.exec(message);
	const receiptPath = match?.[1];
	return receiptPath === undefined ? null : receiptPath;
}

function isSubagentStopInput(value: unknown): value is SubagentStopInput {
	return (
		isRecord(value) &&
		value["hook_event_name"] === SUBAGENT_STOP_EVENT &&
		typeof value["agent_type"] === "string" &&
		typeof value["agent_id"] === "string" &&
		typeof value["session_id"] === "string" &&
		typeof value["cwd"] === "string" &&
		typeof value["transcript_path"] === "string" &&
		typeof value["model"] === "string" &&
		typeof value["permission_mode"] === "string" &&
		typeof value["stop_hook_active"] === "boolean" &&
		optionalString(value["turn_id"]) &&
		optionalString(value["last_assistant_message"])
	);
}

function optionalString(value: unknown): boolean {
	return value === undefined || typeof value === "string";
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

import { readFileSync } from "node:fs";

export const LAZYCODEX_EXECUTOR_VERIFY_DIRECTIVE: string = readFileSync(
	new URL("../directive.md", import.meta.url),
	"utf8",
);

export function renderDirective(attempts: number, lastAssistantMessage: string | undefined): string {
	return LAZYCODEX_EXECUTOR_VERIFY_DIRECTIVE.replaceAll("{{ATTEMPT_COUNT}}", String(attempts)).replaceAll(
		"{{LAST_ASSISTANT_MESSAGE}}",
		lastAssistantMessage ?? "(last_assistant_message was omitted)",
	);
}

export { runSubagentStopHook } from "./codex-hook.js";
export { LAZYCODEX_EXECUTOR_VERIFY_DIRECTIVE, renderDirective } from "./directive.js";
export { MAX_ATTEMPTS } from "./state.js";
export type { HookFileSystem, StopHookOutput, SubagentStopInput } from "./types.js";

import { join } from "node:path";

import type { HookFileSystem } from "./types.js";

export const MAX_ATTEMPTS = 3;

export type AttemptState = {
	readonly attempts: number;
};

export function readAttemptState(cwd: string, sessionId: string, agentId: string, fs: HookFileSystem): AttemptState {
	const statePath = getStatePath(cwd, sessionId, agentId);
	if (!fs.existsSync(statePath)) return { attempts: 0 };
	try {
		const parsed: unknown = JSON.parse(fs.readFileSync(statePath, "utf8"));
		if (isAttemptState(parsed)) return parsed;
		return { attempts: 0 };
	} catch (error) {
		if (error instanceof SyntaxError || error instanceof Error) return { attempts: 0 };
		throw error;
	}
}

export function writeAttemptState(
	cwd: string,
	sessionId: string,
	agentId: string,
	state: AttemptState,
	fs: HookFileSystem,
): void {
	const stateDir = getStateDir(cwd);
	const statePath = getStatePath(cwd, sessionId, agentId);
	const tempPath = `${statePath}.${process.pid}.${Date.now()}.tmp`;
	fs.mkdirSync(stateDir, { recursive: true });
	fs.writeFileSync(tempPath, `${JSON.stringify(state)}\n`);
	fs.renameSync(tempPath, statePath);
}

export function clearAttemptState(cwd: string, sessionId: string, agentId: string, fs: HookFileSystem): void {
	fs.rmSync(getStatePath(cwd, sessionId, agentId), { force: true });
}

export function getStatePath(cwd: string, sessionId: string, agentId: string): string {
	return join(getStateDir(cwd), `${sanitizeKey(sessionId)}-${sanitizeKey(agentId)}.json`);
}

function getStateDir(cwd: string): string {
	return join(cwd, ".omo", "lazycodex-executor-verify");
}

function sanitizeKey(value: string): string {
	const sanitized = value.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "");
	return sanitized.length > 0 ? sanitized : "missing";
}

function isAttemptState(value: unknown): value is AttemptState {
	return isRecord(value) && typeof value["attempts"] === "number" && Number.isInteger(value["attempts"]);
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

export const SUBAGENT_STOP_EVENT = "SubagentStop";

export type SubagentStopInput = {
	readonly hook_event_name: typeof SUBAGENT_STOP_EVENT;
	readonly agent_type: string;
	readonly agent_id: string;
	readonly session_id: string;
	readonly cwd: string;
	readonly transcript_path: string;
	readonly model: string;
	readonly permission_mode: string;
	readonly stop_hook_active: boolean;
	readonly turn_id?: string;
	readonly last_assistant_message?: string;
};

export type StopHookOutput = {
	readonly decision: "block";
	readonly reason: string;
};

export type FileStat = {
	readonly size: number;
	readonly isFile?: () => boolean;
	readonly isSymbolicLink?: () => boolean;
};

export type HookFileSystem = {
	existsSync(path: string): boolean;
	lstatSync?(path: string): FileStat;
	mkdirSync(path: string, options: { readonly recursive: true }): unknown;
	readFileSync(path: string, encoding: "utf8"): string;
	realpathSync?(path: string): string;
	renameSync(oldPath: string, newPath: string): void;
	rmSync(path: string, options: { readonly force: true; readonly recursive?: boolean }): void;
	statSync(path: string): FileStat;
	writeFileSync(path: string, data: string): void;
};

