import type { CodexRulesHookOptions } from "./codex-hook-options.js";
import { configFromEnvironment } from "./config.js";
import { withPromptBudget } from "./event-budget.js";
import { formatAdditionalContextOutput } from "./hook-output.js";
import { completePostCompactRecovery, hydrateEngineState, persistEngineState } from "./persistent-cache.js";
import { withPostCompactBudget } from "./post-compact-budget.js";
import { buildPostCompactReadDirective } from "./post-compact-directive.js";
import type { Engine } from "@oh-my-opencode/rules-engine/engine";
import { isNeverTruncatedRule } from "@oh-my-opencode/rules-engine/engine";
import type { LoadedRule, PiRulesConfig } from "@oh-my-opencode/rules-engine/engine";
import { createRulesEngine } from "./rules-engine-factory.js";
import { getSparkShellRuntimeAwareness, SPARKSHELL_AWARENESS_DEDUP_KEY } from "./sparkshell-awareness.js";
import { filterRulesAlreadyInTranscript, filterRulesNotInTranscriptText } from "./transcript-rule-filter.js";
import type { TranscriptSearchOptions } from "./transcript-search.js";
import { readTranscriptSearchText } from "./transcript-search.js";

export function runStaticInjection(
	cwd: string,
	transcriptPath: string | null,
	eventName: "SessionStart" | "UserPromptSubmit",
	cachePath: string,
	options: CodexRulesHookOptions,
	completedPostCompactChannel?: "static",
	transcriptSearchOptions: TranscriptSearchOptions = {},
	model?: string,
): string {
	const config = configFromEnvironment(options.env);
	if (config.disabled || config.mode === "off" || config.mode === "dynamic") {
		if (completedPostCompactChannel !== undefined) {
			completePostCompactRecovery(cachePath, completedPostCompactChannel);
		}
		return "";
	}

	if (completedPostCompactChannel !== undefined) {
		return runPostCompactRecovery({
			cwd,
			transcriptPath,
			eventName,
			cachePath,
			options,
			channel: completedPostCompactChannel,
			model: model ?? "",
			config,
		});
	}

	const effectiveConfig = eventName === "UserPromptSubmit" ? withPromptBudget(config) : config;
	const engine = createRulesEngine(options, effectiveConfig);
	hydrateEngineState(engine, cachePath);
	engine.state.cwd = cwd;

	const loaded = engine.loadStaticRules(cwd);
	const rules = filterRulesAlreadyInTranscript(
		loaded.rules.filter((rule) => !engine.isStaticInjected(rule)),
		transcriptPath,
		(rule) => {
			engine.markStaticInjected(rule);
		},
		transcriptSearchOptions,
	);
	const sparkshellAwareness = engine.state.staticDedup.has(SPARKSHELL_AWARENESS_DEDUP_KEY)
		? ""
		: getSparkShellRuntimeAwareness(options.env);
	if (rules.length === 0 && sparkshellAwareness.length === 0) {
		persistEngineState(engine, cachePath);
		return "";
	}

	const block = engine.formatStatic(rules);
	for (const rule of rules) {
		engine.markStaticInjected(rule);
	}
	if (sparkshellAwareness.length > 0) {
		engine.state.staticDedup.add(SPARKSHELL_AWARENESS_DEDUP_KEY);
	}
	persistEngineState(engine, cachePath);
	return formatAdditionalContextOutput(eventName, combineStaticContext(block, sparkshellAwareness));
}

interface PostCompactRecoveryInput {
	cwd: string;
	transcriptPath: string | null;
	eventName: "SessionStart" | "UserPromptSubmit";
	cachePath: string;
	options: CodexRulesHookOptions;
	channel: "static";
	model: string;
	config: PiRulesConfig;
}

function runPostCompactRecovery(input: PostCompactRecoveryInput): string {
	const effectiveConfig = withPostCompactBudget(input.config, {
		model: input.model,
		transcriptPath: input.transcriptPath,
	});
	const engine = createRulesEngine(input.options, effectiveConfig);
	hydrateEngineState(engine, input.cachePath);
	engine.state.cwd = input.cwd;

	const loaded = engine.loadStaticRules(input.cwd);
	const transcriptText = readRecoveryTranscriptText(input.transcriptPath);
	const missingRules = filterRulesNotInTranscriptText(
		loaded.rules.filter((rule) => !engine.isStaticInjected(rule)),
		transcriptText,
		(rule) => {
			engine.markStaticInjected(rule);
		},
	);
	const dynamicRulePaths = recoverDynamicRulePaths(engine, transcriptText, loaded.rules);
	const sparkshellAwareness = engine.state.staticDedup.has(SPARKSHELL_AWARENESS_DEDUP_KEY)
		? ""
		: getSparkShellRuntimeAwareness(input.options.env);

	if (missingRules.length === 0 && dynamicRulePaths.length === 0 && sparkshellAwareness.length === 0) {
		persistEngineState(engine, input.cachePath, input.channel);
		return "";
	}

	const fullBodyRules = missingRules.filter((rule) => isNeverTruncatedRule(ruleDisplayPath(rule)));
	const listedRules = missingRules.filter((rule) => !isNeverTruncatedRule(ruleDisplayPath(rule)));
	const bodyBlock = fullBodyRules.length === 0 ? "" : engine.formatStatic(fullBodyRules);
	const directive = buildPostCompactReadDirective(
		[...listedRules.map((rule) => rule.path), ...dynamicRulePaths],
		effectiveConfig.maxResultChars,
	);
	for (const rule of missingRules) {
		engine.markStaticInjected(rule);
	}
	if (sparkshellAwareness.length > 0) {
		engine.state.staticDedup.add(SPARKSHELL_AWARENESS_DEDUP_KEY);
	}
	persistEngineState(engine, input.cachePath, input.channel);
	return formatAdditionalContextOutput(
		input.eventName,
		combineStaticContext(bodyBlock, directive, sparkshellAwareness),
	);
}

function readRecoveryTranscriptText(transcriptPath: string | null): string | null {
	if (transcriptPath === null) {
		return null;
	}
	return (
		readTranscriptSearchText(transcriptPath, { latestCompactedReplacementOnly: true }) ??
		readTranscriptSearchText(transcriptPath)
	);
}

function recoverDynamicRulePaths(
	engine: Engine,
	transcriptText: string | null,
	staticRules: ReadonlyArray<LoadedRule>,
): string[] {
	const staticRulePaths = new Set(staticRules.map((rule) => rule.realPath));
	const recoveredPaths = new Set<string>();
	for (const dedupKeys of engine.state.dynamicDedup.values()) {
		for (const dedupKey of dedupKeys) {
			const separatorIndex = dedupKey.lastIndexOf("::");
			if (separatorIndex <= 0) {
				continue;
			}
			const rulePath = dedupKey.slice(0, separatorIndex);
			if (staticRulePaths.has(rulePath)) {
				continue;
			}
			if (transcriptText !== null && transcriptText.includes(rulePath)) {
				continue;
			}
			if (!existsSync(rulePath)) {
				continue;
			}
			recoveredPaths.add(rulePath);
		}
	}
	return [...recoveredPaths].sort();
}

function ruleDisplayPath(rule: LoadedRule): string {
	return rule.relativePath.length > 0 ? rule.relativePath : rule.path;
}

function combineStaticContext(...blocks: readonly string[]): string {
	return blocks.filter((block) => block.trim().length > 0).join("\n\n");
}

import { existsSync, statSync } from "node:fs";
import { isAbsolute, resolve } from "node:path";

export interface CodexPostToolUseLike {
	tool_name: string;
	tool_input: unknown;
	tool_response: unknown;
}

const COMMAND_TOOL_NAMES = new Set(["bash", "shell_command", "exec_command"]);
const TRACKED_TOOL_NAMES = new Set([
	"read",
	"read_file",
	"mcp__filesystem__read_file",
	"mcp__filesystem__read_multiple_files",
	"mcp__filesystem__write_file",
	"mcp__filesystem__edit_file",
	"write",
	"edit",
	"multiedit",
	"multi_edit",
	"apply_patch",
	"bash",
	"shell_command",
	"exec_command",
]);

export function extractCodexToolPaths(input: CodexPostToolUseLike, cwd: string): string[] {
	const toolName = input.tool_name.toLowerCase();
	if (!TRACKED_TOOL_NAMES.has(toolName) || isFailedToolResponse(input.tool_response)) {
		return [];
	}

	const paths = new Set<string>();
	const toolInput = isRecord(input.tool_input) ? input.tool_input : {};
	addCommonPathFields(paths, toolInput, cwd);
	addPatchPayloadPaths(paths, toolInput, cwd);
	addPatchRecordPaths(paths, toolInput["files"], cwd);
	addPatchRecordPaths(paths, toolInput["changes"], cwd);

	if (COMMAND_TOOL_NAMES.has(toolName)) {
		const command = stringProperty(toolInput, "command") ?? stringProperty(toolInput, "cmd");
		const workdir = stringProperty(toolInput, "workdir") ?? stringProperty(toolInput, "cwd");
		addCommandPaths(paths, command, workdir === undefined ? cwd : resolvePath(cwd, workdir));
	}

	return [...paths];
}

function addCommonPathFields(paths: Set<string>, input: Record<string, unknown>, cwd: string): void {
	for (const key of ["path", "filePath", "file_path", "target", "targetPath", "target_path"]) {
		addPath(paths, input[key], cwd, false);
	}
	for (const key of ["paths", "filePaths", "file_paths"]) {
		addPathArray(paths, input[key], cwd, false);
	}
}

function addPatchPayloadPaths(paths: Set<string>, input: Record<string, unknown>, cwd: string): void {
	for (const key of ["input", "patch", "command", "cmd"]) {
		const value = input[key];
		if (typeof value === "string") {
			addPatchHeaderPaths(paths, value, cwd);
		}
	}
}

function addPatchHeaderPaths(paths: Set<string>, patch: string, cwd: string): void {
	for (const line of patch.split("\n")) {
		for (const prefix of ["*** Add File: ", "*** Update File: ", "*** Move to: "]) {
			if (line.startsWith(prefix)) {
				addPath(paths, line.slice(prefix.length).trim(), cwd, false);
			}
		}
	}
}

function addPatchRecordPaths(paths: Set<string>, value: unknown, cwd: string): void {
	if (!Array.isArray(value)) return;
	for (const item of value) {
		if (typeof item === "string") {
			addPath(paths, item, cwd, false);
			continue;
		}
		if (!isRecord(item)) continue;
		addCommonPathFields(paths, item, cwd);
		for (const key of ["movePath", "move_path", "to", "from"]) {
			addPath(paths, item[key], cwd, false);
		}
	}
}

function addCommandPaths(paths: Set<string>, command: string | undefined, cwd: string): void {
	if (command === undefined) return;
	for (const token of tokenizeShell(command)) {
		if (token.length === 0 || token.startsWith("-") || token.includes("*")) {
			continue;
		}
		addPath(paths, token, cwd, true);
	}
}

function addPathArray(paths: Set<string>, value: unknown, cwd: string, mustExist: boolean): void {
	if (!Array.isArray(value)) return;
	for (const item of value) {
		addPath(paths, item, cwd, mustExist);
	}
}

function addPath(paths: Set<string>, value: unknown, cwd: string, mustExist: boolean): void {
	if (typeof value !== "string" || value.length === 0 || looksLikeUrl(value)) {
		return;
	}

	const path = resolvePath(cwd, value);
	if (mustExist && !isExistingFile(path)) {
		return;
	}
	paths.add(path);
}

function resolvePath(cwd: string, filePath: string): string {
	return isAbsolute(filePath) ? filePath : resolve(cwd, filePath);
}

function isExistingFile(filePath: string): boolean {
	try {
		return existsSync(filePath) && statSync(filePath).isFile();
	} catch {
		return false;
	}
}

function looksLikeUrl(value: string): boolean {
	return /^[A-Za-z][A-Za-z0-9+.-]*:\/\//.test(value);
}

function stringProperty(value: Record<string, unknown>, key: string): string | undefined {
	const property = value[key];
	return typeof property === "string" && property.length > 0 ? property : undefined;
}

function tokenizeShell(command: string): string[] {
	const tokens: string[] = [];
	let current = "";
	let quote: "'" | '"' | null = null;
	let escaped = false;

	for (const character of command) {
		if (escaped) {
			current += character;
			escaped = false;
			continue;
		}
		if (character === "\\") {
			escaped = true;
			continue;
		}
		if ((character === "'" || character === '"') && quote === null) {
			quote = character;
			continue;
		}
		if (quote === character) {
			quote = null;
			continue;
		}
		if (quote === null && /\s/.test(character)) {
			if (current.length > 0) {
				tokens.push(current);
				current = "";
			}
			continue;
		}
		current += character;
	}

	if (current.length > 0) {
		tokens.push(current);
	}
	return tokens;
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isFailedToolResponse(value: unknown): boolean {
	if (!isRecord(value)) return false;
	return (
		value["isError"] === true || value["is_error"] === true || value["error"] === true || value["status"] === "error"
	);
}

import type { LoadedRule } from "@oh-my-opencode/rules-engine/engine";
import type { TranscriptSearchOptions } from "./transcript-search.js";
import { readTranscriptSearchText } from "./transcript-search.js";

export function filterRulesAlreadyInTranscript(
	rules: ReadonlyArray<LoadedRule>,
	transcriptPath: string | null,
	markInjected: (rule: LoadedRule) => void,
	options: TranscriptSearchOptions = {},
): LoadedRule[] {
	if (rules.length === 0 || transcriptPath === null) {
		return [...rules];
	}

	const transcriptText = readTranscriptSearchText(transcriptPath, options);
	return filterRulesNotInTranscriptText(rules, transcriptText, markInjected);
}

export function filterRulesNotInTranscriptText(
	rules: ReadonlyArray<LoadedRule>,
	transcriptText: string | null,
	markInjected: (rule: LoadedRule) => void,
): LoadedRule[] {
	if (rules.length === 0 || transcriptText === null) {
		return [...rules];
	}

	const pendingRules: LoadedRule[] = [];
	for (const rule of rules) {
		if (isRuleAlreadyInTranscript(rule, transcriptText)) {
			markInjected(rule);
			continue;
		}

		pendingRules.push(rule);
	}
	return pendingRules;
}

function isRuleAlreadyInTranscript(rule: LoadedRule, transcriptText: string): boolean {
	const staticReferenceNeedles = [
		`- [${displayFilename(rule)}]{${rule.path}}`,
		`- [${displayFilename(rule)}]{${rule.realPath}}`,
	];
	if (staticReferenceNeedles.some((needle) => transcriptText.includes(needle))) {
		return true;
	}

	const bodyNeedle = rule.body.trim().slice(0, 2_000);
	if (bodyNeedle.length === 0 || !transcriptText.includes(bodyNeedle)) {
		return false;
	}

	const markers = [
		`Instructions from: ${rule.path}`,
		`Instructions from: ${rule.realPath}`,
		rule.relativePath.length === 0 ? null : rule.relativePath,
	].filter((marker): marker is string => marker !== null);
	return markers.some((marker) => transcriptText.includes(marker));
}

function displayFilename(rule: LoadedRule): string {
	const normalizedPath = rule.relativePath.length > 0 ? rule.relativePath : rule.path;
	const segments = normalizedPath
		.replace(/\\/g, "/")
		.split("/")
		.filter((segment) => segment.length > 0);
	return segments.at(-1) ?? normalizedPath;
}

import { readFileSync } from "node:fs";

export interface TranscriptSearchOptions {
	readonly latestCompactedReplacementOnly?: boolean;
}

export function readTranscriptSearchText(transcriptPath: string, options: TranscriptSearchOptions = {}): string | null {
	try {
		const rawTranscript = readFileSync(transcriptPath, "utf8");
		if (options.latestCompactedReplacementOnly === true) {
			return latestCompactedReplacementSearchText(rawTranscript);
		}
		return [rawTranscript, ...collectJsonLineStrings(rawTranscript)].join("\n");
	} catch (error) {
		if (!(error instanceof Error)) {
			throw error;
		}
		return null;
	}
}

function latestCompactedReplacementSearchText(rawTranscript: string): string | null {
	const lines = rawTranscript.split(/\r?\n/);
	let latestCompactedLineIndex = -1;
	let replacementHistory: unknown[] | null = null;
	for (const [index, line] of lines.entries()) {
		const parsed = parseJsonLine(line);
		if (!isRecord(parsed) || parsed["type"] !== "compacted") {
			continue;
		}

		const payload = parsed["payload"];
		if (!isRecord(payload)) {
			continue;
		}

		const candidateReplacementHistory = payload["replacement_history"];
		if (!Array.isArray(candidateReplacementHistory)) {
			continue;
		}

		latestCompactedLineIndex = index;
		replacementHistory = candidateReplacementHistory;
	}

	if (replacementHistory === null) {
		return null;
	}

	const values: string[] = [];
	collectStrings(replacementHistory, values);
	const laterTranscript = lines.slice(latestCompactedLineIndex + 1).join("\n");
	values.push(laterTranscript, ...collectJsonLineStrings(laterTranscript));
	return values.join("\n");
}

function collectJsonLineStrings(rawTranscript: string): string[] {
	const values: string[] = [];
	for (const line of rawTranscript.split(/\r?\n/)) {
		const parsed = parseJsonLine(line);
		if (parsed !== null) {
			collectStrings(parsed, values);
		}
	}
	return values;
}

function parseJsonLine(line: string): unknown | null {
	if (line.trim().length === 0) {
		return null;
	}

	try {
		const parsed: unknown = JSON.parse(line);
		return parsed;
	} catch (error) {
		if (!(error instanceof Error)) {
			throw error;
		}
		return null;
	}
}

function collectStrings(value: unknown, output: string[]): void {
	if (typeof value === "string") {
		output.push(value);
		return;
	}

	if (Array.isArray(value)) {
		for (const item of value) {
			collectStrings(item, output);
		}
		return;
	}

	if (!isRecord(value)) {
		return;
	}

	for (const item of Object.values(value)) {
		collectStrings(item, output);
	}
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterEach, describe, expect, it } from "vitest";

import {
	type CodexPostToolUseInput,
	type CodexSessionStartInput,
	runPostToolUseHook,
	runSessionStartHook,
} from "../src/codex-hook.js";

const REMOVED_AGENT_DOC_SOURCE_LISTS = ["AGENTS.md", "CLAUDE.md", "AGENTS.md,CLAUDE.md"] as const;

const tempDirectories: string[] = [];

type AgentDocProject = {
	readonly pluginData: string;
	readonly root: string;
	readonly nestedSourceFile: string;
};

afterEach(() => {
	for (const directory of tempDirectories.splice(0)) {
		rmSync(directory, { recursive: true, force: true });
	}
});

function makeAgentDocProject(): AgentDocProject {
	const root = mkdtempSync(path.join(tmpdir(), "codex-rules-agent-docs-"));
	const pluginData = mkdtempSync(path.join(tmpdir(), "codex-rules-agent-docs-data-"));
	tempDirectories.push(root, pluginData);

	writeFileSync(path.join(root, "package.json"), JSON.stringify({ name: "fixture" }));
	writeFileSync(path.join(root, "AGENTS.md"), "Root AGENTS.md must remain Codex-native.");
	writeFileSync(path.join(root, "CLAUDE.md"), "Root CLAUDE.md must stay outside rules hook context.");
	writeFileSync(path.join(root, "CONTEXT.md"), "Context source must not leak through removed-only allowlists.");

	mkdirSync(path.join(root, ".omo", "rules"), { recursive: true });
	writeFileSync(
		path.join(root, ".omo", "rules", "typescript.md"),
		[
			"---",
			"description: TypeScript",
			'globs: ["**/*.ts"]',
			"---",
			"",
			"Dynamic .omo/rules context must not leak through removed-only allowlists.",
		].join("\n"),
	);

	const nestedDirectory = path.join(root, "child", "src");
	mkdirSync(nestedDirectory, { recursive: true });
	writeFileSync(path.join(root, "child", "AGENTS.md"), "Child AGENTS.md must remain Codex-native.");
	const nestedSourceFile = path.join(nestedDirectory, "app.ts");
	writeFileSync(nestedSourceFile, "export const app = true;\n");

	return { root, pluginData, nestedSourceFile };
}

function sessionStartInput(root: string): CodexSessionStartInput {
	return {
		session_id: "session-1",
		transcript_path: null,
		cwd: root,
		hook_event_name: "SessionStart",
		model: "gpt-5.5",
		permission_mode: "default",
		source: "startup",
	};
}

function postToolUseInput(root: string, filePath: string): CodexPostToolUseInput {
	return {
		session_id: "session-1",
		turn_id: "turn-1",
		transcript_path: null,
		cwd: root,
		hook_event_name: "PostToolUse",
		model: "gpt-5.5",
		permission_mode: "default",
		tool_name: "mcp__filesystem__read_file",
		tool_input: { path: filePath },
		tool_response: { text: "file contents" },
		tool_use_id: "call-1",
	};
}

describe("agent doc sources", () => {
	for (const sourceList of REMOVED_AGENT_DOC_SOURCE_LISTS) {
		it(`#given ${sourceList} removed-only source allowlist #when SessionStart runs #then it emits no OMO rules context`, async () => {
			// given
			const { root, pluginData } = makeAgentDocProject();

			// when
			const output = await runSessionStartHook(sessionStartInput(root), {
				pluginDataRoot: pluginData,
				env: { CODEX_RULES_ENABLED_SOURCES: sourceList },
			});

			// then
			expect(output).toBe("");
		});
	}

	it("#given nested AGENTS.md and removed-only source allowlist #when PostToolUse targets a child file #then it emits no dynamic OMO rules context", async () => {
		// given
		const { root, pluginData, nestedSourceFile } = makeAgentDocProject();

		// when
		const output = await runPostToolUseHook(postToolUseInput(root, nestedSourceFile), {
			pluginDataRoot: pluginData,
			env: { CODEX_RULES_ENABLED_SOURCES: "AGENTS.md,CLAUDE.md" },
		});

		// then
		expect(output).toBe("");
	});
});

import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";

import { configFromEnvironment } from "../src/config.js";
import { SOURCE_PRIORITY } from "@oh-my-opencode/rules-engine/engine";
import { createEngine, defaultConfig, type EngineDeps } from "@oh-my-opencode/rules-engine/engine";
import { resolvePluginRulesRoot } from "@oh-my-opencode/rules-engine/engine";
import type { RuleCandidate } from "@oh-my-opencode/rules-engine/engine";

const projectRoot = "/tmp/codex-rules-bundled-priority";
const bundledPath = join(projectRoot, "bundled-rules", "hephaestus.md");
const homePath = join(projectRoot, "home", ".opencode", "rules", "hephaestus.md");
const bundledBody = "Bundled baseline discipline.";
const homeBody = "Home baseline discipline override.";
const tempDirectories: string[] = [];

afterEach(() => {
	for (const directory of tempDirectories.splice(0)) {
		rmSync(directory, { recursive: true, force: true });
	}
});

function globalCandidate(source: "plugin-bundled" | "~/.opencode/rules", path: string): RuleCandidate {
	return {
		path,
		realPath: path,
		source,
		distance: 9999,
		isGlobal: true,
		isSingleFile: false,
		relativePath: source === "plugin-bundled" ? "bundled-rules/hephaestus.md" : ".opencode/rules/hephaestus.md",
	};
}

function ruleMarkdown(body: string): string {
	return [
		"---",
		"description: OMO Hephaestus baseline discipline for Codex",
		"alwaysApply: true",
		"---",
		"",
		body,
	].join("\n");
}

describe("plugin bundled rule priority", () => {
	it("#given bundled source explicitly enabled then disabled #when parsing env #then no sources remain enabled", () => {
		// given / when
		const config = configFromEnvironment({
			CODEX_RULES_ENABLED_SOURCES: "plugin-bundled",
			CODEX_RULES_DISABLE_BUNDLED: "1",
		});

		// then
		expect(config.enabledSources).toEqual([]);
	});

	it("#given source priorities #when comparing user-home and bundled rules #then bundled has lower priority", () => {
		// given / when / then
		expect(SOURCE_PRIORITY.get("~/.opencode/rules")).toBe(101);
		expect(SOURCE_PRIORITY.get("plugin-bundled")).toBe(200);
	});

	it("#given user-home and bundled rules share a description #when formatting static rules #then user-home file wins", () => {
		// given
		const bundledCandidate = globalCandidate("plugin-bundled", bundledPath);
		const homeCandidate = globalCandidate("~/.opencode/rules", homePath);
		const deps = {
			findProjectRoot: () => projectRoot,
			findCandidates: () => [bundledCandidate, homeCandidate],
			readFile: (path: string) => {
				if (path === bundledPath) return ruleMarkdown(bundledBody);
				if (path === homePath) return ruleMarkdown(homeBody);
				return null;
			},
		} satisfies EngineDeps;
		const engine = createEngine(defaultConfig(), deps);

		// when
		const loaded = engine.loadStaticRules(projectRoot);
		const formatted = engine.formatStatic(loaded.rules);

		// then
		expect(formatted).toContain(homePath);
		expect(formatted).toContain(homeBody);
		expect(formatted).not.toContain(`- [hephaestus.md]{${homePath}}`);
		expect(formatted).not.toContain(bundledPath);
		expect(formatted).not.toContain(bundledBody);
	});

	it("#given aggregate plugin root #when resolving rules root #then components rules directory is selected", () => {
		// given
		const aggregateRoot = mkdtempSync(join(tmpdir(), "codex-rules-aggregate-plugin-"));
		const componentRoot = join(aggregateRoot, "components", "rules");
		tempDirectories.push(aggregateRoot);
		mkdirSync(join(aggregateRoot, ".codex-plugin"), { recursive: true });
		mkdirSync(componentRoot, { recursive: true });
		writeFileSync(join(aggregateRoot, ".codex-plugin", "plugin.json"), JSON.stringify({ name: "omo" }));

		// when
		const resolvedRoot = resolvePluginRulesRoot(aggregateRoot);

		// then
		expect(resolvedRoot).toBe(componentRoot);
	});
});

import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import {
	type CodexPostCompactInput,
	type CodexSessionStartInput,
	runPostCompactHook,
	runSessionStartHook,
	runUserPromptSubmitHook,
} from "../src/codex-hook.js";
import { createRuleDiscoveryCache, findRuleCandidates } from "@oh-my-opencode/rules-engine/engine";

interface FixtureOptions {
	readonly writeProjectDuplicate?: boolean;
}

interface Fixture {
	readonly root: string;
	readonly pluginRoot: string;
	readonly pluginData: string;
	readonly bundledRulePath: string;
	readonly projectRulePath: string;
}

const BUNDLED_ONLY_ENV = {
	CODEX_RULES_ENABLED_SOURCES: "plugin-bundled",
	CODEX_RULES_MAX_RESULT_CHARS: "40000",
};

const PROJECT_AND_BUNDLED_ENV = {
	CODEX_RULES_ENABLED_SOURCES: ".omo/rules,plugin-bundled",
	CODEX_RULES_MAX_RESULT_CHARS: "40000",
};

const DISABLED_BUNDLED_ENV = {
	CODEX_RULES_ENABLED_SOURCES: "plugin-bundled",
	CODEX_RULES_MAX_RESULT_CHARS: "40000",
	CODEX_RULES_DISABLE_BUNDLED: "1",
};

const BUNDLED_BODY = "Bundled craftsman baseline.";
const SHARED_BODY = "Always choose the smallest correct change.";

const tempDirectories: string[] = [];
let originalPluginRoot: string | undefined;

beforeEach(() => {
	originalPluginRoot = process.env["PLUGIN_ROOT"];
});

afterEach(() => {
	restoreEnv("PLUGIN_ROOT", originalPluginRoot);
	for (const directory of tempDirectories.splice(0)) {
		rmSync(directory, { recursive: true, force: true });
	}
});

function makeFixture(options: FixtureOptions = {}): Fixture {
	const root = mkdtempSync(join(tmpdir(), "codex-rules-bundled-project-"));
	const pluginRoot = mkdtempSync(join(tmpdir(), "codex-rules-bundled-plugin-"));
	const pluginData = mkdtempSync(join(tmpdir(), "codex-rules-bundled-data-"));
	tempDirectories.push(root, pluginRoot, pluginData);

	writeFileSync(join(root, "package.json"), JSON.stringify({ name: "fixture" }));
	mkdirSync(join(root, ".omo", "rules"), { recursive: true });
	mkdirSync(join(pluginRoot, "bundled-rules"), { recursive: true });

	const bundledRulePath = join(pluginRoot, "bundled-rules", "hephaestus.md");
	const bundledBody = options.writeProjectDuplicate === true ? SHARED_BODY : BUNDLED_BODY;
	writeFileSync(bundledRulePath, ruleMarkdown(bundledBody));

	const projectRulePath = join(root, ".omo", "rules", "hephaestus.md");
	if (options.writeProjectDuplicate === true) {
		writeFileSync(projectRulePath, ruleMarkdown(SHARED_BODY));
	}

	process.env["PLUGIN_ROOT"] = pluginRoot;
	return { root, pluginRoot, pluginData, bundledRulePath, projectRulePath };
}

function ruleMarkdown(body: string): string {
	return ["---", "description: Fixture", "alwaysApply: true", "---", "", body].join("\n");
}

function restoreEnv(name: string, value: string | undefined): void {
	if (value === undefined) {
		delete process.env[name];
		return;
	}

	process.env[name] = value;
}

function sessionStartInput(root: string): CodexSessionStartInput {
	return {
		session_id: "session-1",
		transcript_path: null,
		cwd: root,
		hook_event_name: "SessionStart",
		model: "gpt-5.5",
		permission_mode: "default",
		source: "startup",
	};
}

function postCompactInput(root: string): CodexPostCompactInput {
	return {
		session_id: "session-1",
		turn_id: "turn-compact",
		transcript_path: null,
		cwd: root,
		hook_event_name: "PostCompact",
		model: "gpt-5.5",
		trigger: "manual",
	};
}

function userPromptSubmitInput(root: string): Parameters<typeof runUserPromptSubmitHook>[0] {
	return {
		session_id: "session-1",
		turn_id: "turn-1",
		transcript_path: null,
		cwd: root,
		hook_event_name: "UserPromptSubmit",
		model: "gpt-5.5",
		permission_mode: "default",
		prompt: "continue",
	};
}

function occurrenceCount(value: string, search: string): number {
	return value.split(search).length - 1;
}

describe("plugin bundled rules", () => {
	it("#given PLUGIN_ROOT with bundled markdown #when finding candidates #then plugin-bundled source is cached", () => {
		// given
		const { pluginRoot } = makeFixture();
		const cache = createRuleDiscoveryCache();

		// when
		const candidates = findRuleCandidates({ projectRoot: null, targetFile: null, skipUserHome: true, cache });

		// then
		expect(candidates.map((candidate) => `${candidate.source}:${candidate.relativePath}`)).toEqual([
			"plugin-bundled:bundled-rules/hephaestus.md",
		]);
		expect(cache.scannedRuleFiles.has(join(pluginRoot, "bundled-rules"))).toBe(true);
	});

	it("#given alwaysApply bundled Hephaestus rule #when SessionStart runs #then static context expands it inline", async () => {
		// given
		const { root, pluginData, bundledRulePath } = makeFixture();

		// when
		const output = await runSessionStartHook(sessionStartInput(root), {
			pluginDataRoot: pluginData,
			env: BUNDLED_ONLY_ENV,
		});

		// then
		expect(output).toContain('"hookEventName":"SessionStart"');
		expect(output).toContain(`Instructions from: ${bundledRulePath}`);
		expect(output).toContain(BUNDLED_BODY);
		expect(output).toContain("## Project Instructions");
		expect(output).not.toContain("must read project rules:");
		expect(output).not.toContain(`- [hephaestus.md]{${bundledRulePath}}`);
	});

	it("#given same project and bundled body #when SessionStart runs #then project rule file wins", async () => {
		// given
		const { root, pluginData, bundledRulePath, projectRulePath } = makeFixture({ writeProjectDuplicate: true });

		// when
		const output = await runSessionStartHook(sessionStartInput(root), {
			pluginDataRoot: pluginData,
			env: PROJECT_AND_BUNDLED_ENV,
		});

		// then
		expect(occurrenceCount(output, "- [hephaestus.md]{")).toBe(0);
		expect(output).toContain(`Instructions from: ${projectRulePath}`);
		expect(output).toContain(SHARED_BODY);
		expect(output).not.toContain(bundledRulePath);
	});

	it("#given bundled rules disabled #when SessionStart runs #then bundled context is suppressed", async () => {
		// given
		const { root, pluginData } = makeFixture();

		// when
		const output = await runSessionStartHook(sessionStartInput(root), {
			pluginDataRoot: pluginData,
			env: DISABLED_BUNDLED_ENV,
		});

		// then
		expect(output).toBe("");
	});

	it("#given bundled static context dropped by compaction #when UserPromptSubmit runs after PostCompact #then it re-injects the bundled persona body in full", async () => {
		// given
		const { root, pluginData, bundledRulePath } = makeFixture();
		const firstOutput = await runSessionStartHook(sessionStartInput(root), {
			pluginDataRoot: pluginData,
			env: BUNDLED_ONLY_ENV,
		});
		expect(firstOutput).toContain(`Instructions from: ${bundledRulePath}`);
		expect(firstOutput).toContain(BUNDLED_BODY);

		// when
		const compactOutput = await runPostCompactHook(postCompactInput(root), { pluginDataRoot: pluginData });
		const output = await runUserPromptSubmitHook(userPromptSubmitInput(root), {
			pluginDataRoot: pluginData,
			env: BUNDLED_ONLY_ENV,
		});

		// then
		expect(compactOutput).toBe("");
		expect(output).toContain(`Instructions from: ${bundledRulePath}`);
		expect(output).toContain(BUNDLED_BODY);
		expect(output).not.toContain("[Truncated. Full:");
	});

	it("#given bundled Hephaestus rule body exceeds per-rule cap #when SessionStart runs #then static context expands the body within result budget", async () => {
		// given
		const root = mkdtempSync(join(tmpdir(), "codex-rules-bundled-large-project-"));
		const pluginRoot = mkdtempSync(join(tmpdir(), "codex-rules-bundled-large-plugin-"));
		const pluginData = mkdtempSync(join(tmpdir(), "codex-rules-bundled-large-data-"));
		tempDirectories.push(root, pluginRoot, pluginData);
		writeFileSync(join(root, "package.json"), JSON.stringify({ name: "fixture" }));
		mkdirSync(join(pluginRoot, "bundled-rules"), { recursive: true });
		const oversizedBody = "The bundled craftsman discipline is non-negotiable. ".repeat(400);
		expect(oversizedBody.length).toBeGreaterThan(12000);
		const tailMarker = "BUNDLED_TAIL_SENTINEL_LANDS_IN_FULL";
		const bundledRulePath = join(pluginRoot, "bundled-rules", "hephaestus.md");
		const bundledBody = `${oversizedBody}\n\n${tailMarker}\n`;
		writeFileSync(bundledRulePath, ruleMarkdown(bundledBody));
		process.env["PLUGIN_ROOT"] = pluginRoot;

		// when
		const output = await runSessionStartHook(sessionStartInput(root), {
			pluginDataRoot: pluginData,
			env: BUNDLED_ONLY_ENV,
		});

		// then
		expect(output).toContain(`Instructions from: ${bundledRulePath}`);
		expect(output).toContain("The bundled craftsman discipline is non-negotiable.");
		expect(output).toContain(tailMarker);
		expect(output).not.toContain("[Truncated. Full:");
	});

	it("#given project rule body exceeds per-rule cap #when SessionStart runs #then static context injects a truncated body", async () => {
		// given
		const root = mkdtempSync(join(tmpdir(), "codex-rules-project-large-project-"));
		const pluginRoot = mkdtempSync(join(tmpdir(), "codex-rules-project-large-plugin-"));
		const pluginData = mkdtempSync(join(tmpdir(), "codex-rules-project-large-data-"));
		tempDirectories.push(root, pluginRoot, pluginData);
		writeFileSync(join(root, "package.json"), JSON.stringify({ name: "fixture" }));
		mkdirSync(join(root, ".omo", "rules"), { recursive: true });
		mkdirSync(join(pluginRoot, "bundled-rules"), { recursive: true });
		const oversizedBody = "The project rule body is intentionally oversized for the cap test. ".repeat(300);
		expect(oversizedBody.length).toBeGreaterThan(12000);
		const tailMarker = "PROJECT_TAIL_SENTINEL_SHOULD_NOT_LAND";
		const projectRulePath = join(root, ".omo", "rules", "oversized.md");
		const projectBody = `${oversizedBody}\n\n${tailMarker}\n`;
		writeFileSync(projectRulePath, ruleMarkdown(projectBody));
		process.env["PLUGIN_ROOT"] = pluginRoot;

		// when
		const output = await runSessionStartHook(sessionStartInput(root), {
			pluginDataRoot: pluginData,
			env: { CODEX_RULES_ENABLED_SOURCES: ".omo/rules" },
		});

		// then
		expect(output).toContain(`Instructions from: ${projectRulePath}`);
		expect(output).toContain("The project rule body is intentionally oversized for the cap test.");
		expect(output).toContain("[Truncated. Full:");
		expect(output).not.toContain(tailMarker);
	});
});

