		trigger: "auto",
	};
}

function userPromptSubmitInput(root: string, transcriptPath: string): Parameters<typeof runUserPromptSubmitHook>[0] {
	return {
		session_id: "session-post-compact-budget",
		turn_id: "turn-after-compact",
