// team-guide.mjs - render the member-facing field manual (guide.md) and the short
// bootstrap trigger a new thread reads on startup. Pure string builders, no I/O.
//
// The manual is the durable, two-channel replacement for per-prompt guidance: the leader
// writes it once at team creation, and every member thread is told to READ it instead of
// receiving the rules inline each turn.

export function codexThreadLink(threadId) {
	return `codex://threads/${threadId}`;
}

function memberLine(member) {
	const thread = member.threadId ? ` | thread ${member.threadId} (${codexThreadLink(member.threadId)})` : " | thread not created yet";
	const wt = member.worktree?.path ? ` | worktree ${member.worktree.path}` : "";
	const name = member.name ? ` "${member.name}"` : "";
	const title = member.threadTitle ? ` | thread title \`${member.threadTitle}\`` : "";
	return `- **${member.id}**${name} (${member.lens}) - ${member.focus}${member.deliverable ? ` -> ${member.deliverable}` : ""}${title}${thread}${wt} [${member.status}]`;
}

function worktreeSection(team) {
	if (!team.worktree?.enabled) {
		return `## Worktrees

This team does not use isolated git worktrees. Work in the shared repository checkout
the leader is running from. If your changes would collide with another member's files,
that is a coordination signal: mark yourself \`blocked\` and tell the leader at once.`;
	}
	const lines = team.members
		.filter((m) => m.worktree?.path || m.worktree?.branch)
		.map((m) => {
			const thread = m.threadId ? `; thread ${codexThreadLink(m.threadId)}` : "";
			return `- **${m.id}**: worktree \`${m.worktree.path ?? "(assign with bind-thread --cwd)"}\` on branch \`${m.worktree.branch ?? team.worktree.baseBranch}\`${thread}`;
		});
	return `## Worktrees (ISOLATION IS ON - this is not optional for you)

This team runs each member in its own git worktree branched off \`${team.worktree.baseBranch}\`.
**You MUST work only inside your own worktree.** The very first thing you do is \`cd\` into it;
every edit, command, and commit happens there. Never touch another member's worktree, and
never edit files outside your assigned scope. Commit your work so the leader can integrate it.
Before editing, verify that your assigned worktree exists and contains repo files. If the path is
missing, empty, or does not look like a git worktree/repository yet, send \`BLOCKED: worktree not ready\`
to the leader and wait instead of editing any parent checkout or empty directory.

If Codex returns only \`pendingWorktreeId\` while the leader is creating a worktree-backed member
thread, the thread is not ready yet. The leader must wait until Codex surfaces a real thread id,
then bind that real id and send the bootstrap.

${lines.length ? lines.join("\n") : "- (worktree paths are assigned as threads are bound; read team.json for yours)"}`;
}

export function buildGuide(team) {
	const artifacts = team.paths?.artifacts ?? ".omo/teams/<session_id>/artifacts";
	const teamJson = team.paths?.team ?? ".omo/teams/<session_id>/team.json";
	const roster = team.members.length ? team.members.map(memberLine).join("\n") : "- (no members yet)";
	return `# Team ${team.teamName} - Member Field Manual

> Auto-generated by the teammode script. This file is the single source of truth for how
> this team works. Re-read it whenever you are unsure - do not improvise the protocol.

- Team: **${team.teamName}** (id \`${team.teamId}\`)
- Team state: \`${teamJson}\`
- Thread title convention: \`${team.threadTitleConvention}\` - each member's thread takes its OWN title from its name (your row below shows yours); two members never share a title

## Who you are (your identity is fixed)

**You are a member of team ${team.teamName}, not a generic assistant.** You own exactly one
slice of this team's work - the focus and deliverable assigned to your id below - and you are
accountable for it end to end. Read your row, internalize it, and act as that owner for the
whole session. Do not drift into other members' scope.

${roster}

## Leader

**The main session is the leader. There is no other leader, and you are not it.** You report
to the leader, take direction from the leader, and send your results to the leader. Peers
coordinate with each other, but the leader owns the final decision and integration.

## Communication rules (hard rules)

- **All communication between team members, and from you to the leader, is in English.** This
  is mandatory regardless of the language the task was given in.
- **Exception: when the END USER addresses you directly, reply in the user's own language.**
  Team-internal traffic stays English; user-facing replies match the user.
- **Reach the leader and your peers with \`codex_app.send_message_to_thread\` - not by narrating in
  your own thread, where no one reads it.** The address book is in team.json: the leader thread id
  is \`leader.sessionId\`, and each peer thread id is its \`members[].threadId\`.
- **When you mention a Codex thread, include its app link too:** \`codex://threads/<threadId>\`.
  These links are the fastest way for the leader to reopen worktree-backed member threads.
- **Push a short message at each of these moments - never batch them into one report at the end:**
  - to the **leader**: every finding or decision, every file or sub-task you finish, a
    \`WORKING: <focus> - <phase>\` heartbeat every few tool calls so you never look stale, a
    \`BLOCKED: <reason>\` the instant you cannot proceed, and your result the moment your slice is done.
  - to a **peer**: the instant you learn anything that touches their slice - a shared finding, a
    changed assumption, an interface they depend on. When unsure who owns it, send it to the leader.
- **Going quiet is the only failure.** Many small lean messages beat one end-of-work dump; keep
  every message short.

## Artifacts (how you hand work off)

Exchange files and memos through the team artifacts directory:

\`${artifacts}\`

Drop deliverables, notes, diffs, and findings there as files, and reference them by path in
your messages instead of pasting large content into a thread. Treat it as the team's shared
desk: if a peer or the leader needs something from you, leave it in artifacts and point them to it.

${worktreeSection(team)}

## Done means reported and verified

Your slice is done only when (1) the deliverable exists, (2) you have evidence it works, and
(3) you have reported it to the leader. Until all three are true, keep going.`;
}

export function buildMemberPrompt(team, id) {
	const member = team.members.find((m) => m.id === id);
	if (!member) throw new Error(`no member with id "${id}"`);
	const guide = team.paths?.guide ?? ".omo/teams/<session_id>/guide.md";
	const teamJson = team.paths?.team ?? ".omo/teams/<session_id>/team.json";
	const where = member.cwd
		? `Work inside \`${member.cwd}\`.`
		: team.worktree?.enabled
			? "Wait for the leader to bind your worktree cwd before editing."
			: "Work from the repository root unless your manual assigns a worktree.";
	const threadLink = member.threadId ? `\nYour Codex thread link is ${codexThreadLink(member.threadId)}. Include it when reporting handoffs or worktree status.` : "";
	const readiness =
		team.worktree?.enabled
			? "\nBefore editing, verify that your assigned worktree exists and contains repo files. If this prompt arrived before your Codex worktree checkout is ready, or the path is missing, empty, or not a git worktree/repository yet, report `BLOCKED: worktree not ready` to the leader and wait."
			: "";
	return `You are member ${member.id}${member.name ? ` (${member.name})` : ""} of team ${team.teamName} - owner of: ${member.focus}. Your thread title is \`${member.threadTitle}\`.
FIRST read your field manual at \`${guide}\`, then the team state at \`${teamJson}\`; they define your scope, deliverable, the leader, the artifacts directory, and the communication rules.
${where}${threadLink}${readiness}
Communicate with the team and leader in English; reply to the end user in the user's own language.
Start now. Push updates to the leader and relevant peers with \`codex_app.send_message_to_thread\` as you work - findings, \`WORKING:\` heartbeats, and \`BLOCKED:\` the instant you stall - never just one report at the end.`;
}

// team-state.mjs - the teammode state model + atomic, symlink-guarded persistence.
//
// Zero external dependencies (node builtins only) so it runs byte-identically under
// `node` and `bun` on macOS, Linux, and Windows with no install step, no POSIX shell,
// and no python3 precondition. This is the SINGLE source of the team-state shape: the
// model never hand-writes team.json - it calls these helpers through scripts/team.mjs.
//
// Rendering (the member field manual + bootstrap trigger) lives in team-guide.mjs so
// this file stays the state concern only.

import { randomUUID } from "node:crypto";
import { lstat, mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { dirname, isAbsolute, join, relative, resolve } from "node:path";

export const LENSES = ["area", "ownership", "perspective"];
export const MEMBER_STATUSES = ["pending", "active", "reported", "blocked", "archived"];
// A team is never a single member: two or more distinct slices is the minimum. One isolated
// job is a subagent, not a team.
export const MIN_MEMBERS = 2;

export function isUnderstaffed(team) {
	return team.members.length < MIN_MEMBERS;
}
// A team dir is a single child of .omo/teams. This pattern alone blocks "/", "\", and a
// leading "." so ".." and "a/b" can never name a team dir (the escape guard).
const SESSION_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/;

function isoNow(now) {
	return now ?? new Date().toISOString();
}

export function buildTeam({ teamName, sessionName, sessionId = null, dir = null, worktreeEnabled = false, baseBranch = "dev", now }) {
	if (!teamName?.trim()) throw new Error("team name is required");
	if (!sessionName?.trim()) throw new Error("session name is required");
	const ts = isoNow(now);
	return {
		schemaVersion: 2,
		teamId: randomUUID(),
		teamName: teamName.trim(),
		sessionName: sessionName.trim(),
		sessionId,
		threadTitleConvention: `[${teamName.trim()}] <member name>`,
		status: "active",
		createdAt: ts,
		updatedAt: ts,
		archivedAt: null,
		leader: { kind: "main-session", sessionId },
		communication: { memberLanguage: "english", replyToUserInUserLanguage: true },
		worktree: { enabled: Boolean(worktreeEnabled), baseBranch, root: dir ? join(dir, "worktrees") : null },
		paths: dir
			? { dir, team: join(dir, "team.json"), guide: join(dir, "guide.md"), artifacts: join(dir, "artifacts") }
			: null,
		members: [],
		log: [{ ts, event: "created", detail: `team ${teamName.trim()}` }],
	};
}

function touch(team, event, detail) {
	const ts = isoNow();
	team.updatedAt = ts;
	team.log.push({ ts, event, detail });
	return team;
}

function memberById(team, id) {
	const found = team.members.find((m) => m.id === id);
	if (!found) throw new Error(`no member with id "${id}"`);
	return found;
}

function normalizedFocus(focus) {
	return focus.trim().replace(/\s+/g, " ").toLowerCase();
}

function normalizedMemberName(name) {
	return name.trim().replace(/\s+/g, " ").toLowerCase();
}

function normalizedThreadTitle(title) {
	return title.trim().replace(/\s+/g, " ").toLowerCase();
}

function assertUniqueMemberFocus(team) {
	const seen = new Map();
	for (const member of team.members) {
		const key = normalizedFocus(member.focus ?? "");
		const previous = seen.get(key);
		if (previous) {
			throw new Error(`member focus "${member.focus}" duplicates "${previous.focus}" (no two members may own the same thing)`);
		}
		seen.set(key, member);
	}
}

function assertUniqueMemberName(team) {
	const seen = new Map();
	for (const member of team.members) {
		const memberName = member.name ?? member.focus ?? "";
		const key = normalizedMemberName(memberName);
		const previous = seen.get(key);
		if (previous) {
			throw new Error(`member name "${memberName}" duplicates "${previous.name ?? previous.focus}" (no two members may produce the same thread title)`);
		}
		seen.set(key, member);
	}
}

function assertUniqueMemberThreadTitle(team) {
	const seen = new Map();
	for (const member of team.members) {
		const threadTitle = member.threadTitle;
		if (typeof threadTitle !== "string" || !threadTitle.trim()) {
			throw new Error(`member "${member.id ?? member.name ?? member.focus ?? "(unknown)"}" has invalid threadTitle (non-empty string required)`);
		}
		const key = normalizedThreadTitle(threadTitle);
		const previous = seen.get(key);
		if (previous) {
			throw new Error(`member threadTitle "${threadTitle}" duplicates "${previous.threadTitle}" (no two members may produce the same thread title)`);
		}
		seen.set(key, member);
	}
}

function assertTeamReadyForThreadBinding(team) {
	if (isUnderstaffed(team)) {
		throw new Error(
			`cannot bind member threads until the team has at least ${MIN_MEMBERS} distinct members; current count is ${team.members.length}`,
		);
	}
	assertUniqueMemberFocus(team);
	assertUniqueMemberName(team);
	assertUniqueMemberThreadTitle(team);
}

export function addMember(team, { id, focus, lens, deliverable = "", branch = null, name = null }) {
	if (!id?.trim()) throw new Error("member id is required");
	if (!focus?.trim()) throw new Error("member focus is required - a concrete part, ownership area, or perspective");
	if (!LENSES.includes(lens)) throw new Error(`invalid lens "${lens}" - use one of: ${LENSES.join(", ")}`);
	const memberId = id.trim();
	const memberFocus = focus.trim();
	// The member name is the short role label that titles this member's thread. Fall back to the
	// focus so the title is ALWAYS per-member and never the shared team-wide session name.
	const memberName = name?.trim() || memberFocus;
	if (team.members.some((m) => m.id === memberId)) throw new Error(`member id "${memberId}" already exists (duplicate)`);
	const duplicate = team.members.find((m) => normalizedFocus(m.focus) === normalizedFocus(memberFocus));
	if (duplicate) throw new Error(`member focus "${memberFocus}" duplicates "${duplicate.focus}" (no two members may own the same thing)`);
	const duplicateName = team.members.find((m) => normalizedMemberName(m.name ?? m.focus ?? "") === normalizedMemberName(memberName));
	if (duplicateName) {
		throw new Error(`member name "${memberName}" duplicates "${duplicateName.name ?? duplicateName.focus}" (no two members may produce the same thread title)`);
	}
	team.members.push({
		id: memberId,
		name: memberName,
		focus: memberFocus,
		lens,
		deliverable: deliverable.trim(),
		threadId: null,
		threadTitle: `[${team.teamName}] ${memberName}`,
		cwd: null,
		worktree: { path: null, branch: branch ?? null },
		status: "pending",
	});
	return touch(team, "add-member", `member ${memberId} (${lens}): ${memberFocus}`);
}

export function bindThread(team, { id, threadId, cwd = null, worktreePath = null }) {
	if (!threadId?.trim()) throw new Error("thread id is required");
	assertTeamReadyForThreadBinding(team);
	const m = memberById(team, id);
	m.threadId = threadId.trim();
	m.status = "active";
	if (cwd) m.cwd = cwd;
	if (team.worktree.enabled) m.worktree.path = worktreePath ?? cwd ?? m.worktree.path;
	return touch(team, "bind-thread", `member ${id} -> thread ${threadId.trim()}`);
}

export function setMemberStatus(team, { id, status, note = "" }) {
	if (!MEMBER_STATUSES.includes(status)) throw new Error(`invalid status "${status}" - use one of: ${MEMBER_STATUSES.join(", ")}`);
	memberById(team, id).status = status;
	return touch(team, "set-status", `member ${id} -> ${status}${note ? `: ${note}` : ""}`);
}

// Record a provisioned worktree. Isolation is conflict-triggered: the first worktree-add flips
// the whole team into worktree mode, so the leader can decide it mid-run, not only at init.
export function setMemberWorktree(team, { id, path, branch }) {
	const m = memberById(team, id);
	team.worktree.enabled = true;
	m.worktree.path = path;
	m.worktree.branch = branch;
	m.cwd = path;
	return touch(team, "worktree-add", `member ${id} -> ${path} (${branch})`);
}

export function clearMemberWorktree(team, { id }) {
	const m = memberById(team, id);
	if (m.cwd === m.worktree?.path) m.cwd = null;
	m.worktree.path = null;
	return touch(team, "worktree-remove", `member ${id}`);
}

export function archive(team, { id = null, note = "" } = {}) {
	if (id) {
		memberById(team, id).status = "archived";
		return touch(team, "archive-member", `member ${id}${note ? `: ${note}` : ""}`);
	}
	for (const m of team.members) m.status = "archived";
	team.status = "archived";
	team.archivedAt = isoNow();
	return touch(team, "archive", note || "team archived; all members closed");
}

export function validateTeam(team) {
	if (team?.schemaVersion !== 2) throw new Error("invalid team: schemaVersion must be 2");
	if (!team.teamId || !team.teamName) throw new Error("invalid team: teamId and teamName are required");
	if (team.leader?.kind !== "main-session") throw new Error("invalid team: leader.kind must be main-session");
	if (!Array.isArray(team.members)) throw new Error("invalid team: members must be an array");
	assertUniqueMemberFocus(team);
	assertUniqueMemberName(team);
	assertUniqueMemberThreadTitle(team);
	return team;
}

// Resolve (and confine) a team dir to a single child of <cwd>/.omo/teams.
export function resolveTeamDir(cwd, sessionId) {
	if (!SESSION_ID_PATTERN.test(sessionId ?? "")) throw new Error(`invalid or unsafe session id "${sessionId}"`);
	return resolve(cwd, ".omo", "teams", sessionId);
}

async function lstatOrNull(p) {
	return lstat(p).catch((error) => {
		if (error && error.code === "ENOENT") return null;
		throw error;
	});
}

// Create a directory chain refusing any symlinked component, so team state can never be
// written through a symlink that escapes the workspace.
async function mkdirNoSymlink(dir, stopAt) {
	if (dir === stopAt) return;
	const rel = relative(stopAt, dir);
	if (rel.startsWith("..") || isAbsolute(rel)) throw new Error(`refused: path escapes ${stopAt}: ${dir}`);
	await mkdirNoSymlink(dirname(dir), stopAt);
	const st = await lstatOrNull(dir);
	if (st) {
		if (st.isSymbolicLink()) throw new Error(`refused: path component is a symlink: ${dir}`);
		if (!st.isDirectory()) throw new Error(`refused: path component is not a directory: ${dir}`);
		return;
	}
	await mkdir(dir);
}

async function assertNoSymlinkComponents(dir, stopAt) {
	if (dir === stopAt) return;
	const rel = relative(stopAt, dir);
	if (rel.startsWith("..") || isAbsolute(rel)) throw new Error(`refused: path escapes ${stopAt}: ${dir}`);
	await assertNoSymlinkComponents(dirname(dir), stopAt);
	const st = await lstatOrNull(dir);
	if (st?.isSymbolicLink()) throw new Error(`refused: path component is a symlink: ${dir}`);
}

export async function ensureTeamDir(cwd, sessionId) {
	const workspaceRoot = resolve(cwd);
	const teamsRoot = resolve(cwd, ".omo", "teams");
	const dir = resolveTeamDir(cwd, sessionId);
	await mkdirNoSymlink(teamsRoot, workspaceRoot);
	await mkdirNoSymlink(dir, teamsRoot);
	await mkdirNoSymlink(join(dir, "artifacts"), dir);
	return dir;
}

export async function assertSafeTeamDir(cwd, sessionId) {
	const workspaceRoot = resolve(cwd);
	const teamsRoot = resolve(cwd, ".omo", "teams");
	const dir = resolveTeamDir(cwd, sessionId);
	await assertNoSymlinkComponents(teamsRoot, workspaceRoot);
	await assertNoSymlinkComponents(dir, teamsRoot);
	return dir;
}

export async function readTeam(dir) {
	return validateTeam(JSON.parse(await readFile(join(dir, "team.json"), "utf8")));
}

export async function teamExists(dir) {
	return (await lstatOrNull(join(dir, "team.json"))) !== null;
}

async function persistedFileTarget(team, pathKey, fileName, expectedDir) {
	validateTeam(team);
	if (!team.paths?.dir || !team.paths?.[pathKey]) throw new Error(`invalid team: paths.${pathKey} is required`);
	const dir = resolve(expectedDir);
	if (resolve(team.paths.dir) !== dir) throw new Error(`refused: persisted team dir does not match trusted team dir: ${team.paths.dir}`);
	const target = resolve(team.paths[pathKey]);
	if (target !== resolve(dir, fileName)) throw new Error(`refused: ${fileName} persist target escapes team dir: ${team.paths[pathKey]}`);
	const dirStat = await lstatOrNull(dir);
	if (dirStat?.isSymbolicLink()) throw new Error(`refused: team dir is a symlink: ${dir}`);
	const st = await lstatOrNull(target);
	if (st?.isSymbolicLink()) throw new Error(`refused: ${fileName} is a symlink: ${target}`);
	if (st && !st.isFile()) throw new Error(`refused: ${fileName} is not a file: ${target}`);
	return target;
}

async function writePersistedFileAtomic(team, pathKey, fileName, content, expectedDir) {
	const target = await persistedFileTarget(team, pathKey, fileName, expectedDir);
	const tmp = `${target}.tmp-${process.pid}-${randomUUID()}`;
	await writeFile(tmp, content, { encoding: "utf8", flag: "wx" });
	await rename(tmp, target);
	return team;
}

export async function writeTeamAtomic(team, expectedDir) {
	return writePersistedFileAtomic(team, "team", "team.json", `${JSON.stringify(team, null, 2)}\n`, expectedDir);
}

export async function writeGuideAtomic(team, content, expectedDir) {
	return writePersistedFileAtomic(team, "guide", "guide.md", content, expectedDir);
}

// team-worktree.mjs - git worktree provisioning + merge integration for teammode.
//
// Shells out to `git` through node:child_process so the leader never hand-runs worktree or
// merge commands and never improvises a branch name. Zero npm dependencies, like the rest of
// the skill. team-state.mjs stays the pure state model; this file owns the git side only.

import { spawnSync } from "node:child_process";
import { realpathSync } from "node:fs";
import { isAbsolute, join, relative, resolve } from "node:path";

// A member id that also names a directory and a branch segment: no "/", no "..", no leading dot.
const MEMBER_ID_SEGMENT = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;

// Compare two on-disk paths regardless of OS. realpathSync canonicalizes separators, Windows
// 8.3 short names (RUNNER~1) and drive-letter case, and the macOS /var -> /private/var symlink -
// none of which plain resolve() reconciles. Returns false if either side no longer exists.
function samePath(a, b) {
	try {
		return realpathSync(a) === realpathSync(b);
	} catch {
		return false;
	}
}

function git(cwd, args) {
	const result = spawnSync("git", args, { cwd, encoding: "utf8" });
	if (result.error) throw new Error(`git ${args.join(" ")} could not run: ${result.error.message}`);
	return result;
}

function gitOrThrow(cwd, args) {
	const result = git(cwd, args);
	if (result.status !== 0) throw new Error(`git ${args.join(" ")} failed: ${(result.stderr || result.stdout || "").trim()}`);
	return result.stdout ?? "";
}

export function deriveMemberBranch(team, member) {
	if (member.worktree?.branch) return member.worktree.branch;
	return `team/${team.sessionId ?? team.teamId}/${member.id}`;
}

// Confine a member worktree to <worktree.root>/<member id>; reject any id that would escape it.
export function memberWorktreePath(team, member) {
	if (!MEMBER_ID_SEGMENT.test(member.id ?? "")) throw new Error(`unsafe member id for a worktree path: "${member.id}"`);
	const root = team.worktree?.root;
	if (!root) throw new Error("team has no worktree root; re-init the team");
	const path = join(root, member.id);
	const rel = relative(root, path);
	if (rel !== member.id || rel.startsWith("..") || isAbsolute(rel)) throw new Error(`refused: worktree path escapes ${root}`);
	return path;
}

export function listWorktrees(cwd) {
	const out = gitOrThrow(cwd, ["worktree", "list", "--porcelain"]);
	const worktrees = [];
	let current = null;
	for (const line of out.split("\n")) {
		if (line.startsWith("worktree ")) {
			current = { path: line.slice("worktree ".length) };
			worktrees.push(current);
		} else if (line.startsWith("branch ") && current) {
			current.branch = line.slice("branch ".length);
		}
	}
	return worktrees;
}

function branchExists(cwd, branch) {
	return git(cwd, ["rev-parse", "--verify", "--quiet", `refs/heads/${branch}`]).status === 0;
}

function currentBranch(cwd) {
	return gitOrThrow(cwd, ["rev-parse", "--abbrev-ref", "HEAD"]).trim();
}

export function addMemberWorktree(cwd, team, member, { baseBranch } = {}) {
	const base = baseBranch || team.worktree?.baseBranch || "dev";
	const branch = deriveMemberBranch(team, member);
	const path = memberWorktreePath(team, member);
	// Idempotent: skip if a worktree is already checked out on this member's branch (matched on the
	// branch ref, which is OS-agnostic) or already lives at this path (matched on realpath, so a
	// Windows 8.3 git path vs an 8.3-or-long script path still compares equal). Plain string/resolve
	// comparison missed the 8.3-vs-canonical case and re-`git worktree add`-ed into a fatal error.
	if (listWorktrees(cwd).some((w) => w.branch === `refs/heads/${branch}` || samePath(resolve(cwd, w.path), resolve(cwd, path)))) {
		return { path, branch, base, created: false };
	}
	const add = branchExists(cwd, branch)
		? ["worktree", "add", path, branch]
		: ["worktree", "add", "-b", branch, path, base];
	gitOrThrow(cwd, add);
	return { path, branch, base, created: true };
}

export function removeMemberWorktree(cwd, team, member, { force = false } = {}) {
	const path = memberWorktreePath(team, member);
	gitOrThrow(cwd, ["worktree", "remove", ...(force ? ["--force"] : []), path]);
	return { path };
}

// Land a member branch with a MERGE COMMIT (--no-ff). Never squash, never rebase (repo policy).
// On conflict the working tree is left mid-merge so the leader can resolve and re-run.
export function integrateMemberBranch(cwd, branch) {
	const result = git(cwd, ["merge", "--no-ff", "--no-edit", branch]);
	if (result.status === 0) return { branch, merged: true, into: currentBranch(cwd) };
	const conflicts = gitOrThrow(cwd, ["diff", "--name-only", "--diff-filter=U"]).trim();
	return {
		branch,
		merged: false,
		into: currentBranch(cwd),
		conflicts: conflicts ? conflicts.split("\n") : [],
		message: (result.stderr || result.stdout || "").trim(),
	};
}

#!/usr/bin/env node
// team.mjs - the teammode controller CLI. Thin argv dispatch over team-state.mjs (the
// state model) and team-guide.mjs (the member field manual). It replaces hand-written
// team.json / guide.md so the model never has to author those files by hand.
//
// Zero external dependencies (node builtins only): runs identically under node and bun on
// macOS, Linux, and Windows.
//
//   node "<skill-root>/scripts/team.mjs" init        --name "<team>" --session-name "<sess>" [--session <id>] [--worktree] [--base-branch dev]
//   node "<skill-root>/scripts/team.mjs" add-member  --team <id> --id A --name "<short role>" --focus "<part/ownership/perspective>" --lens area|ownership|perspective --deliverable "<...>" [--branch <b>]
//   node "<skill-root>/scripts/team.mjs" bind-thread  --team <id> --id A --thread <thread-id> [--cwd <path>]
//   node "<skill-root>/scripts/team.mjs" member-prompt --team <id> --id A
//   node "<skill-root>/scripts/team.mjs" set-status   --team <id> --id A --status reported|blocked|active|archived [--note "<...>"]
//   node "<skill-root>/scripts/team.mjs" archive      --team <id> [--id A] [--note "<...>"]
//   node "<skill-root>/scripts/team.mjs" delete       --team <id> [--force]
//   node "<skill-root>/scripts/team.mjs" status       --team <id>
//   node "<skill-root>/scripts/team.mjs" guide        --team <id>

import { randomUUID } from "node:crypto";
import { realpathSync } from "node:fs";
import { rm } from "node:fs/promises";
import { fileURLToPath, pathToFileURL } from "node:url";
import { buildGuide, buildMemberPrompt, codexThreadLink } from "./team-guide.mjs";
import {
	addMember,
	archive,
	assertSafeTeamDir,
	bindThread,
	buildTeam,
	clearMemberWorktree,
	ensureTeamDir,
	isUnderstaffed,
	MIN_MEMBERS,
	readTeam,
	setMemberStatus,
	setMemberWorktree,
	teamExists,
	writeGuideAtomic,
	writeTeamAtomic,
} from "./team-state.mjs";
import { addMemberWorktree, integrateMemberBranch, removeMemberWorktree } from "./team-worktree.mjs";

function parseFlags(args) {
	const flags = { _: [] };
	for (let i = 0; i < args.length; i++) {
		const arg = args[i];
		if (!arg.startsWith("--")) {
			flags._.push(arg);
			continue;
		}
		const key = arg.slice(2);
		const next = args[i + 1];
		if (next === undefined || next.startsWith("--")) {
			flags[key] = true;
		} else {
			flags[key] = next;
			i++;
		}
	}
	return flags;
}

function requireFlag(flags, name) {
	const value = flags[name];
	if (value === undefined || value === true) throw new Error(`missing required flag --${name}`);
	return value;
}

async function loadTeam(cwd, sessionId) {
	const dir = await assertSafeTeamDir(cwd, sessionId);
	return { dir, team: await readTeam(dir) };
}

function memberOrThrow(team, id) {
	const member = team.members.find((m) => m.id === id);
	if (!member) throw new Error(`no member with id "${id}"`);
	return member;
}

async function persist(team, dir) {
	await writeTeamAtomic(team, dir);
	await writeGuideAtomic(team, buildGuide(team), dir);
}

const handlers = {
	async init(cwd, flags) {
		const teamName = requireFlag(flags, "name");
		const sessionName = requireFlag(flags, "session-name");
		const sessionId = typeof flags.session === "string" ? flags.session : `team-${randomUUID().slice(0, 8)}`;
		const dir = await ensureTeamDir(cwd, sessionId);
		if (await teamExists(dir)) {
			process.stdout.write(`exists: ${dir} (left untouched; re-init is a safe no-op)\n`);
			return;
		}
		const team = buildTeam({
			teamName,
			sessionName,
			sessionId,
			dir,
			worktreeEnabled: flags.worktree === true,
			baseBranch: typeof flags["base-branch"] === "string" ? flags["base-branch"] : "dev",
		});
		await persist(team, dir);
		process.stdout.write(`created: ${dir}\n`);
		process.stdout.write(`team.json + guide.md written; artifacts/ ready. session id: ${sessionId}\n`);
		process.stdout.write(`next: add-member --team ${sessionId} --id A --name "<short role>" --focus "<part/ownership/perspective>" --lens area|ownership|perspective --deliverable "<...>"\n`);
	},

	async "add-member"(cwd, flags) {
		const sessionId = requireFlag(flags, "team");
		const { dir, team } = await loadTeam(cwd, sessionId);
		const memberId = requireFlag(flags, "id").trim();
		addMember(team, {
			id: memberId,
			name: typeof flags.name === "string" ? flags.name : null,
			focus: requireFlag(flags, "focus"),
			lens: requireFlag(flags, "lens"),
			deliverable: typeof flags.deliverable === "string" ? flags.deliverable : "",
			branch: typeof flags.branch === "string" ? flags.branch : null,
		});
		await persist(team, dir);
		const member = team.members.find((m) => m.id === memberId);
		process.stdout.write(`added member ${memberId} to team ${sessionId}.\n\nSend this as the new thread's first message (title the thread "${member.threadTitle}"):\n---\n${buildMemberPrompt(team, memberId)}\n---\n`);
	},

	async "bind-thread"(cwd, flags) {
		const sessionId = requireFlag(flags, "team");
		const { dir, team } = await loadTeam(cwd, sessionId);
		bindThread(team, {
			id: requireFlag(flags, "id"),
			threadId: requireFlag(flags, "thread"),
			cwd: typeof flags.cwd === "string" ? flags.cwd : null,
			worktreePath: typeof flags["worktree-path"] === "string" ? flags["worktree-path"] : null,
		});
		await persist(team, dir);
		process.stdout.write(`bound member ${flags.id} to thread ${flags.thread}.\n`);
	},

	async "member-prompt"(cwd, flags) {
		const sessionId = requireFlag(flags, "team");
		const { team } = await loadTeam(cwd, sessionId);
		process.stdout.write(`${buildMemberPrompt(team, requireFlag(flags, "id"))}\n`);
	},

	async "set-status"(cwd, flags) {
		const sessionId = requireFlag(flags, "team");
		const { dir, team } = await loadTeam(cwd, sessionId);
		setMemberStatus(team, {
			id: requireFlag(flags, "id"),
			status: requireFlag(flags, "status"),
			note: typeof flags.note === "string" ? flags.note : "",
		});
		await persist(team, dir);
		process.stdout.write(`member ${flags.id} -> ${flags.status}\n`);
	},

	async "worktree-add"(cwd, flags) {
		const sessionId = requireFlag(flags, "team");
		const { dir, team } = await loadTeam(cwd, sessionId);
		const member = memberOrThrow(team, requireFlag(flags, "id"));
		const result = addMemberWorktree(cwd, team, member, {
			baseBranch: typeof flags["base-branch"] === "string" ? flags["base-branch"] : null,
		});
		setMemberWorktree(team, { id: member.id, path: result.path, branch: result.branch });
		await persist(team, dir);
		const note = result.created ? "" : " (already exists)";
		const thread = member.threadId
			? `\nMember thread: ${codexThreadLink(member.threadId)}\nTell that member to: cd "${result.path}"`
			: "\nMember thread is not bound yet; wait for the real Codex thread id, then bind-thread before sending bootstrap. After binding, send the member this worktree path.";
		process.stdout.write(
			`worktree for member ${member.id}${note}: ${result.path} on branch ${result.branch} (off ${result.base}).${thread}\n`,
		);
	},

	async "worktree-remove"(cwd, flags) {
		const sessionId = requireFlag(flags, "team");
		const { dir, team } = await loadTeam(cwd, sessionId);
		const member = memberOrThrow(team, requireFlag(flags, "id"));
		removeMemberWorktree(cwd, team, member, { force: flags.force === true });
		clearMemberWorktree(team, { id: member.id });
		await persist(team, dir);
		process.stdout.write(`removed worktree for member ${member.id}\n`);
	},

	async integrate(cwd, flags) {
		const sessionId = requireFlag(flags, "team");
		const { team } = await loadTeam(cwd, sessionId);
		const targets = typeof flags.id === "string" ? [memberOrThrow(team, flags.id)] : team.members.filter((m) => m.worktree?.branch);
		if (targets.length === 0) throw new Error("no member has a worktree branch to integrate; run worktree-add first");
		for (const member of targets) {
			const result = integrateMemberBranch(cwd, member.worktree.branch);
			if (!result.merged) {
				if (result.conflicts.length > 0) {
					process.stdout.write(`member ${member.id} (${member.worktree.branch}): CONFLICT into ${result.into}\n`);
					throw new Error(
						`merge conflict integrating member ${member.id} (branch ${member.worktree.branch}). Resolve the conflict, commit the merge, then re-run integrate. Conflicting files: ${result.conflicts.join(", ")}`,
					);
				}
				process.stdout.write(`member ${member.id} (${member.worktree.branch}): could not start merge into ${result.into}\n`);
				throw new Error(
					`could not integrate member ${member.id} (branch ${member.worktree.branch}): ${result.message || "git merge failed; see git status"}`,
				);
			}
			process.stdout.write(`member ${member.id} (${member.worktree.branch}): merged into ${result.into}\n`);
		}
		process.stdout.write(`integrated ${targets.length} member branch(es) with merge commits\n`);
	},

	async archive(cwd, flags) {
		const sessionId = requireFlag(flags, "team");
		const { dir, team } = await loadTeam(cwd, sessionId);
		archive(team, {
			id: typeof flags.id === "string" ? flags.id : null,
			note: typeof flags.note === "string" ? flags.note : "",
		});
		await persist(team, dir);
		process.stdout.write(flags.id ? `archived member ${flags.id}\n` : `archived team ${sessionId} and closed all members\n`);
	},

	async delete(cwd, flags) {
		const sessionId = requireFlag(flags, "team");
		const { dir, team } = await loadTeam(cwd, sessionId);
		const active = team.members.filter((m) => m.status !== "archived");
		if (flags.force !== true && (team.status !== "archived" || active.length > 0)) {
			throw new Error(
				`refused: team "${sessionId}" is not archived or still has ${active.length} active member(s). Archive first, or pass --force to delete anyway.`,
			);
		}
		await rm(dir, { recursive: true, force: true });
		process.stdout.write(`deleted team state: ${dir}\n`);
	},

	async status(cwd, flags) {
		const sessionId = requireFlag(flags, "team");
		const { team } = await loadTeam(cwd, sessionId);
		process.stdout.write(`Team ${team.teamName} [${team.status}] - leader: main session - ${team.members.length} member(s)\n`);
		for (const m of team.members) {
			const thread = m.threadId ? ` thread=${m.threadId} link=${codexThreadLink(m.threadId)}` : "";
			process.stdout.write(`  ${m.id} (${m.lens}) ${m.focus} -> ${m.deliverable || "(no deliverable)"} [${m.status}]${thread}${m.cwd ? ` cwd=${m.cwd}` : ""}\n`);
		}
		if (isUnderstaffed(team)) {
			process.stdout.write(
				`WARNING: a team needs at least ${MIN_MEMBERS} members; this team has ${team.members.length}. A single-member team is not a team - add another distinct slice or use a subagent.\n`,
			);
		}
	},

	async guide(cwd, flags) {
		const sessionId = requireFlag(flags, "team");
		const { dir, team } = await loadTeam(cwd, sessionId);
		await writeGuideAtomic(team, buildGuide(team), dir);
		process.stdout.write(`${team.paths.guide}\n`);
	},
};

async function main() {
	const [subcommand, ...rest] = process.argv.slice(2);
	const handler = handlers[subcommand];
	if (!handler) {
		throw new Error(`unknown subcommand "${subcommand ?? ""}" - expected one of: ${Object.keys(handlers).join(", ")}`);
	}
	await handler(process.cwd(), parseFlags(rest));
}

// Symlink-robust main-module check: a symlinked install invokes this file through a symlink
// path while node resolves import.meta.url to the realpath, so compare the resolved real paths
// (falling back to the literal url comparison if a path cannot be resolved).
function isInvokedAsScript() {
	const entry = process.argv[1];
	if (!entry) return false;
	try {
		return realpathSync(fileURLToPath(import.meta.url)) === realpathSync(entry);
	} catch {
		return import.meta.url === pathToFileURL(entry).href;
	}
}

if (isInvokedAsScript()) {
	await main().catch((error) => {
		process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
		process.exit(1);
	});
}

#!/usr/bin/env node

import { runTeammodeHookCli } from "./codex-hook.js";

const [command, subcommand] = process.argv.slice(2);

if (command === "hook" && subcommand === "post-tool-use") {
	await runTeammodeHookCli(process.stdin, process.stdout);
} else {
	process.stderr.write("Usage: omo-teammode hook post-tool-use\n");
	process.exitCode = 2;
}

export interface PostToolUsePayload {
	readonly hook_event_name: "PostToolUse";
	readonly session_id: string;
	readonly turn_id?: string;
	readonly transcript_path?: string | null;
	readonly cwd?: string;
	readonly model?: string;
	readonly permission_mode?: string;
	readonly tool_name: string;
	readonly tool_use_id?: string;
	readonly tool_input: unknown;
	readonly tool_response: unknown;
}

interface PostToolUseHookOutput {
	readonly hookSpecificOutput: {
		readonly hookEventName: "PostToolUse";
		readonly additionalContext: string;
	};
}

type ThreadCreationReference =
	| { readonly kind: "thread"; readonly id: string }
	| { readonly kind: "pendingWorktree"; readonly id: string };

const CREATE_THREAD_TOOL_NAMES = new Set(["create_thread", "codex_app.create_thread"]);

export function parsePostToolUsePayload(raw: string): PostToolUsePayload | null {
	if (raw.trim().length === 0) return null;
	try {
		const parsed: unknown = JSON.parse(raw);
		return isPostToolUsePayload(parsed) ? parsed : null;
	} catch (error) {
		if (error instanceof SyntaxError) return null;
		return null;
	}
}

export function runPostToolUseHook(payload: PostToolUsePayload): string {
	if (payload.hook_event_name !== "PostToolUse") return "";
	if (!CREATE_THREAD_TOOL_NAMES.has(payload.tool_name)) return "";
	const threadReference = extractThreadCreationReference(payload.tool_response);
	if (threadReference === null) return "";
	const output: PostToolUseHookOutput = {
		hookSpecificOutput: {
			hookEventName: "PostToolUse",
			additionalContext: threadTitleReminder(threadReference),
		},
	};
	return `${JSON.stringify(output)}\n`;
}

export async function runTeammodeHookCli(
	stdin: NodeJS.ReadableStream,
	stdout: NodeJS.WritableStream,
): Promise<void> {
	const payload = parsePostToolUsePayload(await readAll(stdin));
	if (payload === null) return;
	const output = runPostToolUseHook(payload);
	if (output.length > 0) stdout.write(output);
}

function threadTitleReminder(threadReference: ThreadCreationReference): string {
	const id = formatIdentifier(threadReference.id);
	return threadReference.kind === "thread"
		? `THREAD ID ${id}: CALL codex_app.set_thread_title NOW. USE THE REAL TASK/ROLE.`
		: `PENDING WORKTREE ID ${id}: WORKTREE THREAD IS NOT READY YET. DO NOT bind-thread OR SEND THE MEMBER BOOTSTRAP UNTIL A REAL THREAD ID EXISTS. THEN CALL codex_app.set_thread_title USING THE REAL TASK/ROLE.`;
}

function formatIdentifier(value: string): string {
	const normalized = value.replace(/\s+/g, " ").trim();
	return normalized.length <= 200 ? normalized : `${normalized.slice(0, 197)}...`;
}

function extractThreadCreationReference(toolResponse: unknown): ThreadCreationReference | null {
	const response = parseToolResponseRecord(toolResponse);
	if (response === null) return null;
	const threadId = response["threadId"];
	if (typeof threadId === "string" && threadId.trim().length > 0) {
		return { kind: "thread", id: threadId };
	}
	const pendingWorktreeId = response["pendingWorktreeId"];
	if (typeof pendingWorktreeId === "string" && pendingWorktreeId.trim().length > 0) {
		return { kind: "pendingWorktree", id: pendingWorktreeId };
	}
	return null;
}

function parseToolResponseRecord(toolResponse: unknown): Record<string, unknown> | null {
	if (isRecord(toolResponse)) return toolResponse;
	if (typeof toolResponse !== "string") return null;
	const trimmed = toolResponse.trim();
	if (trimmed.length === 0) return null;
	try {
		const parsed: unknown = JSON.parse(trimmed);
		return isRecord(parsed) ? parsed : null;
	} catch (error) {
		if (error instanceof SyntaxError) return null;
		return null;
	}
}

function isPostToolUsePayload(value: unknown): value is PostToolUsePayload {
	if (!isRecord(value)) return false;
	return (
		value["hook_event_name"] === "PostToolUse" &&
		typeof value["session_id"] === "string" &&
		typeof value["tool_name"] === "string" &&
		Object.hasOwn(value, "tool_input") &&
		Object.hasOwn(value, "tool_response") &&
		optionalString(value["turn_id"]) &&
		optionalString(value["cwd"]) &&
		optionalString(value["model"]) &&
		optionalString(value["permission_mode"]) &&
		optionalString(value["tool_use_id"]) &&
		(value["transcript_path"] === undefined ||
			value["transcript_path"] === null ||
			typeof value["transcript_path"] === "string")
	);
}

function optionalString(value: unknown): boolean {
	return value === undefined || typeof value === "string";
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

function readAll(stdin: NodeJS.ReadableStream): Promise<string> {
	return new Promise((resolve, reject) => {
		let data = "";
		stdin.setEncoding("utf8");
		stdin.on("data", (chunk: unknown) => {
			data += chunk instanceof Buffer ? chunk.toString() : String(chunk);
		});
		stdin.once("error", reject);
		stdin.once("end", () => resolve(data));
	});
}

