				},
			},
			tool_response: {
				pendingWorktreeId: "remote-control:env:test-worktree",
			},
		});

		// when
		const parsed: unknown = JSON.parse(output);

		// then
		expect(isHookOutput(parsed)).toBe(true);
		if (!isHookOutput(parsed)) return;
