import { essentialCriteriaOf, hasAllCriteriaPass, hasEssentialCriteriaPass } from "./goal-status.js";
import type { UlwLoopScope } from "./paths.js";
import { appendLedger, readUlwLoopPlan, withUlwLoopMutationLock, writePlan } from "./plan-io.js";
import type { UlwLoopItem, UlwLoopLedgerEntry, UlwLoopPlan, UlwLoopSuccessCriterion } from "./types.js";
import { iso, UlwLoopError } from "./types.js";

type EvidenceStatus = "pass" | "fail" | "blocked";
type RecordEvidenceArgs = {
	readonly goalId: string;
	readonly criterionId: string;
	readonly status: EvidenceStatus;
	readonly evidence: string;
	readonly notes?: string;
};

function ulwLoopFail(message: string, code: string, details: Record<string, unknown>): never {
	throw new UlwLoopError(message, code, { details });
}

function ledgerKind(status: EvidenceStatus): UlwLoopLedgerEntry["kind"] {
	switch (status) {
		case "pass":
			return "evidence_captured";
		case "fail":
			return "criterion_failed";
		case "blocked":
			return "criterion_blocked";
		default:
			return ulwLoopFail("Invalid criterion status.", "ULW_LOOP_CRITERION_STATUS_INVALID", { status });
	}
}

function findGoal(plan: UlwLoopPlan, goalId: string): UlwLoopItem {
	const goal = plan.goals.find((candidate) => candidate.id === goalId);
	return goal ?? ulwLoopFail(`UlwLoop goal not found: ${goalId}.`, "ULW_LOOP_GOAL_NOT_FOUND", { goalId });
}

function findCriterion(goal: UlwLoopItem, criterionId: string): UlwLoopSuccessCriterion {
	const criterion = goal.successCriteria.find((candidate) => candidate.id === criterionId);
	return (
		criterion ??
		ulwLoopFail(`Success criterion not found: ${criterionId}.`, "ULW_LOOP_CRITERION_NOT_FOUND", {
			goalId: goal.id,
			criterionId,
		})
	);
}

function nonEmptyEvidence(evidence: string): string {
	const trimmed = evidence.trim();
	return trimmed || ulwLoopFail("Evidence must be a non-empty string.", "ULW_LOOP_EVIDENCE_REQUIRED", {});
}

export async function recordEvidence(
	repoRoot: string,
	args: RecordEvidenceArgs,
	scope?: UlwLoopScope,
): Promise<{
	plan: UlwLoopPlan;
	goal: UlwLoopItem;
	criterion: UlwLoopSuccessCriterion;
	ledgerEntry: UlwLoopLedgerEntry;
}> {
	return withUlwLoopMutationLock(repoRoot, scope, async () => {
		const plan = await readUlwLoopPlan(repoRoot, scope);
		const goal = findGoal(plan, args.goalId);
		const criterion = findCriterion(goal, args.criterionId);
		const evidence = nonEmptyEvidence(args.evidence);
		const kind = ledgerKind(args.status);
		const prevStatus = criterion.status;
		const capturedAt = iso();
		criterion.status = args.status;
		criterion.capturedEvidence = evidence;
		criterion.capturedAt = capturedAt;
		if (args.notes !== undefined) criterion.notes = args.notes;
		goal.updatedAt = capturedAt;
		plan.updatedAt = capturedAt;
		await writePlan(repoRoot, plan, scope);
		const ledgerEntry: UlwLoopLedgerEntry = {
			at: capturedAt,
			kind,
			goalId: goal.id,
			criterionId: criterion.id,
			criterionStatus: args.status,
			evidence,
			capturedEvidence: evidence,
			before: { status: prevStatus },
			after: { goalId: goal.id, criterionId: criterion.id, status: args.status, evidence, capturedAt, prevStatus },
		};
		await appendLedger(repoRoot, ledgerEntry, scope);
		return { plan, goal, criterion, ledgerEntry };
	});
}

export async function markCriteriaPendingResetForGoal(
	repoRoot: string,
	goalId: string,
	scope?: UlwLoopScope,
): Promise<{ plan: UlwLoopPlan; resetCount: number }> {
	return withUlwLoopMutationLock(repoRoot, scope, async () => {
		const plan = await readUlwLoopPlan(repoRoot, scope);
		const goal = findGoal(plan, goalId);
		const now = iso();
		const before = goal.successCriteria.map((criterion) => ({
			id: criterion.id,
			status: criterion.status,
			capturedEvidence: criterion.capturedEvidence,
			capturedAt: criterion.capturedAt ?? null,
		}));
		for (const criterion of goal.successCriteria) {
			criterion.status = "pending";
			criterion.capturedEvidence = null;
			delete criterion.capturedAt;
			delete criterion.notes;
		}
		goal.updatedAt = now;
		plan.updatedAt = now;
		await writePlan(repoRoot, plan, scope);
		await appendLedger(
			repoRoot,
			{
				at: now,
				kind: "criteria_revised",
				goalId,
				message: `Reset ${goal.successCriteria.length} criteria to pending.`,
				before,
				after: { resetCount: goal.successCriteria.length },
			},
			scope,
		);
		return { plan, resetCount: goal.successCriteria.length };
	});
}

export function criteriaSummary(plan: UlwLoopPlan): {
	totalCriteria: number;
	passCount: number;
	pendingCount: number;
	failCount: number;
	blockedCount: number;
	goalsWithUnresolvedCriteria: string[];
} {
	let totalCriteria = 0;
	let passCount = 0;
	let pendingCount = 0;
	let failCount = 0;
	let blockedCount = 0;
	const goalsWithUnresolvedCriteria: string[] = [];
	for (const goal of plan.goals) {
		let unresolved = false;
		for (const criterion of goal.successCriteria) {
			totalCriteria += 1;
			if (criterion.status !== "pass") unresolved = true;
			switch (criterion.status) {
				case "pass":
					passCount += 1;
					break;
				case "pending":
					pendingCount += 1;
					break;
				case "fail":
					failCount += 1;
					break;
				case "blocked":
					blockedCount += 1;
					break;
				default:
					ulwLoopFail("Invalid criterion status.", "ULW_LOOP_CRITERION_STATUS_INVALID", {
						status: criterion.status,
					});
			}
		}
		if (unresolved) goalsWithUnresolvedCriteria.push(goal.id);
	}
	return { totalCriteria, passCount, pendingCount, failCount, blockedCount, goalsWithUnresolvedCriteria };
}

export function unresolvedCriteriaOf(goal: UlwLoopItem): UlwLoopSuccessCriterion[] {
	return goal.successCriteria.filter((criterion) => criterion.status !== "pass");
}

export function unresolvedEssentialCriteriaOf(goal: UlwLoopItem): readonly UlwLoopSuccessCriterion[] {
	const essentialCriteria = new Set(essentialCriteriaOf(goal).map((criterion) => criterion.id));
	return goal.successCriteria.filter(
		(criterion) => essentialCriteria.has(criterion.id) && criterion.status !== "pass",
	);
}

export function requireAllCriteriaPass(goal: UlwLoopItem): void {
	if (hasAllCriteriaPass(goal)) return;
	throw new UlwLoopError(`Goal ${goal.id} has unresolved success criteria.`, "ulw_loop_criteria_not_all_pass", {
		details: {
			goalId: goal.id,
			unresolved: unresolvedCriteriaOf(goal).map((criterion) => ({ id: criterion.id, status: criterion.status })),
		},
	});
}

export function requireAllPlanCriteriaPass(plan: UlwLoopPlan): void {
	const unresolved = plan.goals.flatMap((goal) =>
		unresolvedCriteriaOf(goal).map((criterion) => ({
			goalId: goal.id,
			id: criterion.id,
			status: criterion.status,
		})),
	);
	if (unresolved.length === 0) return;
	throw new UlwLoopError("Ulw-loop aggregate has unresolved success criteria.", "ulw_loop_criteria_not_all_pass", {
		details: { unresolved },
	});
}

export function requireEssentialCriteriaPass(goal: UlwLoopItem): void {
	if (hasEssentialCriteriaPass(goal)) return;
	throw new UlwLoopError(
		`Goal ${goal.id} has unresolved essential success criteria.`,
		"ulw_loop_criteria_not_all_pass",
		{
			details: {
				goalId: goal.id,
				unresolved: unresolvedEssentialCriteriaOf(goal).map((criterion) => ({
					id: criterion.id,
					status: criterion.status,
				})),
			},
		},
	);
}

import { type UlwLoopScope, ulwLoopGoalsRelativePath, ulwLoopLedgerRelativePath } from "./paths.js";
import type {
	UlwLoopCodexGoalMode,
	UlwLoopItem,
	UlwLoopPlan,
	UlwLoopStatus,
	UlwLoopSuccessCriterion,
} from "./types.js";

export const ULW_LOOP_AGGREGATE_CODEX_OBJECTIVE: string = aggregateCodexObjectiveForScope();

export function aggregateCodexObjectiveForScope(scope?: UlwLoopScope): string {
	return `Complete the durable ulw-loop plan in ${ulwLoopGoalsRelativePath(scope)}, including later accepted/appended stories, under the original brief constraints; use ${ulwLoopLedgerRelativePath(scope)} as the audit trail.`;
}

export function codexGoalMode(plan: UlwLoopPlan): UlwLoopCodexGoalMode {
	return plan.codexGoalMode ?? "per_story";
}

function isResolvedStatus(status: UlwLoopStatus): boolean {
	return status === "complete";
}

function isSupersededResolved(goal: UlwLoopItem, plan: UlwLoopPlan): boolean {
	if (goal.steeringStatus !== "superseded") return false;
	const replacements = goal.supersededBy ?? [];
	if (replacements.length === 0) return false;
	return replacements.every((id) => {
		const replacement = plan.goals.find((candidate) => candidate.id === id);
		return replacement !== undefined && isResolvedStatus(replacement.status);
	});
}

function isCompletionBlocking(goal: UlwLoopItem, plan: UlwLoopPlan): boolean {
	if (goal.steeringStatus === "superseded") return !isSupersededResolved(goal, plan);
	if (goal.steeringStatus === "blocked") return true;
	return !isResolvedStatus(goal.status);
}

function isCompletionBlockingForFinalCandidate(
	candidate: UlwLoopItem,
	finalCandidate: UlwLoopItem,
	plan: UlwLoopPlan,
): boolean {
	if (candidate.id === finalCandidate.id) return false;
	if (candidate.steeringStatus === "superseded") {
		const replacements = candidate.supersededBy ?? [];
		if (replacements.length === 0) return true;
		return !replacements.every((id) => {
			if (id === finalCandidate.id) return true;
			const replacement = plan.goals.find((goal) => goal.id === id);
			return replacement !== undefined && isResolvedStatus(replacement.status);
		});
	}
	return isCompletionBlocking(candidate, plan);
}

export function isUlwLoopDone(plan: UlwLoopPlan): boolean {
	if (plan.aggregateCompletion?.status === "complete") return true;
	return plan.goals.every((goal) => !isCompletionBlocking(goal, plan));
}

export function isFinalRunCompletionCandidate(plan: UlwLoopPlan, goal: UlwLoopItem): boolean {
	return (
		isCompletionBlocking(goal, plan) &&
		plan.goals.every((candidate) => !isCompletionBlockingForFinalCandidate(candidate, goal, plan))
	);
}

export function aggregateCodexObjective(plan: UlwLoopPlan): string {
	return plan.codexObjective ?? ULW_LOOP_AGGREGATE_CODEX_OBJECTIVE;
}

export function expectedCodexObjective(plan: UlwLoopPlan, goal: UlwLoopItem): string {
	return codexGoalMode(plan) === "aggregate" ? aggregateCodexObjective(plan) : goal.objective;
}

export function compatibleCodexObjectives(plan: UlwLoopPlan): readonly string[] {
	return [aggregateCodexObjective(plan), ...(plan.codexObjectiveAliases ?? [])];
}

export function hasAllCriteriaPass(goal: UlwLoopItem): boolean {
	return goal.successCriteria.length > 0 && goal.successCriteria.every((criterion) => criterion.status === "pass");
}

export function isEssentialCriterion(criterion: UlwLoopSuccessCriterion): boolean {
	return criterion.essential ?? true;
}

export function essentialCriteriaOf(goal: UlwLoopItem): readonly UlwLoopSuccessCriterion[] {
	const explicit = goal.successCriteria.filter(isEssentialCriterion);
	if (explicit.length > 0) return explicit;
	const happy = goal.successCriteria.find((criterion) => criterion.userModel === "happy");
	return happy === undefined ? [] : [happy];
}

export function hasEssentialCriteriaPass(goal: UlwLoopItem): boolean {
	const criteria = essentialCriteriaOf(goal);
	return criteria.length > 0 && criteria.every((criterion) => criterion.status === "pass");
}

export function firstUnresolvedCriterion(goal: UlwLoopItem): UlwLoopSuccessCriterion | undefined {
	return goal.successCriteria.find((criterion) => criterion.status !== "pass");
}

import { join } from "node:path";
import { ULW_LOOP_BRIEF, ULW_LOOP_DIR, ULW_LOOP_GOALS, ULW_LOOP_LEDGER } from "./types.js";

export interface UlwLoopScope {
	readonly sessionId?: string | null;
}

const SESSION_ENV_KEYS = ["OMO_ULW_LOOP_SESSION_ID", "CODEX_SESSION_ID", "CODEX_THREAD_ID"] as const;
type EnvMap = Readonly<Record<string, string | undefined>>;

export function normalizeUlwLoopSessionId(sessionId: string | null | undefined): string | null {
	const trimmed = sessionId?.trim();
	if (!trimmed) return null;
	const pathSegments = trimmed
		.split(/[\\/]+/)
		.filter((segment) => segment.length > 0 && segment !== "." && segment !== "..");
	const candidate = (pathSegments.length > 0 ? pathSegments.join("-") : trimmed)
		.replace(/[^A-Za-z0-9._-]+/g, "-")
		.replace(/-+/g, "-")
		.replace(/^\.+/, "")
		.replace(/^[.-]+|[.-]+$/g, "");
	return candidate.length > 0 ? candidate : null;
}

export function resolveUlwLoopSessionIdFromEnv(env: EnvMap = process.env): string | null {
	for (const key of SESSION_ENV_KEYS) {
		const normalized = normalizeUlwLoopSessionId(env[key]);
		if (normalized !== null) return normalized;
	}
	return null;
}

export function ulwLoopRelativeDir(scope?: UlwLoopScope): string {
	const sessionId = normalizeUlwLoopSessionId(scope?.sessionId);
	return sessionId === null ? ULW_LOOP_DIR : `${ULW_LOOP_DIR}/${sessionId}`;
}

export function ulwLoopDir(repoRoot: string, scope?: UlwLoopScope): string {
	return join(repoRoot, ulwLoopRelativeDir(scope));
}

export function ulwLoopBriefRelativePath(scope?: UlwLoopScope): string {
	return `${ulwLoopRelativeDir(scope)}/${ULW_LOOP_BRIEF}`;
}

export function ulwLoopGoalsRelativePath(scope?: UlwLoopScope): string {
	return `${ulwLoopRelativeDir(scope)}/${ULW_LOOP_GOALS}`;
}

export function ulwLoopLedgerRelativePath(scope?: UlwLoopScope): string {
	return `${ulwLoopRelativeDir(scope)}/${ULW_LOOP_LEDGER}`;
}

export function ulwLoopBriefPath(repoRoot: string, scope?: UlwLoopScope): string {
	return join(ulwLoopDir(repoRoot, scope), ULW_LOOP_BRIEF);
}

export function ulwLoopGoalsPath(repoRoot: string, scope?: UlwLoopScope): string {
	return join(ulwLoopDir(repoRoot, scope), ULW_LOOP_GOALS);
}

export function ulwLoopLedgerPath(repoRoot: string, scope?: UlwLoopScope): string {
	return join(ulwLoopDir(repoRoot, scope), ULW_LOOP_LEDGER);
}

export function repoRelative(absolutePath: string, repoRoot: string): string {
	const slashPrefix = `${repoRoot}/`;
	const backslashPrefix = `${repoRoot}\\`;
	if (absolutePath.startsWith(slashPrefix)) return absolutePath.slice(slashPrefix.length).split("\\").join("/");
	if (absolutePath.startsWith(backslashPrefix))
		return absolutePath.slice(backslashPrefix.length).split("\\").join("/");
	return absolutePath.split("\\").join("/");
}

import { existsSync } from "node:fs";
import { mkdir, writeFile } from "node:fs/promises";

import { aggregateCodexObjectiveForScope, isUlwLoopDone } from "./goal-status.js";
import {
	type UlwLoopScope,
	ulwLoopBriefPath,
	ulwLoopBriefRelativePath,
	ulwLoopDir,
	ulwLoopGoalsPath,
	ulwLoopGoalsRelativePath,
	ulwLoopLedgerPath,
	ulwLoopLedgerRelativePath,
} from "./paths.js";
import { appendGoalToPlan, deriveGoalCandidates, makeGoal } from "./plan-goal-factory.js";
import { appendLedger, readUlwLoopPlan, withUlwLoopMutationLock, writePlan } from "./plan-io.js";
import type { UlwLoopCodexGoalMode, UlwLoopItem, UlwLoopPlan, UlwLoopSuccessCriterion } from "./types.js";
import { iso, UlwLoopError } from "./types.js";

export { deriveGoalCandidates, seedDefaultSuccessCriteria } from "./plan-goal-factory.js";

export type UlwLoopPlanSummary = {
	readonly total: number;
	readonly pending: number;
	readonly in_progress: number;
	readonly complete: number;
	readonly failed: number;
	readonly blocked: number;
	readonly review_blocked: number;
	readonly needs_user_decision: number;
	readonly superseded: number;
	readonly criteria: {
		readonly total: number;
		readonly pass: number;
		readonly pending: number;
		readonly fail: number;
		readonly blocked: number;
	};
};

function isScheduleEligible(goal: UlwLoopItem): boolean {
	return goal.steeringStatus !== "superseded" && goal.steeringStatus !== "blocked";
}

function clearGoalBlockerFields(goal: UlwLoopItem): void {
	for (const key of [
		"blockedReason",
		"blockerSignature",
		"blockerOccurrenceCount",
		"requiredExternalDecision",
		"nonRetriable",
		"failedAt",
		"failureReason",
	] as const)
		delete goal[key];
}

export async function createUlwLoopPlan(
	repoRoot: string,
	args: { brief: string; codexGoalMode?: UlwLoopCodexGoalMode; force?: boolean },
	scope?: UlwLoopScope,
): Promise<UlwLoopPlan> {
	return withUlwLoopMutationLock(repoRoot, scope, async () => {
		if (!args.force && existsSync(ulwLoopGoalsPath(repoRoot, scope))) {
			const existing = await readUlwLoopPlan(repoRoot, scope);
			if (isUlwLoopDone(existing)) throw completedPlanExistsError(scope);
			throw new UlwLoopError(
				`Refusing to overwrite existing ${ulwLoopGoalsRelativePath(scope)}; pass --force to recreate it.`,
				"ULW_LOOP_PLAN_EXISTS",
			);
		}
		const now = iso();
		const goals = deriveGoalCandidates(args.brief).map((goal, index) =>
			makeGoal(goal.title, goal.objective, index, now),
		);
		const plan: UlwLoopPlan = {
			version: 1,
			createdAt: now,
			updatedAt: now,
			briefPath: ulwLoopBriefRelativePath(scope),
			goalsPath: ulwLoopGoalsRelativePath(scope),
			ledgerPath: ulwLoopLedgerRelativePath(scope),
			codexGoalMode: args.codexGoalMode ?? "aggregate",
			goals,
		};
		if (plan.codexGoalMode === "aggregate") plan.codexObjective = aggregateCodexObjectiveForScope(scope);
		await mkdir(ulwLoopDir(repoRoot, scope), { recursive: true });
		await writeFile(
			ulwLoopBriefPath(repoRoot, scope),
			args.brief.endsWith("\n") ? args.brief : `${args.brief}\n`,
			"utf8",
		);
		await writePlan(repoRoot, plan, scope);
		await writeFile(ulwLoopLedgerPath(repoRoot, scope), "", "utf8");
		await appendLedger(
			repoRoot,
			{ at: now, kind: "plan_created", message: `${goals.length} goal(s) created` },
			scope,
		);
		return plan;
	});
}

function completedPlanExistsError(scope?: UlwLoopScope): UlwLoopError {
	return new UlwLoopError(
		[
			`Existing ulw-loop aggregate is already complete at ${ulwLoopGoalsRelativePath(scope)}.`,
			"Start a new run with `omo ulw-loop create-goals --session-id <new-id> ...` to isolate fresh state.",
			"Use --force only when you intentionally want to overwrite the completed evidence.",
		].join(" "),
		"ULW_LOOP_PLAN_EXISTS_COMPLETE",
	);
}

export async function addUlwLoopGoal(
	repoRoot: string,
	args: { title: string; objective: string },
	scope?: UlwLoopScope,
): Promise<{ plan: UlwLoopPlan; goal: UlwLoopItem }> {
	return withUlwLoopMutationLock(repoRoot, scope, async () => {
		const plan = await readUlwLoopPlan(repoRoot, scope);
		const now = iso();
		const goal = appendGoalToPlan(plan, args.title, args.objective, now);
		await writePlan(repoRoot, plan, scope);
		await appendLedger(
			repoRoot,
			{ at: now, kind: "goal_added", goalId: goal.id, status: goal.status, message: goal.title },
			scope,
		);
		return { plan, goal };
	});
}

export async function startNextUlwLoop(
	repoRoot: string,
	args: { retryFailed?: boolean } = {},
	scope?: UlwLoopScope,
): Promise<{ plan: UlwLoopPlan; goal: UlwLoopItem; resumed: boolean } | { done: true; plan: UlwLoopPlan }> {
	return withUlwLoopMutationLock(repoRoot, scope, async () => {
		const plan = await readUlwLoopPlan(repoRoot, scope);
		const now = iso();
		if (plan.aggregateCompletion?.status === "complete") return { done: true, plan };
		const existing = plan.goals.find((goal) => goal.status === "in_progress" && isScheduleEligible(goal));
		if (existing) return { plan, goal: existing, resumed: true };
		let next = plan.goals.find((goal) => goal.status === "pending" && isScheduleEligible(goal));
		if (!next && args.retryFailed) {
			next = plan.goals.find((goal) => goal.status === "failed" && !goal.nonRetriable && isScheduleEligible(goal));
			if (next)
				await appendLedger(
					repoRoot,
					{
						at: now,
						kind: "goal_retried",
						goalId: next.id,
						status: "pending",
						...(next.failureReason ? { message: next.failureReason } : {}),
					},
					scope,
				);
		}
		if (!next) return { done: true, plan };
		next.status = "in_progress";
		next.attempt += 1;
		next.startedAt = now;
		clearGoalBlockerFields(next);
		next.updatedAt = now;
		plan.activeGoalId = next.id;
		plan.updatedAt = now;
		await writePlan(repoRoot, plan, scope);
		await appendLedger(
			repoRoot,
			{ at: now, kind: "goal_started", goalId: next.id, status: next.status, message: `Attempt ${next.attempt}` },
			scope,
		);
		return { plan, goal: next, resumed: false };
	});
}

export function summarizeUlwLoopPlan(plan: UlwLoopPlan): UlwLoopPlanSummary {
	const countStatus = (status: UlwLoopItem["status"]): number =>
		plan.goals.filter((goal) => goal.status === status).length;
	const countCriteria = (status: UlwLoopSuccessCriterion["status"]): number =>
		plan.goals.reduce(
			(sum, goal) => sum + goal.successCriteria.filter((criterion) => criterion.status === status).length,
			0,
		);
	return {
		total: plan.goals.length,
		pending: countStatus("pending"),
		in_progress: countStatus("in_progress"),
		complete: countStatus("complete"),
		failed: countStatus("failed"),
		blocked: countStatus("blocked"),
		review_blocked: countStatus("review_blocked"),
		needs_user_decision: countStatus("needs_user_decision"),
		superseded: plan.goals.filter((goal) => goal.steeringStatus === "superseded").length,
		criteria: {
			total: plan.goals.reduce((sum, goal) => sum + goal.successCriteria.length, 0),
			pass: countCriteria("pass"),
			pending: countCriteria("pending"),
			fail: countCriteria("fail"),
			blocked: countCriteria("blocked"),
		},
	};
}

import type { UlwLoopItem, UlwLoopPlan, UlwLoopSuccessCriterion } from "./types.js";
import { UlwLoopError } from "./types.js";

function cleanLine(line: string): string {
	return line.replace(/^\s*(?:[-*+]\s+|\d+[.)]\s+)/, "").trim();
}

function normalizeObjective(value: string): string {
	return value.replace(/\s+/g, " ").trim();
}

function titleFromObjective(objective: string, fallback: string): string {
	const firstLine =
		objective
			.split(/\r?\n/)
			.map((line) => line.trim())
			.find(Boolean) ?? fallback;
	return firstLine.length > 72 ? `${firstLine.slice(0, 69).trimEnd()}...` : firstLine;
}

function normalizeGoalId(title: string, index: number): string {
	const slug = title
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, "-")
		.replace(/^-+|-+$/g, "")
		.slice(0, 36)
		.replace(/-+$/g, "");
	return `G${String(index + 1).padStart(3, "0")}${slug ? `-${slug}` : ""}`;
}

function assertNonEmpty(value: string | undefined, label: string): string {
	const trimmed = value?.trim();
	if (!trimmed) throw new UlwLoopError(`Missing ${label}.`, "ULW_LOOP_ARGUMENT_MISSING");
	return trimmed;
}

function truncateObjective(objective: string): string {
	return objective.length > 80 ? `${objective.slice(0, 77).trimEnd()}...` : objective;
}

export function seedDefaultSuccessCriteria(goalIndex: number, objective: string): UlwLoopSuccessCriterion[] {
	const subject = truncateObjective(normalizeObjective(objective) || `Goal ${goalIndex + 1}`);
	const rows = [
		[
			"C001",
			"happy",
			`happy path for: ${subject}`,
			`Replace via revise_criterion with observable happy-path proof for goal ${goalIndex + 1}.`,
			true,
		],
		[
			"C002",
			"edge",
			"edge case (boundary/empty/malformed)",
			`Replace via revise_criterion with boundary or malformed-input proof for: ${subject}.`,
			true,
		],
		[
			"C003",
			"regression",
			"regression: adjacent surface still works",
			`Replace via revise_criterion with regression proof for neighboring behavior after: ${subject}.`,
			false,
		],
	] as const;
	return rows.map(([id, userModel, scenario, expectedEvidence, essential]) => ({
		id,
		scenario,
		userModel,
		expectedEvidence,
		essential,
		capturedEvidence: null,
		status: "pending",
	}));
}

export function deriveGoalCandidates(brief: string): Array<{ title: string; objective: string }> {
	const bulletGoals = brief
		.split(/\r?\n/)
		.map((line) => ({ original: line, cleaned: normalizeObjective(cleanLine(line)) }))
		.filter(({ cleaned }) => cleaned.length > 0 && cleaned.length <= 1200)
		.filter(
			({ original, cleaned }, index, all) =>
				/^\s*(?:[-*+]\s+|\d+[.)]\s+)/.test(original) &&
				all.findIndex((candidate) => candidate.cleaned === cleaned) === index,
		)
		.map(({ cleaned }) => cleaned);
	const paragraphs = brief
		.split(/\n\s*\n/)
		.map(normalizeObjective)
		.filter((paragraph) => paragraph.length > 0 && !paragraph.startsWith("#"));
	const selected =
		(bulletGoals.length > 0 ? bulletGoals : paragraphs).length > 0
			? bulletGoals.length > 0
				? bulletGoals
				: paragraphs
			: ["Complete the requested project objective."];
	return selected.map((objective, index) => ({
		title: titleFromObjective(objective, `Goal ${index + 1}`),
		objective,
	}));
}

export function makeGoal(title: string, objective: string, index: number, now: string): UlwLoopItem {
	const cleanTitle = assertNonEmpty(title, "title");
	const cleanObjective = assertNonEmpty(objective, "objective");
	return {
		id: normalizeGoalId(cleanTitle, index),
		title: cleanTitle,
		objective: cleanObjective,
		status: "pending",
		successCriteria: seedDefaultSuccessCriteria(index, cleanObjective),
		attempt: 0,
		createdAt: now,
		updatedAt: now,
	};
}

export function appendGoalToPlan(plan: UlwLoopPlan, title: string, objective: string, now: string): UlwLoopItem {
	const goal = makeGoal(title, objective, plan.goals.length, now);
	plan.goals.push(goal);
	plan.updatedAt = now;
	return goal;
}

import { appendFile, mkdir, readFile, rename, writeFile } from "node:fs/promises";

import { aggregateCodexObjectiveForScope } from "./goal-status.js";
import {
	repoRelative,
	type UlwLoopScope,
	ulwLoopDir,
	ulwLoopGoalsPath,
	ulwLoopLedgerPath,
	ulwLoopRelativeDir,
} from "./paths.js";
import type { UlwLoopLedgerEntry, UlwLoopPlan } from "./types.js";
import { iso, ULW_LOOP_DIR, ULW_LOOP_GOALS, ULW_LOOP_LEDGER, UlwLoopError } from "./types.js";

const LEGACY_OBJECTIVE_PREFIX = `Complete all ulw-loop stories in ${ULW_LOOP_DIR}/${ULW_LOOP_GOALS}: `;
const LEGACY_OBJECTIVE = `Complete all ulw-loop stories listed in ${ULW_LOOP_DIR}/${ULW_LOOP_GOALS}. Use ${ULW_LOOP_DIR}/${ULW_LOOP_LEDGER} as the durable audit trail.`;
const locks = new Map<string, Promise<unknown>>();

function hasCode(error: unknown, code: string): boolean {
	return error instanceof Error && "code" in error && error.code === code;
}

function isLegacyEnumeratedAggregateObjective(objective: string | undefined): objective is string {
	return objective === LEGACY_OBJECTIVE || Boolean(objective?.startsWith(LEGACY_OBJECTIVE_PREFIX));
}

function isSteeringKind(value: unknown): value is UlwLoopLedgerEntry["kind"] {
	return value === "steering_accepted" || value === "steering_rejected" || value === "criteria_revised";
}

export async function withUlwLoopMutationLock<T>(repoRoot: string, fn: () => Promise<T>): Promise<T>;
export async function withUlwLoopMutationLock<T>(
	repoRoot: string,
	scope: UlwLoopScope | undefined,
	fn: () => Promise<T>,
): Promise<T>;
export async function withUlwLoopMutationLock<T>(
	repoRoot: string,
	scopeOrFn: UlwLoopScope | (() => Promise<T>) | undefined,
	maybeFn?: () => Promise<T>,
): Promise<T> {
	const scope = typeof scopeOrFn === "function" ? undefined : scopeOrFn;
	const fn = typeof scopeOrFn === "function" ? scopeOrFn : maybeFn;
	if (fn === undefined) throw new UlwLoopError("Missing ulw-loop mutation body.", "ULW_LOOP_LOCK_BODY_MISSING");
	const lockKey = `${repoRoot}\0${ulwLoopRelativeDir(scope)}`;
	const prior = locks.get(lockKey) ?? Promise.resolve();
	const run = prior.then(fn, fn);
	locks.set(
		lockKey,
		run.catch(() => undefined),
	);
	return run;
}

export async function readUlwLoopPlan(repoRoot: string, scope?: UlwLoopScope): Promise<UlwLoopPlan> {
	const path = ulwLoopGoalsPath(repoRoot, scope);
	let raw: string;
	try {
		raw = await readFile(path, "utf8");
	} catch (error) {
		if (!hasCode(error, "ENOENT")) throw error;
		throw new UlwLoopError(
			`No ulw-loop plan found at ${repoRelative(path, repoRoot)}. Run \`omo ulw-loop create-goals ...\` first.`,
			"ULW_LOOP_PLAN_MISSING",
			{ cause: error },
		);
	}
	const parsed: UlwLoopPlan = JSON.parse(raw);
	if (parsed.version !== 1 || !Array.isArray(parsed.goals)) {
		throw new UlwLoopError(`Invalid ulw-loop plan at ${repoRelative(path, repoRoot)}.`, "ULW_LOOP_PLAN_INVALID");
	}
	const previousObjective = parsed.codexObjective;
	if (
		(parsed.codexGoalMode ?? "per_story") === "aggregate" &&
		isLegacyEnumeratedAggregateObjective(previousObjective)
	) {
		const now = iso();
		parsed.codexObjective = aggregateCodexObjectiveForScope(scope);
		parsed.codexObjectiveAliases = [...new Set([...(parsed.codexObjectiveAliases ?? []), previousObjective])];
		parsed.updatedAt = now;
		await writePlan(repoRoot, parsed, scope);
		await appendLedger(
			repoRoot,
			{
				at: now,
				kind: "aggregate_objective_migrated",
				message: "Migrated legacy enumerated aggregate Codex objective to the stable pointer objective.",
				before: { codexObjective: previousObjective },
				after: { codexObjective: parsed.codexObjective },
			},
			scope,
		);
	}
	return parsed;
}

export async function writePlan(repoRoot: string, plan: UlwLoopPlan, scope?: UlwLoopScope): Promise<void> {
	await mkdir(ulwLoopDir(repoRoot, scope), { recursive: true });
	const path = ulwLoopGoalsPath(repoRoot, scope);
	const tmpPath = `${path}.${process.pid}.${Date.now()}.tmp`;
	await writeFile(tmpPath, `${JSON.stringify(plan, null, 2)}\n`, "utf8");
	await rename(tmpPath, path);
}

export async function appendLedger(repoRoot: string, entry: UlwLoopLedgerEntry, scope?: UlwLoopScope): Promise<void> {
	await mkdir(ulwLoopDir(repoRoot, scope), { recursive: true });
	await appendFile(ulwLoopLedgerPath(repoRoot, scope), `${JSON.stringify(entry)}\n`, "utf8");
}

export async function readSteeringLedgerEntries(repoRoot: string, scope?: UlwLoopScope): Promise<UlwLoopLedgerEntry[]> {
	let raw: string;
	try {
		raw = await readFile(ulwLoopLedgerPath(repoRoot, scope), "utf8");
	} catch (error) {
		if (hasCode(error, "ENOENT")) return [];
		throw error;
	}
	const entries: UlwLoopLedgerEntry[] = [];
	for (const line of raw.split(/\r?\n/).filter(Boolean)) {
		const entry: UlwLoopLedgerEntry = JSON.parse(line);
		if (isSteeringKind(entry.kind)) entries.push(entry);
	}
	return entries;
}

import type { UlwLoopItem, UlwLoopPlan } from "./types.js";

const BLOCKER_FIELD_KEYS = "blocker blockerSignature blockerEvidence blockerOccurrences blockedAt".split(" ");
const URL_PATTERN = /https?:\/\/\S+/g;
const PUNCTUATION_PATTERN = /[`"'()[\]{}:,;]/g;
const WHITESPACE_PATTERN = /\s+/g;
const AUTH_PATTERN = /\b(auth\w*|credential\w*|token|permission\w*|scope\w*|access|unauthorized|forbidden|401|403)\b/;
const MISSING_PATTERN =
	/\b(unset|missing|required|requires|without|omit\w*|not set|not available|no read packages|read packages)\b/;
const GHCR_PATTERN =
	/\b(ghcr|github container registry|read packages|imagepullsecret|package api|anonymous|container image)\b/;
const GHCR_401_PATTERN = /\b(401|unauthorized|anonymous pull|authentication required)\b/;
const GHCR_403_PATTERN = /\b(403|forbidden|read packages|package api)\b/;

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function normalizeBlockerEvidence(evidence: string): string {
	const withoutUrls = evidence.toLowerCase().replace(URL_PATTERN, " ");
	const withoutPunctuation = withoutUrls.replace(PUNCTUATION_PATTERN, " ");
	return withoutPunctuation.replace(WHITESPACE_PATTERN, " ").trim();
}

export function classifyExternalAuthorizationBlocker(evidence: string): string | null {
	const normalized = normalizeBlockerEvidence(evidence);
	if (!normalized || !AUTH_PATTERN.test(normalized) || !MISSING_PATTERN.test(normalized)) return null;
	if (!GHCR_PATTERN.test(normalized)) return "EXTERNAL_AUTHORIZATION_REQUIRED";
	const status401 = GHCR_401_PATTERN.test(normalized) ? "HTTP_401_ANONYMOUS" : null;
	const status403 = GHCR_403_PATTERN.test(normalized) ? "HTTP_403_NO_READ_PACKAGES" : null;
	const status = [status401, status403].filter((part): part is string => part !== null).join("+");
	return `GHCR_PULL_ACCESS:${status || "AUTHORIZATION_REQUIRED"}:GHCR_VISIBILITY_OR_CREDENTIAL_REQUIRED`;
}

function nestedBlockerSignature(goal: UlwLoopItem): string | null {
	const blocker = Reflect.get(goal, "blocker");
	const signature = isRecord(blocker) ? blocker["signature"] : null;
	return typeof signature === "string" ? signature : null;
}

export function sameBlockerOccurrences(plan: UlwLoopPlan, signature: string): number {
	return plan.goals.filter((goal) => goal.blockerSignature === signature || nestedBlockerSignature(goal) === signature)
		.length;
}

export function clearGoalBlockerFields(goal: UlwLoopItem): void {
	for (const key of BLOCKER_FIELD_KEYS) Reflect.deleteProperty(goal, key);
}

import { UlwLoopError } from "./types.js";

const PLACEHOLDER_PATTERN = /^(?:placeholder|todo|tbd|n\/a|stub)$/i;

export function invalid(message: string, field: string): never {
	throw new UlwLoopError(message, "ULW_LOOP_QUALITY_GATE_INVALID", { details: { field } });
}

export function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function section(value: unknown, field: string): Record<string, unknown> {
	return isRecord(value) ? value : invalid(`Final quality gate is missing ${field} evidence.`, field);
}

export function textField(value: unknown, field: string): string {
	if (typeof value !== "string" || value.trim() === "")
		invalid(`Final quality gate requires non-empty ${field}.`, field);
	const trimmed = value.trim();
	if (PLACEHOLDER_PATTERN.test(trimmed)) invalid(`Final quality gate rejects placeholder ${field}.`, field);
	return trimmed;
}

export function numberField(value: unknown, field: string): number {
	return typeof value === "number" && Number.isFinite(value)
		? value
		: invalid(`Final quality gate requires numeric ${field}.`, field);
}

export function stringArray(value: unknown, field: string): readonly string[] {
	if (!Array.isArray(value) || value.length === 0) return invalid(`Final quality gate requires ${field}.`, field);
	return value.map((item) => textField(item, field));
}

export function emptyBlockers(value: unknown, field: string): readonly [] {
	if (Array.isArray(value) && value.length === 0) return [];
	invalid(`${field} must be empty.`, field);
}

export function literal<T extends string | boolean>(value: unknown, expected: T, field: string): T {
	if (value === expected) return expected;
	invalid(`${field} must be ${String(expected)}.`, field);
}

import { resolve } from "node:path";
import {
	emptyBlockers,
	invalid,
	literal,
	numberField,
	section,
	stringArray,
	textField,
} from "./quality-gate-fields.js";
import type {
	UlwLoopManualQaArtifactKind,
	UlwLoopManualQaArtifactRef,
	UlwLoopManualQaSurface,
	UlwLoopQualityGate,
} from "./types.js";

const REVIEWER_ROLES = {
	codeReview: "lazycodex-code-reviewer",
	manualQa: "lazycodex-qa-executor",
	gateReview: "lazycodex-gate-reviewer",
} as const;

export {
	classifyExternalAuthorizationBlocker,
	clearGoalBlockerFields,
	normalizeBlockerEvidence,
	sameBlockerOccurrences,
} from "./quality-gate-blockers.js";

export interface QualityGateFs {
	readonly existsSync: (path: string) => boolean;
	readonly statSync: (path: string) => { readonly size: number };
}

export interface ValidateQualityGateOptions {
	readonly repoRoot: string;
	readonly fs: QualityGateFs;
}

function reviewerRoleField<T extends string>(value: unknown, expected: T, field: string): T {
	const actual = textField(value, field);
	if (actual !== expected) invalid(`${field} must be ${expected}.`, field);
	return expected;
}

function surfaceField(value: unknown, field: string): UlwLoopManualQaSurface {
	if (
		value === "cli" ||
		value === "http" ||
		value === "tmux" ||
		value === "browser" ||
		value === "gui" ||
		value === "data"
	)
		return value;
	invalid(`${field} must be a supported manual QA surface.`, field);
}

function kindField(value: unknown, field: string): UlwLoopManualQaArtifactKind {
	if (
		value === "cli-transcript" ||
		value === "log" ||
		value === "screenshot" ||
		value === "image" ||
		value === "http-dump" ||
		value === "data-diff"
	)
		return value;
	invalid(`${field} must be a supported artifact kind.`, field);
}

function passedVerdict(value: unknown, field: string): "passed" {
	if (value === "not_applicable") invalid(`${field} must not be not_applicable.`, field);
	return literal(value, "passed", field);
}

function artifactCompatible(surface: UlwLoopManualQaSurface, kind: UlwLoopManualQaArtifactKind): boolean {
	switch (surface) {
		case "cli":
		case "tmux":
			return kind === "cli-transcript" || kind === "log";
		case "http":
			return kind === "http-dump";
		case "browser":
		case "gui":
			return kind === "screenshot" || kind === "image";
		case "data":
			return kind === "data-diff";
		default:
			invalid("manualQa.surfaceEvidence has an unsupported surface.", "manualQa.surfaceEvidence.surface");
	}
}

function checkFile(path: string, field: string, opts?: ValidateQualityGateOptions): void {
	if (opts === undefined) return;
	const absolute = resolve(opts.repoRoot, path);
	if (!opts.fs.existsSync(absolute)) invalid(`${field} must point to an existing artifact.`, field);
	const stat = opts.fs.statSync(absolute);
	if (stat.size <= 0) invalid(`${field} must point to a non-empty artifact.`, field);
}

function artifactMap(refs: readonly UlwLoopManualQaArtifactRef[]): Map<string, UlwLoopManualQaArtifactRef> {
	const byId = new Map<string, UlwLoopManualQaArtifactRef>();
	for (const ref of refs) {
		if (byId.has(ref.id)) invalid(`manualQa.artifactRefs contains duplicate ${ref.id}.`, "manualQa.artifactRefs");
		byId.set(ref.id, ref);
	}
	return byId;
}

function parseArtifactRefs(value: unknown, opts?: ValidateQualityGateOptions): readonly UlwLoopManualQaArtifactRef[] {
	if (!Array.isArray(value) || value.length === 0)
		invalid("manualQa.artifactRefs must not be empty.", "manualQa.artifactRefs");
	return value.map((item, index) => {
		const ref = section(item, `manualQa.artifactRefs[${index}]`);
		const path = textField(ref["path"], `manualQa.artifactRefs[${index}].path`);
		checkFile(path, `manualQa.artifactRefs[${index}].path`, opts);
		return {
			id: textField(ref["id"], `manualQa.artifactRefs[${index}].id`),
			kind: kindField(ref["kind"], `manualQa.artifactRefs[${index}].kind`),
			description: textField(ref["description"], `manualQa.artifactRefs[${index}].description`),
			path,
		};
	});
}

function referencedArtifacts(
	value: unknown,
	field: string,
	byId: ReadonlyMap<string, UlwLoopManualQaArtifactRef>,
): readonly UlwLoopManualQaArtifactRef[] {
	return stringArray(value, field).map((id) => {
		const artifact = byId.get(id);
		if (artifact === undefined) invalid(`${field} references unknown artifact ${id}.`, field);
		return artifact;
	});
}

export function validateQualityGate(input: unknown, opts?: ValidateQualityGateOptions): UlwLoopQualityGate {
	const gate = section(input, "qualityGate");
	const codeReview = section(gate["codeReview"], "codeReview");
	const manualQa = section(gate["manualQa"], "manualQa");
	const gateReview = section(gate["gateReview"], "gateReview");
	const iteration = section(gate["iteration"], "iteration");
	const coverage = section(gate["criteriaCoverage"], "criteriaCoverage");
	const totalCriteria = numberField(coverage["totalCriteria"], "criteriaCoverage.totalCriteria");
	const passCount = numberField(coverage["passCount"], "criteriaCoverage.passCount");
	if (passCount < totalCriteria)
		invalid("criteriaCoverage.passCount must cover totalCriteria.", "criteriaCoverage.passCount");
	const artifactRefs = parseArtifactRefs(manualQa["artifactRefs"], opts);
	const byId = artifactMap(artifactRefs);
	const surfaceEvidence = parseSurfaceEvidence(manualQa["surfaceEvidence"], byId);
	const adversarialCases = parseAdversarialCases(manualQa["adversarialCases"], byId);
	const codeReportPath = textField(codeReview["reportPath"], "codeReview.reportPath");
	const gateReportPath = textField(gateReview["reportPath"], "gateReview.reportPath");
	checkFile(codeReportPath, "codeReview.reportPath", opts);
	checkFile(gateReportPath, "gateReview.reportPath", opts);
	return {
		codeReview: {
			by: reviewerRoleField(codeReview["by"], REVIEWER_ROLES.codeReview, "codeReview.by"),
			recommendation: literal(codeReview["recommendation"], "APPROVE", "codeReview.recommendation"),
			codeQualityStatus: literal(codeReview["codeQualityStatus"], "CLEAR", "codeReview.codeQualityStatus"),
			reportPath: codeReportPath,
			evidence: textField(codeReview["evidence"], "codeReview.evidence"),
			blockers: emptyBlockers(codeReview["blockers"], "codeReview.blockers"),
		},
		manualQa: {
			by: reviewerRoleField(manualQa["by"], REVIEWER_ROLES.manualQa, "manualQa.by"),
			status: literal(manualQa["status"], "passed", "manualQa.status"),
			evidence: textField(manualQa["evidence"], "manualQa.evidence"),
			surfaceEvidence,
			adversarialCases,
			artifactRefs,
		},
		gateReview: {
			by: reviewerRoleField(gateReview["by"], REVIEWER_ROLES.gateReview, "gateReview.by"),
			recommendation: literal(gateReview["recommendation"], "APPROVE", "gateReview.recommendation"),
			reportPath: gateReportPath,
			evidence: textField(gateReview["evidence"], "gateReview.evidence"),
			blockers: emptyBlockers(gateReview["blockers"], "gateReview.blockers"),
		},
		iteration: {
			fullRerun: literal(iteration["fullRerun"], true, "iteration.fullRerun"),
			status: literal(iteration["status"], "passed", "iteration.status"),
			rerunCommands: stringArray(iteration["rerunCommands"], "iteration.rerunCommands"),
			evidence: textField(iteration["evidence"], "iteration.evidence"),
		},
		criteriaCoverage: {
			totalCriteria,
			passCount,
			originalIntent: textField(coverage["originalIntent"], "criteriaCoverage.originalIntent"),
			desiredOutcome: textField(coverage["desiredOutcome"], "criteriaCoverage.desiredOutcome"),
			userOutcomeReview: textField(coverage["userOutcomeReview"], "criteriaCoverage.userOutcomeReview"),
			adversarialClassesCovered: stringArray(
				coverage["adversarialClassesCovered"],
				"criteriaCoverage.adversarialClassesCovered",
			),
		},
	};
}

function parseSurfaceEvidence(
	value: unknown,
	byId: ReadonlyMap<string, UlwLoopManualQaArtifactRef>,
): UlwLoopQualityGate["manualQa"]["surfaceEvidence"] {
	if (!Array.isArray(value) || value.length === 0)
		invalid("manualQa.surfaceEvidence must not be empty.", "manualQa.surfaceEvidence");
	return value.map((item, index) => {
		const row = section(item, `manualQa.surfaceEvidence[${index}]`);
		const surface = surfaceField(row["surface"], `manualQa.surfaceEvidence[${index}].surface`);
		const artifacts = referencedArtifacts(
			row["artifactRefs"],
			`manualQa.surfaceEvidence[${index}].artifactRefs`,
			byId,
		);
		for (const artifact of artifacts) {
			if (!artifactCompatible(surface, artifact.kind)) {
				invalid(
					`manualQa.surfaceEvidence ${surface} artifact ${artifact.kind} is incompatible.`,
					"manualQa.surfaceEvidence",
				);
			}
		}
		return {
			id: textField(row["id"], `manualQa.surfaceEvidence[${index}].id`),
			criterionRef: textField(row["criterionRef"], `manualQa.surfaceEvidence[${index}].criterionRef`),
			surface,
			invocation: textField(row["invocation"], `manualQa.surfaceEvidence[${index}].invocation`),
			verdict: passedVerdict(row["verdict"], `manualQa.surfaceEvidence[${index}].verdict`),
			artifactRefs: artifacts.map((artifact) => artifact.id),
		};
	});
}

function parseAdversarialCases(
	value: unknown,
	byId: ReadonlyMap<string, UlwLoopManualQaArtifactRef>,
): UlwLoopQualityGate["manualQa"]["adversarialCases"] {
	if (!Array.isArray(value) || value.length === 0)
		invalid("manualQa.adversarialCases must not be empty.", "manualQa.adversarialCases");
	return value.map((item, index) => {
		const row = section(item, `manualQa.adversarialCases[${index}]`);
		const artifacts = referencedArtifacts(
			row["artifactRefs"],
			`manualQa.adversarialCases[${index}].artifactRefs`,
			byId,
		);
		return {
			id: textField(row["id"], `manualQa.adversarialCases[${index}].id`),
			criterionRef: textField(row["criterionRef"], `manualQa.adversarialCases[${index}].criterionRef`),
			scenario: textField(row["scenario"], `manualQa.adversarialCases[${index}].scenario`),
			expectedBehavior: textField(row["expectedBehavior"], `manualQa.adversarialCases[${index}].expectedBehavior`),
			verdict: passedVerdict(row["verdict"], `manualQa.adversarialCases[${index}].verdict`),
			artifactRefs: artifacts.map((artifact) => artifact.id),
		};
	});
}

