		const parsed = extractQualityGateSample(workflow);

		// when
		const gate = validateQualityGate(parsed, FS_OPTS);

		// then
		expect(gate.manualQa.surfaceEvidence).toHaveLength(2);
		expect(gate.gateReview.recommendation).toBe("APPROVE");
	});
});

