		readonly hookEventName: "UserPromptSubmit";
		readonly additionalContext: string;
	};
}

export function runUserPromptSubmitHook(input: unknown): string {
	if (!isCodexUserPromptSubmitInput(input)) return "";
	if (isContextPressureRecoveryPrompt(input.prompt)) return "";
	if (hasAutoWorkflowContextAlreadyInTranscript(input.transcript_path))
		return "";
	if (isContextPressureTranscript(input.transcript_path)) return "";
	const autoWorkflowContext = buildAutoWorkflowContext(input.prompt);
	return autoWorkflowContext === null
		? ""
		: formatAdditionalContextOutput(autoWorkflowContext);
}

export function buildAutoWorkflowContext(
	prompt: string,
	hookEnv: NodeJS.ProcessEnv = env,
): string | null {
	if (!isAutoWorkflowEnabled(hookEnv)) return null;
	if (matchesAny(prompt, EXPLICIT_WORKFLOW_PATTERNS)) return null;
	const selection = selectAutoWorkflow(prompt);
	if (selection === null) return null;
	return [
		...AUTO_WORKFLOW_CONTEXT,
		selection,
		"</lazycodex-auto-workflow>",
	].join("\n");
}

function isAutoWorkflowEnabled(hookEnv: NodeJS.ProcessEnv): boolean {
	const rawFlag = hookEnv[AUTO_WORKFLOW_FLAG_NAME];
	if (rawFlag === undefined) return false;
	return /^(?:1|true|yes|on)$/i.test(rawFlag);
}

function selectAutoWorkflow(prompt: string): string | null {
	const matches = WORKFLOW_MATCHERS.filter((workflow) =>
		matchesAny(prompt, workflow.patterns),
	);
	if (matches.length === 0) return null;
	if (matches.length > 1) {
		return [
			"- Several LazyCodex workflows may fit this prompt.",
			`- Ask one concise confirmation before escalating: ${matches.map((match) => match.name).join(", ")}.`,
			"- Keep the turn plain if the user confirms this is a small direct edit.",
		].join("\n");
	}
	return matches[0]?.guidance ?? null;
}

function hasAutoWorkflowContextAlreadyInTranscript(
	transcriptPath: string | null | undefined,
): boolean {
	if (transcriptPath === undefined || transcriptPath === null) return false;
	try {
		const rawTranscript = readTranscriptTail(transcriptPath);
		for (const line of rawTranscript.split(/\r?\n/)) {
			const parsed = parseJsonLine(line);
			if (!isRecord(parsed)) continue;
			const hookSpecificOutput = parsed["hookSpecificOutput"];
			if (!isRecord(hookSpecificOutput)) continue;
			if (hookSpecificOutput["hookEventName"] !== "UserPromptSubmit") continue;
			if (
				typeof hookSpecificOutput["additionalContext"] === "string" &&
				hookSpecificOutput["additionalContext"].includes(
					AUTO_WORKFLOW_DIRECTIVE_MARKER,
				)
			) {
				return true;
			}
		}
	} catch (error) {
		if (error instanceof Error) return false;
		throw error;
	}
	return false;
}

function readTranscriptTail(transcriptPath: string): string {
	const rawTranscript = readFileSync(transcriptPath);
	return rawTranscript
		.subarray(Math.max(0, rawTranscript.byteLength - TRANSCRIPT_SEARCH_BYTES))
		.toString("utf8");
}

function isContextPressureRecoveryPrompt(prompt: string): boolean {
	const normalizedPrompt = prompt.toLowerCase();
	return CONTEXT_PRESSURE_MARKERS.some((marker) =>
		normalizedPrompt.includes(marker),
	);
}

function isContextPressureTranscript(
	transcriptPath: string | null | undefined,
): boolean {
	if (transcriptPath === undefined || transcriptPath === null) return false;
	try {
		return isContextPressureRecoveryPrompt(
			readFileSync(transcriptPath, "utf8"),
		);
	} catch (error) {
		if (error instanceof Error) return false;
		throw error;
	}
}

function formatAdditionalContextOutput(additionalContext: string): string {
	const normalizedContext = normalizeAdditionalContext(additionalContext);
	if (normalizedContext.length === 0) return "";
	const output: UserPromptSubmitHookOutput = {
		hookSpecificOutput: {
			hookEventName: "UserPromptSubmit",
			additionalContext: normalizedContext,
		},
	};
	return `${JSON.stringify(output)}\n`;
}

function normalizeAdditionalContext(additionalContext: string): string {
	return additionalContext.replace(/\r\n/g, "\n").replace(/\r/g, "\n").trim();
}

function parseJsonLine(line: string): unknown | null {
	if (line.trim().length === 0) return null;
	try {
		const parsed: unknown = JSON.parse(line);
		return parsed;
	} catch (error) {
		if (error instanceof Error) return null;
		throw error;
	}
}

function matchesAny(prompt: string, patterns: readonly RegExp[]): boolean {
	return patterns.some((pattern) => pattern.test(prompt));
}

function isCodexUserPromptSubmitInput(
	value: unknown,
): value is CodexUserPromptSubmitInput {
	return (
		isRecord(value) &&
		value["hook_event_name"] === "UserPromptSubmit" &&
		typeof value["prompt"] === "string" &&
		(value["transcript_path"] === undefined ||
			value["transcript_path"] === null ||
			typeof value["transcript_path"] === "string")
	);
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

const tempDirectories: string[] = [];

interface UserPromptSubmitHookOutput {
	readonly hookSpecificOutput: {
		readonly hookEventName: "UserPromptSubmit";
		readonly additionalContext: string;
	};
}

export function cleanupTempDirectories(): void {
	for (const directory of tempDirectories.splice(0)) {
		rmSync(directory, { recursive: true, force: true });
	}
}

export function parseHookOutput(output: string): UserPromptSubmitHookOutput {
	const parsed: unknown = JSON.parse(output);
	if (!isUserPromptSubmitHookOutput(parsed))
		throw new TypeError("Expected UserPromptSubmit hook output");
	return parsed;
}

export function writeTranscript(...lines: string[]): string {
	const root = mkdtempSync(
		path.join(tmpdir(), "codex-workflow-selector-transcript-"),
	);
	tempDirectories.push(root);
	const transcriptPath = path.join(root, "transcript.jsonl");
	writeFileSync(transcriptPath, `${lines.join("\n")}\n`);
	return transcriptPath;
}

export function writeContextPressureTranscript(): string {
	return writeTranscript(
		JSON.stringify({
			type: "message",
			payload: {
				content: "Codex ran out of room in the model's context window.",
			},
		}),
	);
}

function isUserPromptSubmitHookOutput(
	value: unknown,
): value is UserPromptSubmitHookOutput {
	if (!isRecord(value)) return false;
	const hookSpecificOutput = value["hookSpecificOutput"];
	return (
		isRecord(hookSpecificOutput) &&
		hookSpecificOutput["hookEventName"] === "UserPromptSubmit" &&
		typeof hookSpecificOutput["additionalContext"] === "string"
	);
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

import { afterEach, describe, expect, it } from "vitest";

import {
	buildAutoWorkflowContext,
	runUserPromptSubmitHook,
} from "../src/codex-hook.js";
import {
	cleanupTempDirectories,
	parseHookOutput,
	writeContextPressureTranscript,
	writeTranscript,
} from "./codex-hook-test-helpers.js";

afterEach(() => {
	cleanupTempDirectories();
});

describe("codex workflow selector hook", () => {
	const originalAutoWorkflowFlag = process.env["OMO_CODEX_AUTO_WORKFLOW"];

	afterEach(() => {
		if (originalAutoWorkflowFlag === undefined) {
			delete process.env["OMO_CODEX_AUTO_WORKFLOW"];
		} else {
			process.env["OMO_CODEX_AUTO_WORKFLOW"] = originalAutoWorkflowFlag;
		}
	});

	it("#given auto workflow is disabled #when prompt asks for debugging #then hook stays quiet", () => {
		// given
		delete process.env["OMO_CODEX_AUTO_WORKFLOW"];
		const payload = {
			hook_event_name: "UserPromptSubmit",
			prompt: "Fix this flaky test and diagnose why CI is failing",
		};

		// when
		const output = runUserPromptSubmitHook(payload);

		// then
		expect(output).toBe("");
		expect(buildAutoWorkflowContext(payload.prompt, {})).toBeNull();
	});

	it("#given auto workflow is enabled #when prompt asks for debugging #then hook selects ulw-loop guidance", () => {
		// given
		process.env["OMO_CODEX_AUTO_WORKFLOW"] = "1";
		const payload = {
			hook_event_name: "UserPromptSubmit",
			prompt: "Fix this flaky test and diagnose why CI is failing",
		};

		// when
		const output = runUserPromptSubmitHook(payload);
		const parsed = parseHookOutput(output);

		// then
		expect(parsed.hookSpecificOutput.additionalContext).toContain(
			"<lazycodex-auto-workflow>",
		);
		expect(parsed.hookSpecificOutput.additionalContext).toContain("$ulw-loop");
		expect(parsed.hookSpecificOutput.additionalContext).toContain(
			"manual QA evidence",
		);
	});

	it("#given auto workflow is enabled #when prompt asks for broad feature work #then hook selects plan and start-work guidance", () => {
		// given
		const prompt =
			"Add a settings page and implement the account preferences flow";

		// when
		const context = buildAutoWorkflowContext(prompt, {
			OMO_CODEX_AUTO_WORKFLOW: "true",
		});

		// then
		expect(context).not.toBeNull();
		expect(context).toContain("$ulw-plan");
		expect(context).toContain("$start-work");
		expect(context).toContain("plain Codex");
	});

	it("#given auto workflow is enabled #when prompt continues an approved plan #then hook selects start-work guidance", () => {
		// given
		const prompt = "Continue the approved plan";

		// when
		const context = buildAutoWorkflowContext(prompt, {
			OMO_CODEX_AUTO_WORKFLOW: "1",
		});

		// then
		expect(context).not.toBeNull();
		expect(context).toContain("$start-work");
		expect(context).toContain("existing plan instead of replanning");
		expect(context).not.toContain("$ulw-plan");
	});

	it("#given auto workflow is enabled #when prompt asks for repository onboarding #then hook selects init-deep guidance", () => {
		// given
		const prompt =
			"Map this unfamiliar repository before we change the architecture";

		// when
		const context = buildAutoWorkflowContext(prompt, {
			OMO_CODEX_AUTO_WORKFLOW: "on",
		});

		// then
		expect(context).not.toBeNull();
		expect(context).toContain("$init-deep");
		expect(context).toContain("weak-context repository onboarding");
	});

	it("#given auto workflow is enabled #when prompt is a small edit #then hook stays quiet", () => {
		// given
		const prompt = "Rename this variable";

		// when
		const context = buildAutoWorkflowContext(prompt, {
			OMO_CODEX_AUTO_WORKFLOW: "yes",
		});

		// then
		expect(context).toBeNull();
	});

	it("#given low-confidence overlapping prompt #when auto workflow is enabled #then hook asks confirmation before escalation", () => {
		// given
		const prompt = "Debug this failing test in a new unfamiliar repository";

		// when
		const context = buildAutoWorkflowContext(prompt, {
			OMO_CODEX_AUTO_WORKFLOW: "1",
		});

		// then
		expect(context).not.toBeNull();
		expect(context).toContain("Several LazyCodex workflows may fit");
		expect(context).toContain("Ask one concise confirmation");
		expect(context).toContain("debugging or recovery work");
		expect(context).toContain("weak-context repository onboarding");
	});

	it("#given explicit workflow command #when auto workflow is enabled #then selector stays quiet", () => {
		// given
		const prompts = [
			"ulw fix this",
			"$ulw-plan refactor auth",
			"$start-work continue",
			"$init-deep",
			"omo ulw-loop status",
		] as const;

		// when
		const contexts = prompts.map((prompt) =>
			buildAutoWorkflowContext(prompt, { OMO_CODEX_AUTO_WORKFLOW: "1" }),
		);

		// then
		expect(contexts).toEqual([null, null, null, null, null]);
	});

	it("#given transcript already contains auto workflow context #when prompt asks for debugging #then hook does not repeat guidance", () => {
		// given
		process.env["OMO_CODEX_AUTO_WORKFLOW"] = "1";
		const payload = {
			hook_event_name: "UserPromptSubmit",
			prompt: "Why did the build fail? Please diagnose the error",
			transcript_path: writeTranscript(
				JSON.stringify({
					hookSpecificOutput: {
						hookEventName: "UserPromptSubmit",
						additionalContext: "<lazycodex-auto-workflow>\nexisting directive",
					},
				}),
			),
		};

		// when
		const output = runUserPromptSubmitHook(payload);

		// then
		expect(output).toBe("");
	});

	it("#given context-pressure transcript #when prompt asks for debugging #then hook stays quiet", () => {
		// given
		process.env["OMO_CODEX_AUTO_WORKFLOW"] = "1";
		const payload = {
			hook_event_name: "UserPromptSubmit",
			prompt: "Fix this failing test",
			transcript_path: writeContextPressureTranscript(),
		};

		// when
		const output = runUserPromptSubmitHook(payload);

		// then
		expect(output).toBe("");
	});

	it("#given malformed or empty input #when hook runs #then exits with empty output", () => {
		// given
		process.env["OMO_CODEX_AUTO_WORKFLOW"] = "1";
		const inputs = [
			undefined,
			{},
			{ hook_event_name: "UserPromptSubmit", prompt: "" },
		] as const;

		// when
		const outputs = inputs.map((input) => runUserPromptSubmitHook(input));

		// then
		expect(outputs).toEqual(["", "", ""]);
	});
});

