import { dirname } from "node:path";
import { pathToFileURL } from "node:url";

import { FALLBACK_CATALOG, readModelCatalog } from "./migrate-codex-config/catalog.mjs";
import { configPaths } from "./migrate-codex-config/config-paths.mjs";
import { removeUnsupportedRootMultiAgentMode } from "./migrate-codex-config/multi-agent-mode-guard.mjs";
import { forceDisableMultiAgentV2 } from "./migrate-codex-config/multi-agent-v2-guard.mjs";
import { ensureCodexReasoningConfig as applyReasoningProfile, readRootSettings } from "./migrate-codex-config/root-settings.mjs";
import { readState, resolveStatePath, writeState } from "./migrate-codex-config/state.mjs";

export { readModelCatalog } from "./migrate-codex-config/catalog.mjs";

export function ensureCodexReasoningConfig(config, profile = FALLBACK_CATALOG.current) {
	return applyReasoningProfile(config, profile);
}

export async function migrateCodexConfig({ env = process.env, cwd = process.cwd() } = {}) {
	const catalog = await readModelCatalog(env);
	const statePath = resolveStatePath(env);
	const state = await readState(statePath);
	const paths = await configPaths({ env, cwd });
	const changed = [];
	const modeChanged = [];
	const nextState = { catalogVersion: catalog.version, files: {} };
	for (const configPath of paths) {
		const result = await migrateConfigFile(configPath, {
			catalog,
			previousState: state.files?.[configPath],
		});
		if (result.changed) changed.push(configPath);
		if (result.multiAgentModeChanged) modeChanged.push(configPath);
		nextState.files[configPath] = {
			catalogVersion: catalog.version,
			written: result.written,
			managed: result.managed,
		};
	}
	await writeState(statePath, nextState);
	return { changed, modeChanged };
}

export async function migrateConfigFile(configPath, { catalog = FALLBACK_CATALOG, previousState } = {}) {
	const before = await readConfig(configPath);
	const decision = shouldApplyCatalog(before, catalog, previousState);

	let config = before;
	let reasoningApplied = false;

	if (decision.apply) {
		config = ensureCodexReasoningConfig(config, catalog.current);
		reasoningApplied = config !== before;
	}

	const afterMultiAgentGuard = forceDisableMultiAgentV2(config);
	const multiAgentChanged = afterMultiAgentGuard !== config;
	if (multiAgentChanged) config = afterMultiAgentGuard;

	const afterMultiAgentModeGuard = removeUnsupportedRootMultiAgentMode(config);
	const multiAgentModeChanged = afterMultiAgentModeGuard !== config;
	if (multiAgentModeChanged) config = afterMultiAgentModeGuard;

	const changed = reasoningApplied || multiAgentChanged || multiAgentModeChanged;
	if (changed) {
		await mkdir(dirname(configPath), { recursive: true });
		await writeFile(configPath, `${config.trimEnd()}\n`);
	}

	const written = decision.apply ? catalog.current : readRootSettings(config);
	const managed = decision.apply ? true : decision.managed;
	return { changed, written, managed, multiAgentModeChanged };
}

function shouldApplyCatalog(config, catalog, previousState) {
	const current = readRootSettings(config);
	if (Object.keys(current).length === 0) return { apply: true, reason: "empty" };
	if (matchesProfile(current, catalog.current)) return { apply: false, reason: "current", managed: true };
	if (previousState?.managed === true && matchesProfile(current, previousState.written)) {
		return { apply: true, reason: "managed-state" };
	}
	for (const profile of catalog.managedProfiles) {
		if (matchesProfile(current, profile.match)) return { apply: true, reason: profile.version };
	}
	return { apply: false, reason: "user-modified", managed: false };
}

function matchesProfile(current, profile) {
	if (!isRecord(profile)) return false;
	for (const [key, value] of Object.entries(profile)) {
		if (current[key] !== value) return false;
	}
	return true;
}

function isRecord(value) {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

async function readConfig(configPath) {
	try {
		return await readFile(configPath, "utf8");
	} catch (error) {
		if (error instanceof Error && "code" in error && error.code === "ENOENT") return "";
		throw error;
	}
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
	migrateCodexConfig().catch((error) => {
		if (!(error instanceof Error)) throw error;
		process.exit(0);
	});
}

import { stringEnd, stripJsonComments } from "./jsonc.mjs";

export function addCodexCodegraphValues(content, config, additions) {
	const codex = recordAt(config, "[codex]");
	const codexRange = findObjectPropertyRange(content, 0, "[codex]");
	if (!isRecord(codex) || codexRange === null) {
		return insertPropertiesIntoObject(content, 0, {
			"[codex]": {
				codegraph: additions,
			},
		});
	}

	const codegraph = recordAt(codex, "codegraph");
	const codegraphRange = findObjectPropertyRange(content, codexRange.valueStart, "codegraph");
	if (!isRecord(codegraph) || codegraphRange === null) {
		return insertPropertiesIntoObject(content, codexRange.valueStart, { codegraph: additions });
	}
	return insertPropertiesIntoObject(content, codegraphRange.valueStart, additions);
}

export function recordAt(value, key) {
	return isRecord(value) ? value[key] : undefined;
}

export function isRecord(value) {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function hasOwn(value, key) {
	return isRecord(value) && Object.prototype.hasOwnProperty.call(value, key);
}

function findObjectPropertyRange(content, objectStart, name) {
	const open = content.indexOf("{", objectStart);
	if (open < 0) return null;
	let index = open + 1;
	while (index < content.length) {
		index = skipTrivia(content, index);
		if (content[index] === "}") return null;
		if (content[index] !== "\"") return null;
		const end = stringEnd(content, index);
		const key = JSON.parse(content.slice(index, end));
		index = skipTrivia(content, end);
		if (content[index] !== ":") return null;
		const valueStart = skipTrivia(content, index + 1);
		const valueEnd = valueRangeEnd(content, valueStart);
		if (key === name) return { valueEnd, valueStart };
		index = skipTrivia(content, valueEnd);
		if (content[index] === ",") index += 1;
	}
	return null;
}

function insertPropertiesIntoObject(content, objectStart, properties) {
	const open = content.indexOf("{", objectStart);
	const close = matchingBrace(content, open);
	if (open < 0 || close < 0) return content;
	const entries = Object.entries(properties);
	if (entries.length === 0) return content;
	const parentIndent = lineIndent(content, open);
	const childIndent = `${parentIndent}  `;
	const body = entries.map(([key, value]) => `${childIndent}${JSON.stringify(key)}: ${formatJsoncValue(value, childIndent)}`).join(",\n");
	const hasProperty = /"[^"]+"\s*:/.test(stripJsonComments(content.slice(open + 1, close)));
	const beforeClose = content.slice(0, close).replace(/\s*$/, "");
	const suffix = content.slice(close);
	const comma = hasProperty && !beforeClose.endsWith(",") && !beforeClose.endsWith("{") ? "," : "";
	return `${beforeClose}${comma}\n${body}\n${parentIndent}${suffix}`;
}

function formatJsoncValue(value, indent) {
	if (!isRecord(value)) return JSON.stringify(value);
	const nextIndent = `${indent}  `;
	const entries = Object.entries(value).map(([key, entry]) => `${nextIndent}${JSON.stringify(key)}: ${formatJsoncValue(entry, nextIndent)}`);
	return `{\n${entries.join(",\n")}\n${indent}}`;
}

function valueRangeEnd(content, start) {
	const char = content[start];
	if (char === "{" || char === "[") return matchingBrace(content, start) + 1;
	if (char === "\"") return stringEnd(content, start);
	let index = start;
	while (index < content.length && content[index] !== "," && content[index] !== "}") index += 1;
	return index;
}

function matchingBrace(content, start) {
	const open = content[start];
	const close = open === "{" ? "}" : "]";
	let depth = 0;
	for (let index = start; index < content.length; index += 1) {
		const char = content[index];
		if (char === "\"") index = stringEnd(content, index) - 1;
		else if (char === "/" && content[index + 1] === "/") while (index < content.length && content[index] !== "\n") index += 1;
		else if (char === "/" && content[index + 1] === "*") {
			index += 2;
			while (index < content.length && !(content[index] === "*" && content[index + 1] === "/")) index += 1;
			index += 1;
		} else if (char === open) depth += 1;
		else if (char === close) {
			depth -= 1;
			if (depth === 0) return index;
		}
	}
	return -1;
}

function skipTrivia(content, index) {
	while (index < content.length) {
		if (/\s/.test(content[index])) index += 1;
		else if (content[index] === "/" && content[index + 1] === "/") while (index < content.length && content[index] !== "\n") index += 1;
		else if (content[index] === "/" && content[index + 1] === "*") {
			index += 2;
			while (index < content.length && !(content[index] === "*" && content[index + 1] === "/")) index += 1;
			index += 2;
		} else return index;
	}
	return index;
}

function lineIndent(content, index) {
	const lineStart = content.lastIndexOf("\n", index) + 1;
	const match = /^[ \t]*/.exec(content.slice(lineStart, index));
	return match?.[0] ?? "";
}

export function parseJsonc(content) {
	try {
		return { ok: true, value: JSON.parse(stripTrailingCommas(stripJsonComments(content))) };
	} catch (error) {
		if (error instanceof Error) return { ok: false, error };
		throw error;
	}
}

export function stripJsonComments(content) {
	let result = "";
	for (let index = 0; index < content.length; index += 1) {
		const char = content[index];
		const next = content[index + 1];
		if (char === "\"") {
			const end = stringEnd(content, index);
			result += content.slice(index, end);
			index = end - 1;
		} else if (char === "/" && next === "/") {
			while (index < content.length && content[index] !== "\n") index += 1;
			result += "\n";
		} else if (char === "/" && next === "*") {
			index += 2;
			while (index < content.length && !(content[index] === "*" && content[index + 1] === "/")) index += 1;
			index += 1;
		} else {
			result += char;
		}
	}
	return result;
}

export function stringEnd(content, start) {
	for (let index = start + 1; index < content.length; index += 1) {
		if (content[index] === "\\") index += 1;
		else if (content[index] === "\"") return index + 1;
	}
	return content.length;
}

function stripTrailingCommas(content) {
	return content.replace(/,\s*([}\]])/g, "$1");
}

export const SCAFFOLD = `{
  // Shared OMO settings. Harness override blocks below are additive.
  "codegraph": {
    // "enabled": true,
    // "auto_provision": true,
    // "telemetry": false,
    // "install_dir": "~/.omo/codegraph"
  },

  "[codex]": {
    "codegraph": {
      // "enabled": true,
      // "auto_provision": true,
      // "install_dir": "~/.omo/codegraph",
      // "telemetry": false
    }
  },

  "[opencode]": {
    "codegraph": {
      // "enabled": true,
      // "auto_provision": true,
      // "install_dir": "~/.omo/codegraph",
      // "telemetry": false,
      // "watch_debounce_ms": 250
    }
  }
}
`;

#!/usr/bin/env node

import { access, mkdir, readFile, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { dirname, join } from "node:path";
import { pathToFileURL } from "node:url";

import { addCodexCodegraphValues, hasOwn, isRecord, recordAt } from "./migrate-omo-sot/editor.mjs";
import { parseJsonc } from "./migrate-omo-sot/jsonc.mjs";
import { SCAFFOLD } from "./migrate-omo-sot/scaffold.mjs";

const CODEGRAPH_KEYS = ["auto_provision", "enabled", "install_dir", "telemetry"];
const ENV_MAPPINGS = [
	["auto_provision", "OMO_CODEGRAPH_AUTO_PROVISION", "boolean"],
	["auto_provision", "CODEX_CODEGRAPH_AUTO_PROVISION", "boolean"],
	["enabled", "OMO_CODEGRAPH_ENABLED", "boolean"],
	["enabled", "CODEX_CODEGRAPH_ENABLED", "boolean"],
	["install_dir", "OMO_CODEGRAPH_INSTALL_DIR", "string"],
	["install_dir", "CODEX_CODEGRAPH_INSTALL_DIR", "string"],
	["telemetry", "OMO_CODEGRAPH_TELEMETRY", "boolean"],
	["telemetry", "CODEX_CODEGRAPH_TELEMETRY", "boolean"],
];

export async function migrateOmoSotConfig({ env = process.env, seed = false, configPath } = {}) {
	const targetPath = configPath ?? join(resolveHomeDir(env), ".omo", "config.jsonc");
	if (!(await pathExists(targetPath))) {
		if (!seed) return { changed: false, configPath: targetPath, seeded: false, warnings: [] };
		const parsedScaffold = parseJsonc(SCAFFOLD);
		if (!parsedScaffold.ok) throw parsedScaffold.error;
		const additions = collectCodexAdditions(parsedScaffold.value, env);
		const content = addCodexCodegraphValues(SCAFFOLD, parsedScaffold.value, additions);
		await mkdir(dirname(targetPath), { recursive: true });
		await writeFile(targetPath, content);
		return { changed: true, configPath: targetPath, seeded: true, warnings: [] };
	}

	const content = await readFile(targetPath, "utf8");
	const parsed = parseJsonc(content);
	if (!parsed.ok) {
		return {
			changed: false,
			configPath: targetPath,
			seeded: false,
			warnings: [`Could not parse ${targetPath}; left existing OMO SOT untouched: ${parsed.error.message}`],
		};
	}

	const additions = collectCodexAdditions(parsed.value, env);
	if (Object.keys(additions).length === 0) {
		return { changed: false, configPath: targetPath, seeded: false, warnings: [] };
	}

	const edited = addCodexCodegraphValues(content, parsed.value, additions);
	if (edited === content) return { changed: false, configPath: targetPath, seeded: false, warnings: [] };
	await writeFile(targetPath, edited);
	return { changed: true, configPath: targetPath, seeded: false, warnings: [] };
}

function resolveHomeDir(env) {
	const candidate = env.HOME ?? env.USERPROFILE;
	return candidate?.trim() ? candidate : homedir();
}

async function pathExists(path) {
	try {
		await access(path);
		return true;
	} catch (error) {
		if (error instanceof Error && "code" in error && error.code === "ENOENT") return false;
		throw error;
	}
}

function collectCodexAdditions(config, env) {
	const codexCodegraph = recordAt(recordAt(config, "[codex]"), "codegraph");
	const additions = {};
	addSupportedCodegraphValues(additions, recordAt(config, "codegraph"), codexCodegraph);
	for (const [key, envKey, kind] of ENV_MAPPINGS) {
		const raw = env[envKey];
		if (raw === undefined || hasOwn(codexCodegraph, key)) continue;
		const parsed = parseEnvValue(raw, kind);
		if (parsed !== null) additions[key] = parsed;
	}
	for (const key of Object.keys(additions)) {
		if (hasOwn(codexCodegraph, key)) delete additions[key];
	}
	return additions;
}

function addSupportedCodegraphValues(additions, baseCodegraph, codexCodegraph) {
	if (!isRecord(baseCodegraph)) return;
	for (const key of CODEGRAPH_KEYS) {
		if (hasOwn(codexCodegraph, key) || !hasOwn(baseCodegraph, key)) continue;
		const value = baseCodegraph[key];
		if (isValidCodegraphValue(key, value)) additions[key] = value;
	}
}

function parseEnvValue(value, kind) {
	if (kind === "string") return value;
	const normalized = value.trim().toLowerCase();
	if (["1", "true", "yes", "on"].includes(normalized)) return true;
	if (["0", "false", "no", "off"].includes(normalized)) return false;
	return null;
}

function isValidCodegraphValue(key, value) {
	if (key === "install_dir") return typeof value === "string";
	return typeof value === "boolean";
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
	migrateOmoSotConfig({ seed: process.argv.includes("--seed") })
		.then((result) => {
			for (const warning of result.warnings) process.stderr.write(`${warning}\n`);
		})
		.catch((error) => {
			console.error(error instanceof Error ? error.message : String(error));
			process.exitCode = 1;
		});
}

const WINDOWS_CMD_SHIM_COMMANDS = new Set(["npm", "npx"]);

export function resolveSpawnInvocation(command, args, platform = process.platform) {
	const invocation = { command, args: Array.from(args) };
	if (platform !== "win32") return invocation;
	if (!WINDOWS_CMD_SHIM_COMMANDS.has(command.toLowerCase())) return invocation;
	return {
		command: "cmd.exe",
		args: ["/d", "/s", "/c", `${command}.cmd`, ...invocation.args],
	};
}

#!/usr/bin/env node
import { access, readdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { pathToFileURL } from "node:url";
import { fileURLToPath } from "node:url";

import { formatLazyCodexHookStatusMessage, normalizeLazyCodexHookStatusLabel } from "./hook-status-message.mjs";

const defaultRoot = dirname(dirname(fileURLToPath(import.meta.url)));

async function exists(path) {
	try {
		await access(path);
		return true;
	} catch (error) {
		if (error instanceof Error && "code" in error && error.code === "ENOENT") return false;
		throw error;
	}
}

async function readJson(path) {
	return JSON.parse(await readFile(path, "utf8"));
}

async function writeJson(path, value) {
	await writeFile(path, `${JSON.stringify(value, null, "\t")}\n`);
}

async function readPackageVersion(path) {
	const packageJson = await readJson(path);
	return packageJson.version;
}

async function readAggregateHookPaths(root) {
	const manifest = await readJson(join(root, ".codex-plugin", "plugin.json"));
	if (typeof manifest.hooks === "string") return [manifest.hooks];
	if (Array.isArray(manifest.hooks)) {
		return manifest.hooks.filter((hookPath) => typeof hookPath === "string");
	}
	return ["./hooks/hooks.json"];
}

async function readComponentNames(root) {
	const componentsRoot = join(root, "components");
	const entries = await readdir(componentsRoot, { withFileTypes: true });
	const names = [];
	for (const entry of entries) {
		if (!entry.isDirectory()) continue;
		const packageJsonPath = join(componentsRoot, entry.name, "package.json");
		if (!(await exists(packageJsonPath))) continue;
		names.push(entry.name);
	}
	return names;
}

function syncHooksJson(hooksJson, versionForCommand) {
	for (const groups of Object.values(hooksJson.hooks)) {
		for (const group of groups) {
			for (const hook of group.hooks) {
				if (hook.type !== "command") continue;
				const label = normalizeLazyCodexHookStatusLabel(hook.statusMessage);
				hook.statusMessage = formatLazyCodexHookStatusMessage(versionForCommand(hook.command), label);
			}
		}
	}
}

async function syncComponentHooks(root, componentName, version) {
	const hooksPath = join(root, "components", componentName, "hooks", "hooks.json");
	if (!(await exists(hooksPath))) return;
	const hooksJson = await readJson(hooksPath);
	syncHooksJson(hooksJson, () => version);
	await writeJson(hooksPath, hooksJson);
}

function normalizeReleaseVersion(version) {
	if (typeof version !== "string") return "";
	return version.trim();
}

function readReleaseVersion(options) {
	const releaseVersion = normalizeReleaseVersion(options.releaseVersion ?? process.env.LAZYCODEX_RELEASE_VERSION);
	if (releaseVersion.length > 0) return releaseVersion;
	return undefined;
}

export async function syncHookStatusMessages(root = defaultRoot, options = {}) {
	const releaseVersion = readReleaseVersion(options);
	const aggregateVersion = releaseVersion ?? (await readPackageVersion(join(root, ".codex-plugin", "plugin.json")));
	const componentNames = await readComponentNames(root);
	for (const hookPath of await readAggregateHookPaths(root)) {
		const aggregateHooksPath = join(root, hookPath.replace(/^\.\//, ""));
		const aggregateHooks = await readJson(aggregateHooksPath);
		syncHooksJson(aggregateHooks, () => aggregateVersion);
		await writeJson(aggregateHooksPath, aggregateHooks);
	}

	for (const componentName of componentNames) {
		const componentVersion =
			releaseVersion ?? (await readPackageVersion(join(root, "components", componentName, "package.json")));
		await syncComponentHooks(root, componentName, componentVersion);
	}
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
	await syncHookStatusMessages();
}

#!/usr/bin/env node
import { cp, mkdir, readdir, readFile, rm, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { sharedSkillsRootPath } from "@oh-my-opencode/shared-skills";

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const sharedSkillsRoot = sharedSkillsRootPath();
const skillsRoot = join(root, "skills");
const sourceTestFilePattern = /\.test\.ts$/;
const skillSources = [
	["comment-checker", "components/comment-checker/skills/comment-checker"],
	["lsp", "components/lsp/skills/lsp"],
	["rules", "components/rules/skills/rules"],
	["teammode", "components/teammode/skills/teammode"],
	["ulw-loop", "components/ulw-loop/skills/ulw-loop"],
	["ulw-plan", "components/ultrawork/skills/ulw-plan"],
];
const componentSkillNames = new Set(skillSources.map(([name]) => name));
const skillDisplayPrefix = "(OmO) ";

const opencodeOnlyOrchestrationPattern = /\b(?:call_omo_agent|background_output|team_[a-z_]+|task)\s*\(/;

const codexHarnessToolCompatibility = `## Codex Harness Tool Compatibility

This skill may include examples copied from the OpenCode harness. In Codex, do not call OpenCode-only tools such as \`call_omo_agent(...)\`, \`task(...)\`, \`background_output(...)\`, or \`team_*(...)\` literally. Translate those examples to Codex native tools:

| OpenCode example | Codex tool to use |
| --- | --- |
| \`call_omo_agent(subagent_type="explore", ...)\` | \`multi_agent_v1.spawn_agent({"message":"TASK: act as an explorer. ...","agent_type":"explorer","fork_context":false})\` |
| \`call_omo_agent(subagent_type="librarian", ...)\` | \`multi_agent_v1.spawn_agent({"message":"TASK: act as a librarian. ...","agent_type":"librarian","fork_context":false})\` |
| \`task(subagent_type="plan", ...)\` | \`multi_agent_v1.spawn_agent({"message":"TASK: act as a planning agent. ...","agent_type":"plan","fork_context":false})\` |
| \`task(subagent_type="oracle", ...)\` for final verification | \`multi_agent_v1.spawn_agent({"message":"TASK: act as a rigorous reviewer. ...","agent_type":"lazycodex-gate-reviewer","fork_context":false})\` |
| \`task(category="...", ...)\` for implementation or QA | \`multi_agent_v1.spawn_agent({"message":"TASK: act as an implementation or QA worker. ...","fork_context":false})\` |
| \`background_output(task_id="...")\` | \`multi_agent_v1.wait_agent(...)\` for mailbox signals |
| \`team_*(...)\` | Use Codex native subagents via \`multi_agent_v1.spawn_agent\`, \`multi_agent_v1.send_input\`, \`multi_agent_v1.wait_agent\`, and \`multi_agent_v1.close_agent\` |

Role-specific behavior must be described in a self-contained \`message\`. Use \`fork_context: false\` to start the child with only the initial prompt (no parent history); use \`fork_context: true\` only when full parent history is truly required. Include any required conversation context, files, diffs, constraints, and requested skill names directly in the spawned agent's \`message\`. OMO installs these selectable agent roles into \`~/.codex/agents/\`: \`explorer\`, \`librarian\`, \`plan\`, \`momus\`, \`metis\`, \`lazycodex-code-reviewer\`, \`lazycodex-qa-executor\`, and \`lazycodex-gate-reviewer\` - pass the matching name as \`agent_type\` so the child gets that role's model and instructions. If the spawn tool exposes no \`agent_type\` parameter, omit it and describe the role inside \`message\`. If a code block below conflicts with this section, this section wins.

For work likely to exceed one wait cycle, require the child to send \`WORKING: <task> - <current phase>\` before long passes and \`BLOCKED: <reason>\` only when progress stops. A \`multi_agent_v1.wait_agent\` timeout only means no new mailbox update arrived. Treat a running child as alive. Fallback only when the child is completed without the deliverable, ack-only after followup, explicitly \`BLOCKED:\`, or no longer running.

`;

const codexCompatibilityEndMarkers = [
	"For work likely to exceed one wait cycle, require the child to send `WORKING: <task> - <current phase>` before long passes and `BLOCKED: <reason>` only when progress stops. A `multi_agent_v1.wait_agent` timeout only means no new mailbox update arrived. Treat a running child as alive. Fallback only when the child is completed without the deliverable, ack-only after followup, explicitly `BLOCKED:`, or no longer running.\n\n",
