	});
	await writeFile(env.LAZYCODEX_AUTO_UPDATE_STATE_PATH, JSON.stringify({
		lastCheckedAt: Date.now() - 1_000,
		lastStatus: "success",
		pendingNotice: { fromVersion: "1.0.0", toVersion: "1.0.1", startedAt: 1 },
