		join(pluginRoot, "hooks", "stop.json"),
		JSON.stringify({ hooks: { Stop: HOOKS_MANIFEST.hooks.Stop } }, null, "\t"),
	);
	const targets = [
		"scripts/auto-update.mjs",
		"components/ulw-loop/dist/cli.js",
		...(withGitBashDist ? ["components/git-bash/dist/cli.js"] : []),
	];
