import { cp, mkdir, readFile, rename, rm } from "node:fs/promises"
import { basename, dirname, join, sep } from "node:path"
import { copyBundledMcpRuntimeDists } from "./codex-cache-bundled-mcps"
import { fileExistsStrict, isPlainRecord } from "./codex-cache-fs"
import { rewriteCachedPackageLocalFileDependencies } from "./codex-cache-local-dependencies"
import { rewriteCachedManifestRoot, rewriteCachedMcpManifest } from "./codex-cache-mcp-manifest"
import { assertHookCommandTargets } from "./codex-hook-targets"
import type { InstalledPlugin, RunCommand } from "./types"

type RenameDirectory = (fromPath: string, toPath: string) => Promise<void>

export async function installCachedPlugin(input: {
  readonly buildSource?: boolean
  readonly codexHome: string
  readonly marketplaceName: string
  readonly name: string
  readonly renameDirectory?: RenameDirectory
  readonly sourcePath: string
  readonly version: string
  readonly runCommand: RunCommand
}): Promise<InstalledPlugin> {
  if (input.buildSource !== false) {
    await maybeRunNpmInstall(input.sourcePath, input.runCommand)
    await maybeRunNpmBuild(input.sourcePath, input.runCommand)
  }

  const targetPath = join(input.codexHome, "plugins", "cache", input.marketplaceName, input.name, input.version)
  const tempPath = createTempSiblingPath(targetPath)
  await rm(tempPath, { recursive: true, force: true })
  try {
    await copyDirectory(input.sourcePath, tempPath)
    await rewriteCachedPackageLocalFileDependencies(tempPath, input.sourcePath)
    await copyBundledMcpRuntimeDists({ pluginRoot: tempPath, sourceRoot: input.sourcePath })
    await maybeRunNpmInstall(tempPath, input.runCommand, ["ci", "--omit=dev"])
    if (input.buildSource === false) await maybeRunNpmSyncSkills(tempPath, input.runCommand)
    await rewriteCachedMcpManifest(tempPath, input.sourcePath)
    await rewriteCachedManifestRoot(tempPath, tempPath, targetPath)
    await assertHookCommandTargets(tempPath)
    await promoteDirectory(tempPath, targetPath, input.renameDirectory ?? rename)
  } catch (error) {
    await rm(tempPath, { recursive: true, force: true })
    throw error
  }
  return { name: input.name, version: input.version, path: targetPath }
}

async function maybeRunNpmInstall(cwd: string, runCommand: RunCommand, args: readonly string[] = ["install"]): Promise<void> {
  if (!(await fileExistsStrict(join(cwd, "package.json")))) return
  await runCommand("npm", args, { cwd })
}

async function maybeRunNpmBuild(cwd: string, runCommand: RunCommand): Promise<void> {
  if (!(await fileExistsStrict(join(cwd, "package.json")))) return
  const packageJson: unknown = JSON.parse(await readFile(join(cwd, "package.json"), "utf8"))
  if (!isPlainRecord(packageJson)) return
  const scripts = packageJson.scripts
  if (!isPlainRecord(scripts) || typeof scripts.build !== "string") return
  await runCommand("npm", ["run", "build"], { cwd })
}

async function maybeRunNpmSyncSkills(cwd: string, runCommand: RunCommand): Promise<void> {
  if (!(await fileExistsStrict(join(cwd, "package.json")))) return
  const packageJson: unknown = JSON.parse(await readFile(join(cwd, "package.json"), "utf8"))
  if (!isPlainRecord(packageJson)) return
  const scripts = packageJson.scripts
  if (!isPlainRecord(scripts) || typeof scripts["sync:skills"] !== "string") return
  await runCommand("npm", ["run", "sync:skills"], { cwd })
}

function createTempSiblingPath(targetPath: string): string {
  return join(dirname(targetPath), `.tmp-${basename(targetPath)}-${process.pid}-${Date.now()}`)
}

function createBackupSiblingPath(targetPath: string): string {
  return join(dirname(targetPath), `.backup-${basename(targetPath)}-${process.pid}-${Date.now()}`)
}

async function copyDirectory(sourcePath: string, targetPath: string): Promise<void> {
  await mkdir(dirname(targetPath), { recursive: true })
  await cp(sourcePath, targetPath, { recursive: true, filter: (source) => shouldCopyPluginPath(source, sourcePath) })
}

async function promoteDirectory(tempPath: string, targetPath: string, renameDirectory: RenameDirectory): Promise<void> {
  const backupPath = createBackupSiblingPath(targetPath)
  await rm(backupPath, { recursive: true, force: true })
  let backupMoved = false
  try {
    if (await fileExistsStrict(targetPath)) {
      await renameDirectory(targetPath, backupPath)
      backupMoved = true
    }
    await renameDirectory(tempPath, targetPath)
  } catch (error) {
    if (backupMoved) await restoreBackupDirectory(backupPath, targetPath, renameDirectory)
    throw error
  }
  if (backupMoved) await rm(backupPath, { recursive: true, force: true })
}

async function restoreBackupDirectory(backupPath: string, targetPath: string, renameDirectory: RenameDirectory): Promise<void> {
  if (!(await fileExistsStrict(backupPath))) return
  await rm(targetPath, { recursive: true, force: true })
  await renameDirectory(backupPath, targetPath)
}

function shouldCopyPluginPath(path: string, root: string): boolean {
  const relative = path === root ? "" : path.slice(root.length + sep.length)
  if (relative === "") return true
  const parts = relative.split(sep)
  return !parts.some((part) => part === ".git" || part === "node_modules")
}

import { lstat, readFile, readlink, rm } from "node:fs/promises"
import { join } from "node:path"
import { COMMAND_SHIM_MARKER } from "./codex-cache-command-shim"

type LinkPlatform = NodeJS.Platform

const LEGACY_CODEX_COMPONENT_BINS = [
  { name: "omo", component: "ulw-loop" },
  { name: "codex-comment-checker", component: "comment-checker" },
  { name: "codex-lsp", component: "lsp" },
  { name: "codex-rules", component: "rules" },
  { name: "codex-start-work-continuation", component: "start-work-continuation" },
  { name: "codex-telemetry", component: "telemetry" },
  { name: "codex-ultrawork", component: "ultrawork" },
] as const

type LegacyCodexComponent = (typeof LEGACY_CODEX_COMPONENT_BINS)[number]["component"]

export async function removeLegacyCodexComponentBins(binDir: string, platform: LinkPlatform): Promise<void> {
  for (const entry of LEGACY_CODEX_COMPONENT_BINS) {
    const linkPath = join(binDir, platform === "win32" ? `${entry.name}.cmd` : entry.name)
    await removeLegacyCodexComponentBin(linkPath, entry.component, platform)
  }
}

async function removeLegacyCodexComponentBin(linkPath: string, component: LegacyCodexComponent, platform: LinkPlatform): Promise<void> {
  try {
    const stat = await lstat(linkPath)
    if (platform !== "win32") {
      if (!stat.isSymbolicLink()) return
      const target = await readlink(linkPath)
      if (isManagedLegacyComponentTarget(target, component)) await rm(linkPath, { force: true })
      return
    }
    if (!stat.isFile()) return
    const content = await readFile(linkPath, "utf8")
    if (content.includes(COMMAND_SHIM_MARKER)) await rm(linkPath, { force: true })
  } catch (error) {
    if (isNodeErrorWithCode(error) && error.code === "ENOENT") return
    throw error
  }
}

function isManagedLegacyComponentTarget(target: string, component: LegacyCodexComponent): boolean {
  const parts = target.split(/[\\/]+/)
  const suffixStart = parts.length - 4
  const suffix = parts.slice(-4)
  return (
    suffix[0] === "components" &&
    suffix[1] === component &&
    suffix[2] === "dist" &&
    suffix[3] === "cli.js" &&
    (hasPluginCachePrefix(parts, suffixStart) || hasOmoCodexPluginPrefix(parts, suffixStart))
  )
}

function hasPluginCachePrefix(parts: readonly string[], endExclusive: number): boolean {
  for (let index = 0; index < endExclusive - 1; index += 1) {
    if (parts[index] === "plugins" && parts[index + 1] === "cache") return true
  }
  return false
}

function hasOmoCodexPluginPrefix(parts: readonly string[], endExclusive: number): boolean {
  for (let index = 0; index <= endExclusive - 3; index += 1) {
    if (parts[index] === "packages" && parts[index + 1] === "omo-codex" && parts[index + 2] === "plugin") return true
  }
  return false
}

function isNodeErrorWithCode(error: unknown): error is NodeJS.ErrnoException {
  return typeof error === "object" && error !== null && "code" in error
}

import { isPlainRecord } from "./codex-cache-fs"
import { realpathSync } from "node:fs"
import { readFile, readdir, writeFile } from "node:fs/promises"
import { dirname, isAbsolute, join, relative, resolve, sep } from "node:path"
import { isPathInside } from "./codex-cache-paths"

export async function rewriteCachedPackageLocalFileDependencies(pluginRoot: string, sourceRoot: string): Promise<void> {
  const packageJsonPaths: string[] = []
  await collectPackageJsonPaths(pluginRoot, pluginRoot, packageJsonPaths)
  const packageLock = await readPackageLock(pluginRoot)
  for (const packageJsonPath of packageJsonPaths) {
    const raw = await readFile(packageJsonPath, "utf8")
    const parsed: unknown = JSON.parse(raw)
    if (!isPlainRecord(parsed)) continue
    const packageDir = dirname(packageJsonPath)
    const sourcePackageDir = join(sourceRoot, relative(pluginRoot, packageDir))
    let changed = false
    for (const field of ["dependencies", "optionalDependencies", "peerDependencies"] as const) {
      const dependencies = parsed[field]
      if (!isPlainRecord(dependencies)) continue
      for (const [name, specifier] of Object.entries(dependencies)) {
        if (typeof specifier !== "string" || !specifier.startsWith("file:")) continue
        const filePath = specifier.slice("file:".length)
        if (filePath.length === 0 || isAbsolute(filePath)) continue
        const targetPath = resolve(packageDir, filePath)
        if (isPathInside(targetPath, pluginRoot)) continue
        const sourceTargetPath = resolve(sourcePackageDir, filePath)
        dependencies[name] = `file:${sourceTargetPath}`
        rewritePackageLockFileDependency({
          dependencyName: name,
          field,
          packageDir,
          packageLock,
          pluginRoot,
          sourceTargetPath,
          targetPath,
        })
        changed = true
      }
    }
    if (changed) await writeFile(packageJsonPath, `${JSON.stringify(parsed, null, "\t")}\n`)
  }
  if (packageLock.changed) await writeFile(packageLock.path, `${JSON.stringify(packageLock.value, null, "\t")}\n`)
}

type PackageLockState = {
  readonly path: string
  readonly value: Record<string, unknown> | null
  changed: boolean
}

async function readPackageLock(pluginRoot: string): Promise<PackageLockState> {
  const path = join(pluginRoot, "package-lock.json")
  try {
    const parsed: unknown = JSON.parse(await readFile(path, "utf8"))
    return { path, value: isPlainRecord(parsed) ? parsed : null, changed: false }
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT") {
      return { path, value: null, changed: false }
    }
    throw error
  }
}

function rewritePackageLockFileDependency(input: {
  readonly dependencyName: string
  readonly field: "dependencies" | "optionalDependencies" | "peerDependencies"
  readonly packageDir: string
  readonly packageLock: PackageLockState
  readonly pluginRoot: string
  readonly sourceTargetPath: string
  readonly targetPath: string
}): void {
  const packages = getPackageLockPackages(input.packageLock.value)
  if (!packages) return

  const lockRoot = canonicalizeExistingPath(input.pluginRoot)
  const packageKey = toPackageLockPath(relative(input.pluginRoot, input.packageDir))
  const oldTargetKey = toPackageLockPath(relative(input.pluginRoot, input.targetPath))
  const newTargetKey = toPackageLockPath(relative(lockRoot, input.sourceTargetPath))
  const newSpecifier = `file:${input.sourceTargetPath}`

  const packageEntry = packages[packageKey]
  if (isPlainRecord(packageEntry)) {
    const dependencyRecord = packageEntry[input.field]
    if (isPlainRecord(dependencyRecord) && dependencyRecord[input.dependencyName] !== newSpecifier) {
      dependencyRecord[input.dependencyName] = newSpecifier
      input.packageLock.changed = true
    }
  }

  if (oldTargetKey !== newTargetKey && isPlainRecord(packages[oldTargetKey])) {
    packages[newTargetKey] = packages[oldTargetKey]
    delete packages[oldTargetKey]
    input.packageLock.changed = true
  }

  const nodeModulesKey = `node_modules/${input.dependencyName}`
  const nodeModulesEntry = packages[nodeModulesKey]
  if (isPlainRecord(nodeModulesEntry) && nodeModulesEntry.resolved !== newTargetKey) {
    nodeModulesEntry.resolved = newTargetKey
    input.packageLock.changed = true
  }
}

function getPackageLockPackages(packageLock: Record<string, unknown> | null): Record<string, unknown> | null {
  if (!packageLock) return null
  const packages = packageLock.packages
  return isPlainRecord(packages) ? packages : null
}

function toPackageLockPath(path: string): string {
  return path.split(sep).join("/")
}

function canonicalizeExistingPath(path: string): string {
  try {
    return realpathSync(path)
  } catch (error) {
    if (error instanceof Error) return path
    throw error
  }
}

async function collectPackageJsonPaths(directory: string, root: string, paths: string[]): Promise<void> {
  const entries = await readdir(directory, { withFileTypes: true })
  if (entries.some((entry) => entry.isFile() && entry.name === "package.json")) {
    paths.push(join(directory, "package.json"))
  }
  for (const entry of entries) {
    if (!entry.isDirectory()) continue
    if (entry.name === "node_modules" || entry.name === ".git" || entry.name === "dist") continue
    const childPath = join(directory, entry.name)
    if (!isPathInside(childPath, root)) continue
    await collectPackageJsonPaths(childPath, root, paths)
  }
}

import { readFile, writeFile } from "node:fs/promises"
import { join, sep } from "node:path"
import { resolveCodegraphNodeRuntime } from "@oh-my-opencode/utils/codegraph/resolve"
import { resolveBundledMcpRuntimeArg } from "./codex-cache-bundled-mcps"
import { fileExistsStrict, isPlainRecord } from "./codex-cache-fs"
import { resolveCachedRuntimePath } from "./codex-cache-paths"

const CODEGRAPH_RELATIVE_ARGS = new Set(["components/codegraph/dist/serve.js", "./components/codegraph/dist/serve.js"])

export interface RewriteCachedMcpManifestOptions {
  readonly codegraphNodeRuntime?: () => string | null
}

export async function rewriteCachedMcpManifest(
  pluginRoot: string,
  sourceRoot = pluginRoot,
  options: RewriteCachedMcpManifestOptions = {},
): Promise<void> {
  const manifestPath = join(pluginRoot, ".mcp.json")
  if (!(await fileExistsStrict(manifestPath))) return
  const raw = await readFile(manifestPath, "utf8")
  const parsed: unknown = JSON.parse(raw)
  if (!isPlainRecord(parsed) || !isPlainRecord(parsed.mcpServers)) return
  let changed = false
  for (const server of Object.values(parsed.mcpServers)) {
    if (!isPlainRecord(server)) continue
    if (server.cwd === "." || server.cwd === "./") {
      delete server.cwd
      changed = true
    }
    const currentArgs = server.args
    if (!Array.isArray(currentArgs)) continue
    const nextArgs = currentArgs.map((arg) => {
      if (typeof arg !== "string") return arg
      const bundledMcpRuntimeArg = resolveBundledMcpRuntimeArg(pluginRoot, arg)
      if (bundledMcpRuntimeArg !== null) return bundledMcpRuntimeArg
      if (CODEGRAPH_RELATIVE_ARGS.has(arg)) return join(pluginRoot, "components", "codegraph", "dist", "serve.js")
      if (arg.startsWith("./") || arg.startsWith("../")) return resolveCachedRuntimePath(pluginRoot, sourceRoot, arg)
      return arg
    })
    if (nextArgs.some((value, index) => value !== currentArgs[index])) {
      server.args = nextArgs
      changed = true
    }
    if (server === parsed.mcpServers.codegraph) {
      const runtime = options.codegraphNodeRuntime?.() ?? resolveCodegraphNodeRuntime()
      if (runtime !== null && server.command === "node") {
        server.command = runtime
        changed = true
      }
    }
  }
  if (changed) await writeFile(manifestPath, `${JSON.stringify(parsed, null, "\t")}\n`)
}

export async function rewriteCachedManifestRoot(pluginRoot: string, fromRoot: string, toRoot: string): Promise<void> {
  const manifestPath = join(pluginRoot, ".mcp.json")
  if (!(await fileExistsStrict(manifestPath))) return
  const raw = await readFile(manifestPath, "utf8")
  const parsed: unknown = JSON.parse(raw)
  if (!isPlainRecord(parsed) || !isPlainRecord(parsed.mcpServers)) return
  let changed = false
  for (const server of Object.values(parsed.mcpServers)) {
    if (!isPlainRecord(server)) continue
    const currentArgs = server.args
    if (!Array.isArray(currentArgs)) continue
    const nextArgs = currentArgs.map((arg) => {
      if (typeof arg !== "string") return arg
      if (arg === fromRoot) return toRoot
      const prefix = `${fromRoot}${sep}`
      if (!arg.startsWith(prefix)) return arg
      return `${toRoot}${arg.slice(fromRoot.length)}`
    })
    if (nextArgs.some((value, index) => value !== currentArgs[index])) {
      server.args = nextArgs
      changed = true
    }
  }
  if (changed) await writeFile(manifestPath, `${JSON.stringify(parsed, null, "\t")}\n`)
}

