import { mkdir, readFile } from "node:fs/promises"
import { dirname } from "node:path"
import { ensureAgentConfig, removeStaleManagedAgentBlocks } from "./codex-config-agents"
import { writeFileAtomic } from "./codex-config-atomic-write"
import { ensureFeatureEnabled } from "./codex-config-features"
import {
  ensureMarketplaceBlock,
  hasMarketplaceBlock,
  legacyMarketplaceNames,
  removeMarketplaceBlock,
  removeStaleMarketplaceHookStateBlocks,
  removeStaleMarketplacePluginBlocks,
} from "./codex-config-marketplaces"
import { ensureAutonomousPermissions } from "./codex-config-permissions"
import { ensureHookTrusted, ensureOmoBuiltinMcpPolicies, ensurePluginEnabled } from "./codex-config-plugins"
import { ensureCodexReasoningConfig } from "./codex-config-reasoning"
import { readCodexModelCatalog } from "./codex-model-catalog"
import { removeUnsupportedCodexMultiAgentModeConfig } from "./codex-multi-agent-mode-config"
import { ensureCodexMultiAgentV2Config } from "./codex-multi-agent-v2-config"
import type { CodexAgentConfig, CodexInstallPlatform, CodexMarketplaceSource, TrustedHookState } from "./types"

export async function updateCodexConfig(input: {
  readonly configPath: string
  readonly repoRoot: string
  readonly marketplaceName: string
  readonly marketplaceSource: CodexMarketplaceSource
  readonly pluginNames: readonly string[]
  readonly platform?: CodexInstallPlatform
  readonly codegraphMcpEnabled?: boolean
  readonly gitBashEnabled?: boolean
  readonly trustedHookStates?: readonly TrustedHookState[]
  readonly agentConfigs?: readonly CodexAgentConfig[]
  readonly autonomousPermissions?: boolean
  readonly preserveMarketplaceSource?: boolean
}): Promise<void> {
  await mkdir(dirname(input.configPath), { recursive: true })
  let config = ""
  if (await exists(input.configPath)) config = await readFile(input.configPath, "utf8")

  const pluginSet = new Set(input.pluginNames)
  for (const legacyMarketplaceName of legacyMarketplaceNames(input.marketplaceName)) {
    config = removeMarketplaceBlock(config, legacyMarketplaceName)
    config = removeStaleMarketplacePluginBlocks(config, legacyMarketplaceName, new Set())
    config = removeStaleMarketplaceHookStateBlocks(config, legacyMarketplaceName, new Set())
  }
  config = removeStaleMarketplacePluginBlocks(config, input.marketplaceName, pluginSet)
  config = removeStaleMarketplaceHookStateBlocks(config, input.marketplaceName, pluginSet)
  config = removeStaleManagedAgentBlocks(
    config,
    new Set((input.agentConfigs ?? []).map((agentConfig) => agentConfig.name)),
  )
  config = ensureFeatureEnabled(config, "plugins")
  config = ensureFeatureEnabled(config, "plugin_hooks")
  config = ensureFeatureEnabled(config, "multi_agent")
  config = ensureFeatureEnabled(config, "child_agents_md")
  config = removeUnsupportedCodexMultiAgentModeConfig(config)
  config = ensureCodexReasoningConfig(config, await readCodexModelCatalog(input.repoRoot))
  config = ensureCodexMultiAgentV2Config(config)
  if (input.autonomousPermissions === true) config = ensureAutonomousPermissions(config)
  if (!(input.preserveMarketplaceSource === true && hasMarketplaceBlock(config, input.marketplaceName))) {
    config = ensureMarketplaceBlock(config, input.marketplaceName, input.marketplaceSource)
  }
  for (const pluginName of input.pluginNames) {
    config = ensurePluginEnabled(config, `${pluginName}@${input.marketplaceName}`)
  }
  config = ensureOmoBuiltinMcpPolicies(config, input)
  for (const state of input.trustedHookStates ?? []) {
    config = ensureHookTrusted(config, state)
  }
  for (const agentConfig of input.agentConfigs ?? []) {
    config = ensureAgentConfig(config, agentConfig)
  }

  await writeFileAtomic(input.configPath, `${config.trimEnd()}\n`)
}

async function exists(path: string): Promise<boolean> {
  try {
    await readFile(path, "utf8")
    return true
  } catch (error) {
    if (error instanceof Error) return false
    return false
  }
}

import { readFile, writeFile } from "node:fs/promises"
import { join } from "node:path"
import { fileExistsStrict, isPlainRecord } from "./codex-cache-fs"
import type { CodexInstallPlatform } from "./types"

const GIT_BASH_ENV_KEY = "OMO_CODEX_GIT_BASH_PATH"
const CODEGRAPH_RELATIVE_ARGS = new Set(["components/codegraph/dist/serve.js", "./components/codegraph/dist/serve.js"])

export async function stampGitBashMcpEnv(input: {
  readonly pluginRoot: string
  readonly env?: NodeJS.ProcessEnv
  readonly platform?: CodexInstallPlatform
}): Promise<boolean> {
  const manifestPath = join(input.pluginRoot, ".mcp.json")
  if (!(await fileExistsStrict(manifestPath))) return false
  const parsed: unknown = JSON.parse(await readFile(manifestPath, "utf8"))
  if (!isPlainRecord(parsed) || !isPlainRecord(parsed["mcpServers"])) return false

  let changed = stampCodegraphMcpPath(parsed["mcpServers"], input.pluginRoot)

  if (input.platform === "win32") {
    const rawOverride = input.env?.[GIT_BASH_ENV_KEY]
    const override = typeof rawOverride === "string" ? rawOverride.trim() : ""
    const gitBashServer = parsed["mcpServers"]["git_bash"]

    if (override !== "" && isPlainRecord(gitBashServer)) {
      const serverEnv = isPlainRecord(gitBashServer["env"]) ? gitBashServer["env"] : {}
      if (serverEnv[GIT_BASH_ENV_KEY] !== override) {
        gitBashServer["env"] = { ...serverEnv, [GIT_BASH_ENV_KEY]: override }
        changed = true
      }
    }
  }

  if (!changed) return false
  await writeFile(manifestPath, `${JSON.stringify(parsed, null, "\t")}\n`)
  return true
}

function stampCodegraphMcpPath(mcpServers: Record<string, unknown>, pluginRoot: string): boolean {
  const codegraphServer = mcpServers["codegraph"]
  if (!isPlainRecord(codegraphServer) || !Array.isArray(codegraphServer["args"])) return false

  const args = codegraphServer["args"]
  const entrypoint = args[0]
  if (typeof entrypoint !== "string" || !CODEGRAPH_RELATIVE_ARGS.has(entrypoint)) return false

  codegraphServer["args"] = [join(pluginRoot, "components", "codegraph", "dist", "serve.js"), ...args.slice(1)]
  return true
}

import { readFile } from "node:fs/promises"
import { join, sep } from "node:path"
import { fileExistsStrict, isPlainRecord } from "./codex-cache-fs"

const PLUGIN_ROOT_TARGET_PATTERN = /\$\{PLUGIN_ROOT\}[\\/]+([^"']+)/g

export async function findMissingHookCommandTargets(pluginRoot: string): Promise<readonly string[]> {
  const commands: string[] = []
  for (const manifestPath of await hookManifestPaths(pluginRoot)) {
    if (!(await fileExistsStrict(manifestPath))) continue
    const parsed: unknown = JSON.parse(await readFile(manifestPath, "utf8"))
    collectCommands(parsed, commands)
  }

  const missing: string[] = []
  const seen = new Set<string>()
  for (const command of commands) {
    for (const match of command.matchAll(PLUGIN_ROOT_TARGET_PATTERN)) {
      const targetSuffix = match[1]
      if (targetSuffix === undefined) continue
      const target = join(pluginRoot, ...targetSuffix.split(/[\\/]+/))
      if (seen.has(target)) continue
      seen.add(target)
      if (!(await fileExistsStrict(target))) missing.push(target)
    }
  }
  return missing
}

async function hookManifestPaths(pluginRoot: string): Promise<readonly string[]> {
  const pluginManifestPath = join(pluginRoot, ".codex-plugin", "plugin.json")
  if (!(await fileExistsStrict(pluginManifestPath))) return [join(pluginRoot, "hooks", "hooks.json")]
  const parsed: unknown = JSON.parse(await readFile(pluginManifestPath, "utf8"))
  if (!isPlainRecord(parsed)) return []
  if (typeof parsed.hooks === "string" && parsed.hooks.trim() !== "") {
    return [join(pluginRoot, stripDotSlash(parsed.hooks))]
  }
  if (Array.isArray(parsed.hooks)) {
    return parsed.hooks
      .filter((hookPath) => typeof hookPath === "string" && hookPath.trim() !== "")
      .map((hookPath) => join(pluginRoot, stripDotSlash(hookPath)))
  }
  return []
}

function stripDotSlash(path: string): string {
  return path.startsWith("./") ? path.slice(2) : path
}

export async function assertHookCommandTargets(pluginRoot: string): Promise<void> {
  const missing = await findMissingHookCommandTargets(pluginRoot)
  if (missing.length === 0) return
  const relativeMissing = missing.map((path) => path.split(`${pluginRoot}${sep}`).join("").split(sep).join("/"))
  throw new Error(
    `Plugin payload is missing ${missing.length} hook command target(s) referenced by hooks.json: ${relativeMissing.join(", ")}. ` +
      "The previous plugin cache was left untouched; this payload was not activated.",
  )
}

function collectCommands(value: unknown, commands: string[]): void {
  if (Array.isArray(value)) {
    for (const entry of value) collectCommands(entry, commands)
    return
  }
  if (!isPlainRecord(value)) return
  if (value["type"] === "command" && typeof value["command"] === "string") commands.push(value["command"])
  if (value["type"] === "command" && typeof value["commandWindows"] === "string") commands.push(value["commandWindows"])
  for (const entry of Object.values(value)) collectCommands(entry, commands)
}

