import { isPlainRecord } from "./codex-cache-fs"
import { readFile } from "node:fs/promises"
import { join } from "node:path"
import type {
  MarketplaceManifest,
  MarketplacePluginEntry,
  MarketplacePluginSourceLocal,
  PluginManifest,
} from "./types"

const DEFAULT_MARKETPLACE_PATH = "packages/omo-codex/marketplace.json"

export async function readMarketplace(
  repoRoot: string,
  options?: { readonly marketplacePath?: string },
): Promise<MarketplaceManifest> {
  const marketplacePath = options?.marketplacePath ?? join(repoRoot, DEFAULT_MARKETPLACE_PATH)
  const raw = await readFile(marketplacePath, "utf8")
  const parsed: unknown = JSON.parse(raw)
  if (!isPlainRecord(parsed)) throw new Error("marketplace.json must be an object")
  if (typeof parsed.name !== "string" || parsed.name.trim() === "") {
    throw new Error("marketplace.json name must be a non-empty string")
  }
  validatePathSegment(parsed.name, "marketplace name")
  if (!Array.isArray(parsed.plugins)) throw new Error("marketplace.json plugins must be an array")
  return {
    name: parsed.name,
    plugins: parsed.plugins.map((plugin, index) => normalizeMarketplacePlugin(plugin, index)),
  }
}

export function resolvePluginSource(
  repoRoot: string,
  plugin: MarketplacePluginEntry,
  options?: { readonly pathOverride?: string },
): string {
  const sourcePath = localSourcePath(options?.pathOverride ?? plugin.source)
  const relativePath = sourcePath.slice(2)
  return join(repoRoot, ...relativePath.split(/[\\/]/))
}

export async function readPluginManifest(pluginRoot: string): Promise<PluginManifest> {
  const raw = await readFile(join(pluginRoot, ".codex-plugin", "plugin.json"), "utf8")
  const parsed: unknown = JSON.parse(raw)
  if (!isPlainRecord(parsed)) throw new Error(`${pluginRoot} plugin.json must be an object`)
  if (typeof parsed.name !== "string" || parsed.name.trim() === "") {
    throw new Error(`${pluginRoot} plugin.json name must be a non-empty string`)
  }
  if (parsed.version !== undefined && (typeof parsed.version !== "string" || parsed.version.trim() === "")) {
    throw new Error(`${pluginRoot} plugin.json version must be a non-empty string`)
  }
  if (parsed.hooks !== undefined && !isPluginHooksManifestValue(parsed.hooks)) {
    throw new Error(`${pluginRoot} plugin.json hooks must be a non-empty string or string array`)
  }
  return {
    name: parsed.name,
    version: typeof parsed.version === "string" ? parsed.version.trim() : undefined,
    hooks: normalizePluginHooksManifestValue(parsed.hooks),
  }
}

function isPluginHooksManifestValue(value: unknown): boolean {
  if (typeof value === "string") return value.trim() !== ""
  return Array.isArray(value) && value.every((item) => typeof item === "string" && item.trim() !== "")
}

function normalizePluginHooksManifestValue(value: unknown): string | readonly string[] | undefined {
  if (typeof value === "string") return value.trim()
  if (Array.isArray(value)) return value.map((item) => item.trim())
  return undefined
}

export function validatePathSegment(value: string, label: string): void {
  if (!/^[A-Za-z0-9._+-]+$/.test(value)) {
    throw new Error(`${label} contains unsupported characters: ${value}`)
  }
  if (value === "." || value === "..") {
    throw new Error(`${label} must not be a path traversal segment`)
  }
}

function normalizeMarketplacePlugin(plugin: unknown, index: number): MarketplacePluginEntry {
  if (!isPlainRecord(plugin)) throw new Error(`marketplace plugin ${index} must be an object`)
  if (typeof plugin.name !== "string" || plugin.name.trim() === "") {
    throw new Error(`marketplace plugin ${index} name must be a non-empty string`)
  }
  validatePathSegment(plugin.name, "plugin name")
  if (plugin.source === undefined || typeof plugin.source === "string") {
    if (typeof plugin.source === "string") {
      validateLocalSourcePath(plugin.source)
    }
    return { name: plugin.name, source: plugin.source }
  }
  if (isPlainRecord(plugin.source) && plugin.source.source === "local" && typeof plugin.source.path === "string") {
    validateLocalSourcePath(plugin.source.path)
    const local: MarketplacePluginSourceLocal = { source: "local", path: plugin.source.path }
    return { name: plugin.name, source: local }
  }
  throw new Error("local plugin source must be a string path or { source: \"local\", path } object")
}

function localSourcePath(source: string | MarketplacePluginSourceLocal | undefined): string {
  if (typeof source === "string") return validateLocalSourcePath(source)
  if (source?.source === "local") return validateLocalSourcePath(source.path)
  throw new Error("local plugin source path is required")
}

function validateLocalSourcePath(path: string): string {
  if (!path.startsWith("./")) throw new Error("local plugin source path must start with ./")
  const relative = path.slice(2)
  if (relative.length === 0) throw new Error("local plugin source path must not be empty")
  for (const part of relative.split(/[\\/]/)) {
    if (part === "" || part === "." || part === "..") {
      throw new Error("local plugin source path must stay within the marketplace root")
    }
  }
  return path
}

import { isPlainRecord } from "./codex-cache-fs"
import { readFile } from "node:fs/promises"
import { join } from "node:path"

export type CodexReasoningProfile = {
  readonly model: string
  readonly modelContextWindow: number
  readonly modelReasoningEffort: string
  readonly planModeReasoningEffort: string
}

export type CodexReasoningProfileMatch = Partial<CodexReasoningProfile>

export type CodexModelCatalog = {
  readonly current: CodexReasoningProfile
  readonly managedProfiles: readonly CodexReasoningProfileMatch[]
}

const FALLBACK_CODEX_MODEL_CATALOG: CodexModelCatalog = {
  current: {
    model: "gpt-5.5",
    modelContextWindow: 400_000,
    modelReasoningEffort: "high",
    planModeReasoningEffort: "xhigh",
  },
  managedProfiles: [
    {
      model: "gpt-5.5",
      modelContextWindow: 1_000_000,
      modelReasoningEffort: "high",
      planModeReasoningEffort: "xhigh",
    },
    { model: "gpt-5.5", modelContextWindow: 272_000 },
  ],
}

export async function readCodexModelCatalog(codexPackageRoot: string): Promise<CodexModelCatalog> {
  const catalogPath = join(codexPackageRoot, "plugin", "model-catalog.json")
  try {
    const parsed: unknown = JSON.parse(await readFile(catalogPath, "utf8"))
    return parseCodexModelCatalog(parsed) ?? FALLBACK_CODEX_MODEL_CATALOG
  } catch (error) {
    if (error instanceof Error) return FALLBACK_CODEX_MODEL_CATALOG
    throw error
  }
}

export async function readCodexReasoningProfile(codexPackageRoot: string): Promise<CodexReasoningProfile> {
  return (await readCodexModelCatalog(codexPackageRoot)).current
}

function parseCodexModelCatalog(value: unknown): CodexModelCatalog | null {
  if (!isPlainRecord(value)) return null
  const current = value["current"]
  const managedProfiles = value["managedProfiles"]
  if (!isPlainRecord(current) || !Array.isArray(managedProfiles)) return null
  const model = current["model"]
  const modelContextWindow = current["model_context_window"]
  const modelReasoningEffort = current["model_reasoning_effort"]
  const planModeReasoningEffort = current["plan_mode_reasoning_effort"]
  if (
    typeof model !== "string" ||
    typeof modelContextWindow !== "number" ||
    typeof modelReasoningEffort !== "string" ||
    typeof planModeReasoningEffort !== "string"
  ) {
    return null
  }
  const parsedManagedProfiles: CodexReasoningProfileMatch[] = []
  for (const profile of managedProfiles) {
    if (!isPlainRecord(profile)) return null
    const match = profile["match"]
    if (!isPlainRecord(match)) return null
    parsedManagedProfiles.push(parseProfileMatch(match))
  }
  return {
    current: { model, modelContextWindow, modelReasoningEffort, planModeReasoningEffort },
    managedProfiles: parsedManagedProfiles,
  }
}

function parseProfileMatch(match: Record<string, unknown>): CodexReasoningProfileMatch {
  const profile: {
    model?: string
    modelContextWindow?: number
    modelReasoningEffort?: string
    planModeReasoningEffort?: string
  } = {}
  if (typeof match["model"] === "string") profile.model = match["model"]
  if (typeof match["model_context_window"] === "number") profile.modelContextWindow = match["model_context_window"]
  if (typeof match["model_reasoning_effort"] === "string") profile.modelReasoningEffort = match["model_reasoning_effort"]
  if (typeof match["plan_mode_reasoning_effort"] === "string") profile.planModeReasoningEffort = match["plan_mode_reasoning_effort"]
  return profile
}

import { isTomlTableHeaderLine } from "./toml-section-editor"

const CODEX_MULTI_AGENT_MODE_KEY = "multi_agent_mode"

export function removeUnsupportedCodexMultiAgentModeConfig(config: string): string {
  const lines = config.split(/\n/)
  const output: string[] = []
  let inRoot = true
  let changed = false
  for (const line of lines) {
    const sectionHeader = isSectionHeader(line)
    if (inRoot && isRootSetting(line, CODEX_MULTI_AGENT_MODE_KEY)) {
      changed = true
      continue
    }
    output.push(line)
    if (sectionHeader) inRoot = false
  }
  return changed ? output.join("\n") : config
}

function isSectionHeader(line: string): boolean {
  return isTomlTableHeaderLine(line)
}

function isRootSetting(line: string, key: string): boolean {
  const trimmed = line.trimStart()
  if (trimmed.startsWith("#") || trimmed.startsWith("[")) return false
  const match = trimmed.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*=/)
  return match?.[1] === key
}

import { appendBlock, findTomlSection, removeSetting, replaceOrInsertSetting } from "./toml-section-editor"

const CODEX_MULTI_AGENT_V2_HEADER = "features.multi_agent_v2"
const CODEX_MULTI_AGENT_V2_MAX_CONCURRENT_THREADS_PER_SESSION = 10000

/**
 * Configure multi_agent_v2 thread limits without forcing the feature on.
 *
 * Whether V2 is active is determined at runtime by the model's server-side
 * catalog entry (`ModelInfo.multi_agent_version`).  Forcing `enabled = true`
 * in config breaks models whose API does not support encrypted tool
 * parameters (e.g. gpt-5.5-medium, API-key-only models, third-party
 * providers).  The installer therefore only sets the tuning knob
 * (`max_concurrent_threads_per_session`) so that sessions that DO activate
 * V2 benefit from the higher limit.
 */
export function ensureCodexMultiAgentV2Config(config: string): string {
  const normalizedConfig = removeLegacyAgentsMaxThreadsSetting(removeFeatureFlagSetting(config, "multi_agent_v2"))
  const section = findTomlSection(normalizedConfig, CODEX_MULTI_AGENT_V2_HEADER)
  const maxThreadsValue = CODEX_MULTI_AGENT_V2_MAX_CONCURRENT_THREADS_PER_SESSION.toString()
  if (!section) {
    return appendBlock(
      normalizedConfig,
      `[${CODEX_MULTI_AGENT_V2_HEADER}]\nmax_concurrent_threads_per_session = ${maxThreadsValue}\n`,
    )
  }

  return replaceOrInsertSetting(normalizedConfig, section, "max_concurrent_threads_per_session", maxThreadsValue)
}

function removeFeatureFlagSetting(config: string, featureName: string): string {
  const section = findTomlSection(config, "features")
  if (!section) return config
  return removeSetting(config, section, featureName)
}

function removeLegacyAgentsMaxThreadsSetting(config: string): string {
  const section = findTomlSection(config, "agents")
  if (!section) return config
  return removeSetting(config, section, "max_threads")
}

