export async function runLazyCodexInstallLocalCli(input: {
  readonly argv: readonly string[]
  readonly defaultRepoRoot: string
  readonly entrypointPath: string
  readonly invokedPath?: string
  readonly cwd: string
  readonly env: NodeJS.ProcessEnv
  readonly log: (line: string) => void
}): Promise<number> {
  const parsed = parseLazyCodexInstallCliArgs(input.argv)
  if (parsed.kind === "help") {
    input.log(formatLazyCodexInstallHelp())
    return 0
  }
  if (parsed.kind === "version") {
    const packageJson = JSON.parse(await readFile(join(input.defaultRepoRoot, "package.json"), "utf8")) as { readonly version?: unknown }
    const version = typeof packageJson.version === "string" ? packageJson.version : "unknown"
    input.log(`lazycodex-ai ${version}`)
    return 0
  }
  if (parsed.kind === "command") {
    await runDelegatedOmoCommand(parsed, { cwd: input.cwd, log: input.log, runCommand: defaultRunCommand })
    return 0
  }
  if (parsed.kind === "update") {
    if (parsed.repoRoot) {
      if (parsed.dryRun) {
        input.log(`node ${input.entrypointPath} install --repo-root=${parsed.repoRoot}`)
        return 0
      }
      const result = await installMarketplaceLocally({
        repoRoot: resolve(parsed.repoRoot),
        autonomousPermissions: true,
        env: input.env,
      })
      input.log(`Installed ${result.installed.length} plugin(s) from ${result.marketplaceName}.`)
      return 0
    }
    return runLazyCodexManualUpdate({ env: input.env, dryRun: parsed.dryRun, log: input.log, invokedPath: input.invokedPath })
  }

  const repoRoot = parsed.repoRoot ? resolve(parsed.repoRoot) : input.defaultRepoRoot
  const result = await installMarketplaceLocally({
    repoRoot,
    autonomousPermissions: parsed.autonomousPermissions,
    env: input.env,
  })
  input.log(`Installed ${result.installed.length} plugin(s) from ${result.marketplaceName}.`)
  return 0
}

import { join } from "node:path"

export function isBunGlobalEntrypointPath(invokedPath: string | undefined, env: NodeJS.ProcessEnv): boolean {
  if (typeof invokedPath !== "string" || invokedPath.trim().length === 0) return false
  const normalizedPath = normalizePathForPrefix(invokedPath)
  return resolveBunGlobalRoots(env).some((root) => normalizedPath.startsWith(root))
}

function resolveBunGlobalRoots(env: NodeJS.ProcessEnv): readonly string[] {
  const bunInstallRoot = env.BUN_INSTALL?.trim()
  const homeRoot = env.HOME?.trim()
  return [
    ...(bunInstallRoot ? [join(bunInstallRoot, "bin"), join(bunInstallRoot, "install", "global", "node_modules")] : []),
    ...(homeRoot ? [join(homeRoot, ".bun", "bin"), join(homeRoot, ".bun", "install", "global", "node_modules")] : []),
  ].map(normalizePathForPrefix)
}

function normalizePathForPrefix(path: string): string {
  const normalized = path.replaceAll("\\", "/").replace(/\/+$/, "")
  return normalized.endsWith("/node_modules") || normalized.endsWith("/bin") ? `${normalized}/` : normalized
}

const CODEX_ONLY_ERROR = "lazycodex-ai installs the Codex Light edition only. Use the omo installer for OpenCode or both-platform installs."

export const PASSTHROUGH_COMMANDS: ReadonlySet<string> = new Set([
  "doctor",
  "cleanup",
  "get-local-version",
  "boulder",
  "refresh-model-capabilities",
  "run",
  "ulw-loop",
] as const)

export type LazyCodexInstallCliArgs =
  | { readonly kind: "install"; readonly autonomousPermissions: boolean | undefined; readonly repoRoot: string | undefined }
  | { readonly kind: "help" }
  | { readonly kind: "version" }
  | {
      readonly kind: "command"
      readonly command: string
      readonly dryRun: boolean
      readonly noTui?: boolean
      readonly skipAuth?: boolean
      readonly autonomousPermissions?: boolean
      readonly repoRoot?: string
      readonly args: readonly string[]
    }
  | { readonly kind: "update"; readonly dryRun: boolean; readonly repoRoot: string | undefined }

export function parseLazyCodexInstallCliArgs(argv: readonly string[]): LazyCodexInstallCliArgs {
  const args = [...argv]
  if (args.length === 0) return { kind: "install", autonomousPermissions: undefined, repoRoot: undefined }

  let repoRoot: string | undefined
  let command: "install" | undefined
  let dryRun = false
  let noTui = false
  let skipAuth = false
  let autonomousPermissions: boolean | undefined
  let index = 0
  while (index < args.length) {
    const arg = args[index]
    if (arg === "--help" || arg === "-h" || arg === "help") return { kind: "help" }
    if (arg === "--version" || arg === "-v" || arg === "version") return { kind: "version" }
    if (arg === "--dry-run") {
      dryRun = true
      index += 1
      continue
    }
    if (arg === "--no-tui") {
      noTui = true
      index += 1
      continue
    }
    if (arg === "--skip-auth") {
      skipAuth = true
      index += 1
      continue
    }
    if (arg === "--codex-autonomous") {
      autonomousPermissions = true
      index += 1
      continue
    }
    if (arg === "--no-codex-autonomous") {
      autonomousPermissions = false
      index += 1
      continue
    }
    if (arg === "--platform") {
      const platform = readOptionValue(args, index, "--platform")
      if (platform !== "codex") throw new Error(CODEX_ONLY_ERROR)
      index += 2
      continue
    }
    if (typeof arg === "string" && arg.startsWith("--platform=")) {
      const platform = arg.slice("--platform=".length)
      if (platform.trim().length === 0) throw new Error("--platform requires a value")
      if (platform !== "codex") throw new Error(CODEX_ONLY_ERROR)
      index += 1
      continue
    }
    if (arg === "--repo-root") {
      repoRoot = readOptionValue(args, index, "--repo-root")
      index += 2
      continue
    }
    if (typeof arg === "string" && arg.startsWith("--repo-root=")) {
      const value = arg.slice("--repo-root=".length)
      if (value.trim().length === 0) throw new Error("--repo-root requires a path")
      repoRoot = value
      index += 1
      continue
    }
    if (arg === "install" || arg === "setup") {
      if (command !== undefined) throw new Error(`Unsupported lazycodex-ai install option: ${String(arg)}`)
      command = "install"
      index += 1
      continue
    }
    if (arg === "update") {
      return parseUpdateArgs(args, index + 1, dryRun, repoRoot)
    }
    if (arg === "uninstall") {
      return { kind: "command", command: "cleanup", dryRun, args: args.slice(index + 1) }
    }
    if (PASSTHROUGH_COMMANDS.has(arg)) {
      return { kind: "command", command: arg, dryRun, args: args.slice(index + 1) }
    }
    if (command === undefined && typeof arg === "string" && !arg.startsWith("-")) {
      throw new Error(`Unsupported lazycodex-ai command: ${String(arg)}`)
    }
    throw new Error(`Unsupported lazycodex-ai install option: ${String(arg)}`)
  }

  if (!dryRun) return { kind: "install", autonomousPermissions, repoRoot }

  return {
    kind: "command",
    command: command ?? "install",
    dryRun,
    noTui,
    skipAuth,
    autonomousPermissions,
    repoRoot,
    args: [],
  }
}

function parseUpdateArgs(
  args: readonly string[],
  startIndex: number,
  initialDryRun: boolean,
  initialRepoRoot: string | undefined,
): LazyCodexInstallCliArgs {
  let dryRun = initialDryRun
  let repoRoot = initialRepoRoot
  let index = startIndex
  while (index < args.length) {
    const updateArg = args[index]
    if (updateArg === "--dry-run") {
      dryRun = true
      index += 1
      continue
    }
    if (updateArg === "--repo-root") {
      repoRoot = readOptionValue(args, index, "--repo-root")
      index += 2
      continue
    }
    if (typeof updateArg === "string" && updateArg.startsWith("--repo-root=")) {
      const value = updateArg.slice("--repo-root=".length)
      if (value.trim().length === 0) throw new Error("--repo-root requires a path")
      repoRoot = value
      index += 1
      continue
    }
    throw new Error(`Unsupported lazycodex-ai update option: ${String(updateArg)}`)
  }
  return { kind: "update", dryRun, repoRoot }
}

function readOptionValue(args: readonly string[], index: number, option: string): string {
  const value = args[index + 1]
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new Error(`${option} requires a value`)
  }
  return value
}

export function formatLazyCodexInstallHelp(): string {
  const passthrough = [...PASSTHROUGH_COMMANDS].sort().join(", ")
  return [
    "Usage: lazycodex-ai install [--no-tui] [--codex-autonomous|--no-codex-autonomous] [--repo-root <path>]",
    "       lazycodex-ai uninstall [--project <path>]",
    "       lazycodex-ai update [--dry-run] [--repo-root <path>]",
    "       lazycodex-ai version",
    "       lazycodex-ai <command> [args...]",
    "",
    "Installs or removes the Codex Light edition in ~/.codex using Node/npm.",
    "`uninstall` removes managed Codex Light state; `cleanup` is a backward-compatible alias.",
    "`update` refreshes the installed Codex Light edition in place.",
    "",
    `Commands supported by lazycodex-ai: ${passthrough}.`,
    "`doctor` runs the Codex LazyCodex doctor workflow; other pass-through commands delegate to the omo CLI.",
  ].join("\n")
}

import type { RunCommand } from "./types"
import type { LazyCodexInstallCliArgs } from "./lazycodex-cli-args"

export type LazyCodexDelegatedCommand = Extract<LazyCodexInstallCliArgs, { readonly kind: "command" }>

export type DelegatedOmoInvocation = {
  readonly command: string
  readonly args: readonly string[]
  readonly delegatesToOmo: boolean
  readonly env?: Readonly<Record<string, string>>
}

export async function runDelegatedOmoCommand(
  parsed: LazyCodexDelegatedCommand,
  options: {
    readonly cwd: string
    readonly log: (line: string) => void
    readonly runCommand: RunCommand
  },
): Promise<void> {
  if (parsed.command === "doctor" && process.env.LAZYCODEX_DOCTOR_LCX_ACTIVE === "1") {
    throw new Error("Refusing recursive lazycodex doctor invocation from inside $omo:lcx-doctor")
  }
  const invocation = buildDelegatedOmoInvocation(parsed)
  if (parsed.dryRun) {
    options.log(formatShellCommand(invocation.command, invocation.args))
    return
  }
  const env = invocation.delegatesToOmo
    ? { ...process.env, OMO_INVOCATION_NAME: "omo", ...invocation.env }
    : { ...process.env, ...invocation.env }
  await options.runCommand(invocation.command, invocation.args, { cwd: options.cwd, env })
}

export function buildDelegatedOmoInvocation(parsed: LazyCodexDelegatedCommand): DelegatedOmoInvocation {
  if (parsed.command === "doctor") return buildLazyCodexDoctorInvocation(parsed.args)

  const args = ["--yes", "--package", "oh-my-openagent", "omo", parsed.command]
  if (parsed.command === "install") {
    args.push("--platform=codex")
    if (parsed.noTui) args.push("--no-tui")
    if (parsed.skipAuth) args.push("--skip-auth")
    if (parsed.autonomousPermissions !== false) args.push("--codex-autonomous")
    if (parsed.autonomousPermissions === false) args.push("--no-codex-autonomous")
    if (parsed.repoRoot) args.push(`--repo-root=${parsed.repoRoot}`)
  } else if (parsed.command === "cleanup") {
    args.push("--platform=codex", ...parsed.args)
  } else {
    args.push(...parsed.args)
  }
  return { command: "npx", args, delegatesToOmo: true }
}

function buildLazyCodexDoctorInvocation(doctorArgs: readonly string[]): DelegatedOmoInvocation {
  return {
    command: "codex",
    args: [
      "exec",
      "--ephemeral",
      "--sandbox",
      "read-only",
      "--skip-git-repo-check",
      "--cd",
      ".",
      buildLazyCodexDoctorPrompt(doctorArgs),
    ],
    delegatesToOmo: false,
    env: {
      LAZYCODEX_DOCTOR_LCX_ACTIVE: "1",
    },
  }
}

function buildLazyCodexDoctorPrompt(doctorArgs: readonly string[]): string {
  return [
    "Use $omo:lcx-doctor to diagnose this LazyCodex/Codex installation.",
    "This command is already the lazycodex doctor surface; never invoke lazycodex doctor from inside the doctor workflow.",
    "Sync the latest LazyCodex and OpenAI Codex sources into /tmp, inventory the local installation,",
    "probe the Codex plugin/cache/hooks/MCP state, and report PASS/WARN/FAIL findings with evidence and remediations.",
    buildDoctorOutputInstruction(doctorArgs),
    doctorArgs.length > 0 ? `Requested doctor arguments: ${doctorArgs.join(" ")}` : "Requested doctor arguments: none",
  ].join(" ")
}

function buildDoctorOutputInstruction(doctorArgs: readonly string[]): string {
  if (doctorArgs.includes("--json")) {
    return "Return exactly one JSON object with summary, environment, checks, remediations, and knownIssues fields; do not wrap it in Markdown."
  }
  return "Return the standard Markdown LazyCodex Doctor Report."
}

function formatShellCommand(command: string, args: readonly string[]): string {
  return [command, ...args].map(shellQuote).join(" ")
}

function shellQuote(value: string): string {
  if (/^[A-Za-z0-9_/:=.,@%+-]+$/.test(value)) return value
  return `'${value.replaceAll("'", "'\\''")}'`
}

