import { createRepoWithBuiltComponentBins, EXPECTED_OMO_COMPONENT_BINS, expectedBinName } from "./install-codex-test-fixtures"

const STALE_CODEX_COMPONENT_BINS = [
  "codex-comment-checker",
  "codex-rules",
  "codex-start-work-continuation",
  "codex-telemetry",
  "codex-ultrawork",
] as const

const LAZYCODEX_AGENT_ROLE_NAMES = [
  "lazycodex-clone-fidelity-reviewer",
  "lazycodex-code-reviewer",
  "lazycodex-executor",
  "lazycodex-gate-reviewer",
  "lazycodex-qa-executor",
] as const

const INSTALL_CODEX_INTEGRATION_TEST_TIMEOUT_MS = process.platform === "win32" ? 60_000 : 20_000

const skipAstGrepInstall = async () => ({ kind: "skipped" as const, reason: "test" })

describe("lazycodex install surface", () => {
  test("#given codex installer #when installing omo #then exposes durable LazyCodex agent roles", async () => {
    // given
    const codexHome = await mkdtemp(join(tmpdir(), "omo-codex-home-lazycodex-agents-"))
    const binDir = await mkdtemp(join(tmpdir(), "omo-codex-bin-lazycodex-agents-"))

    // when
    await runCodexInstaller({ codexHome, binDir, repoRoot: process.cwd(), astGrepInstaller: skipAstGrepInstall, runCommand: async () => undefined })

    // then
    const configContent = await readFile(join(codexHome, "config.toml"), "utf8")
    for (const agentName of LAZYCODEX_AGENT_ROLE_NAMES) {
      expect(configContent).toContain(`[agents.${agentName}]`)
      expect(configContent).toContain(`config_file = "./agents/${agentName}.toml"`)
      const agentFile = join(codexHome, "agents", `${agentName}.toml`)
      expect((await stat(agentFile)).isFile()).toBe(true)
      expect(await readFile(agentFile, "utf8")).toContain(`name = "${agentName}"`)
    }
  }, { timeout: INSTALL_CODEX_INTEGRATION_TEST_TIMEOUT_MS })

  test("#given codex installer #when installing omo #then links documented component binaries to cached runtimes", async () => {
    // given
    const codexHome = await mkdtemp(join(tmpdir(), "omo-codex-home-bins-"))
    const binDir = await mkdtemp(join(tmpdir(), "omo-codex-bin-bins-"))
    const repoRoot = await createRepoWithBuiltComponentBins()

    // when
    const result = await runCodexInstaller({ codexHome, binDir, repoRoot, astGrepInstaller: skipAstGrepInstall, runCommand: async () => undefined })

    // then
    const pluginPath = result.installed[0]?.path ?? ""
    const linkedNames = (await readdir(binDir)).sort()
    expect(linkedNames).toEqual(EXPECTED_OMO_COMPONENT_BINS.map((entry) => expectedBinName(entry.name)).sort())
    for (const entry of EXPECTED_OMO_COMPONENT_BINS) {
      const linkPath = join(binDir, expectedBinName(entry.name))
      if ("kind" in entry && entry.kind === "runtime-wrapper") {
        const expectedTarget = join(repoRoot, entry.target)
        expect((await stat(linkPath)).isFile()).toBe(true)
        const wrapper = await readFile(linkPath, "utf8")
        expect(wrapper).toContain("OMO_GENERATED_RUNTIME_WRAPPER")
        expect(wrapper).toContain(expectedTarget)
        expect(wrapper).toContain("CODEX_HOME")
        expect(wrapper).toContain("OMO_SPARKSHELL_APP_SERVER_SOCKET")
        expect(wrapper).toContain("omo-ulw-loop")
        expect(wrapper).toContain("bun runtime not found")
        expect(wrapper).toContain("https://bun.sh")
      } else if (process.platform === "win32") {
        const expectedTarget = join(pluginPath, entry.target)
        expect((await stat(linkPath)).isFile()).toBe(true)
        expect(await readFile(linkPath, "utf8")).toContain(expectedTarget)
      } else {
        const expectedTarget = join(pluginPath, entry.target)
        expect(await readlink(linkPath)).toBe(expectedTarget)
        expect((await stat(expectedTarget)).isFile()).toBe(true)
      }
    }
    for (const staleName of STALE_CODEX_COMPONENT_BINS) {
      expect(linkedNames).not.toContain(staleName)
      expect(linkedNames).not.toContain(`${staleName}.cmd`)
    }
  }, { timeout: INSTALL_CODEX_INTEGRATION_TEST_TIMEOUT_MS })

  test("#given installation guide #when component binaries and LazyCodex roles are documented #then docs match install surface", async () => {
    // given
    const installationGuide = await readFile(join(process.cwd(), "docs", "guide", "installation.md"), "utf8")

    // when
    const componentBinNames = EXPECTED_OMO_COMPONENT_BINS.map((entry) => entry.name)

    // then
    for (const name of componentBinNames) {
      expect(installationGuide).toContain(name)
    }
    for (const staleName of STALE_CODEX_COMPONENT_BINS) {
      expect(installationGuide).not.toContain(`~/.local/bin/${staleName}`)
      expect(installationGuide).not.toContain(`command not found: ${staleName}`)
    }
    expect(installationGuide).toContain("~/.codex/agents/{")
    expect(installationGuide).toContain("}.toml")
    for (const agentName of LAZYCODEX_AGENT_ROLE_NAMES) {
      expect(installationGuide).toContain(agentName)
    }
  })

  test("#given Codex prunes an old plugin cache version #when LazyCodex roles were installed #then roles still resolve from Codex home", async () => {
    // given
    const codexHome = await mkdtemp(join(tmpdir(), "omo-codex-home-autoupdate-"))
    const binDir = await mkdtemp(join(tmpdir(), "omo-codex-bin-autoupdate-"))
    const marketplaceRoot = join(codexHome, ".tmp", "marketplaces", "sisyphuslabs")
    await mkdir(join(marketplaceRoot, ".git"), { recursive: true })
    await writeFile(join(marketplaceRoot, ".git", "config"), "[remote \"origin\"]\n")
    await writeFile(join(marketplaceRoot, ".codex-marketplace-install.json"), '{"source_type":"git"}\n')

    // when
    const result = await runCodexInstaller({ codexHome, binDir, repoRoot: process.cwd(), astGrepInstaller: skipAstGrepInstall, runCommand: async () => undefined })
    const pluginPath = result.installed[0]?.path
    if (pluginPath === undefined) {
      throw new Error("Codex installer did not report an installed plugin path")
    }
    await rm(pluginPath, { recursive: true, force: true })

    // then
    const agentName = "lazycodex-gate-reviewer"
    const agentPath = join(codexHome, "agents", `${agentName}.toml`)
    const snapshotAgentPath = join(marketplaceRoot, "plugins", "omo", "components", "ultrawork", "agents", `${agentName}.toml`)
    expect((await stat(agentPath)).isFile()).toBe(true)
    expect(await readFile(agentPath, "utf8")).toBe(await readFile(snapshotAgentPath, "utf8"))
    expect(await readFile(agentPath, "utf8")).toContain(`name = "${agentName}"`)
    expect(await readFile(join(marketplaceRoot, ".git", "config"), "utf8")).toBe("[remote \"origin\"]\n")
    expect(await readFile(join(marketplaceRoot, ".codex-marketplace-install.json"), "utf8")).toBe(
      '{"source_type":"git"}\n',
    )
  }, { timeout: INSTALL_CODEX_INTEGRATION_TEST_TIMEOUT_MS })

  test("#given Codex temporary marketplace snapshot is removed #when LazyCodex roles were installed #then roles still resolve from Codex home", async () => {
    // given
    const codexHome = await mkdtemp(join(tmpdir(), "omo-codex-home-clean-snapshot-"))
    const binDir = await mkdtemp(join(tmpdir(), "omo-codex-bin-clean-snapshot-"))

    // when
    await runCodexInstaller({ codexHome, binDir, repoRoot: process.cwd(), astGrepInstaller: skipAstGrepInstall, runCommand: async () => undefined })
    await rm(join(codexHome, ".tmp", "marketplaces", "sisyphuslabs"), { recursive: true, force: true })
    await rm(join(codexHome, "plugins", "cache", "sisyphuslabs"), { recursive: true, force: true })

    // then
    const agentName = "lazycodex-code-reviewer"
    const configContent = await readFile(join(codexHome, "config.toml"), "utf8")
    expect(configContent).toContain(`config_file = "./agents/${agentName}.toml"`)
    expect(await readFile(join(codexHome, "agents", `${agentName}.toml`), "utf8")).toContain(`name = "${agentName}"`)
  }, { timeout: INSTALL_CODEX_INTEGRATION_TEST_TIMEOUT_MS })
})

import { spawn, spawnSync } from "node:child_process"
import { readFileSync } from "node:fs"
import { dirname, join } from "node:path"
import { createInterface } from "node:readline/promises"
import { fileURLToPath } from "node:url"
import { isBunGlobalEntrypointPath } from "./lazycodex-bun-global-paths"
import type { RunCommand } from "./types"

const DEFAULT_UPDATE_COMMAND = "npx"
const DEFAULT_UPDATE_ARGS = ["--yes", "lazycodex-ai@latest", "install", "--no-tui", "--codex-autonomous"] as const
const BUN_UPDATE_COMMAND = "bun"
const BUN_GLOBAL_UPDATE_ARGS = ["update", "-g", "lazycodex-ai@latest"] as const
const BUN_GLOBAL_UNTRUSTED_ARGS = ["pm", "-g", "untrusted"] as const
const BUN_GLOBAL_TRUST_ARGS = ["pm", "-g", "trust"] as const
const INSTALLED_VERSION_FILE = "lazycodex-install.json"
const KNOWN_LAZYCODEX_BUN_TRUST_PACKAGES = new Set([
  "@ast-grep/cli",
  "@code-yeongyu/comment-checker",
  "@sisyphuslabs/omo-codex-plugin",
  "lazycodex-ai",
  "oh-my-openagent",
  "oh-my-opencode",
])
const KNOWN_LAZYCODEX_BUN_TRUST_PREFIXES = ["@oh-my-opencode/", "oh-my-openagent-", "oh-my-opencode-"] as const

type Version = {
  readonly major: number
  readonly minor: number
  readonly patch: number
  readonly prerelease: string | undefined
}

type LazyCodexUpdatePlan =
  | { readonly shouldUpdate: false; readonly reason: "unknown-current" | "unknown-latest" | "up-to-date" }
  | { readonly shouldUpdate: true; readonly command: string; readonly args: readonly string[]; readonly postUpdate: "bun-global-trust" | "none" }

export async function runLazyCodexManualUpdate(input: {
  readonly env?: NodeJS.ProcessEnv
  readonly dryRun?: boolean
  readonly log?: (line: string) => void
  readonly runCommand?: RunCommand
  readonly invokedPath?: string
  readonly isInteractive?: boolean
} = {}): Promise<number> {
  const env = input.env ?? process.env
  const log = input.log ?? console.log
  const commandRunner = input.runCommand ?? defaultRunCommandForManualUpdate
  const currentVersion = resolveCurrentVersion(env)
  const latestVersion = resolveLatestVersion(env)
  const plan = resolveLazyCodexUpdatePlan({
    currentVersion,
    latestVersion,
    command: resolveCommand(env),
    args: resolveArgs(env),
    env,
    invokedPath: input.invokedPath ?? process.argv[1],
  })
  if (!plan.shouldUpdate) {
    const printableVersion = currentVersion ?? "unknown"
    log(plan.reason === "up-to-date"
      ? `lazycodex-ai ${printableVersion} is already up to date.`
      : `Unable to check lazycodex-ai updates (${plan.reason}).`)
    return plan.reason === "up-to-date" ? 0 : 1
  }
  if (input.dryRun) {
    log(`${plan.command} ${plan.args.join(" ")}`)
    if (plan.postUpdate === "bun-global-trust") log(`${DEFAULT_UPDATE_COMMAND} ${DEFAULT_UPDATE_ARGS.join(" ")}`)
    return 0
  }
  await commandRunner(plan.command, plan.args, { cwd: process.cwd(), env })
  if (plan.postUpdate === "bun-global-trust") {
    await handleBunGlobalTrust({
      env,
      log,
      commandRunner,
      isInteractive: input.isInteractive ?? (process.stdin.isTTY === true && process.stdout.isTTY === true),
    })
    await commandRunner(DEFAULT_UPDATE_COMMAND, DEFAULT_UPDATE_ARGS, { cwd: process.cwd(), env })
  }
  return 0
}

function resolveLazyCodexUpdatePlan(input: {
  readonly currentVersion?: string
  readonly latestVersion?: string
  readonly command?: string
  readonly args?: readonly string[]
  readonly env?: NodeJS.ProcessEnv
  readonly invokedPath?: string
} = {}): LazyCodexUpdatePlan {
  const current = parseVersion(input.currentVersion)
  if (current === null) return { shouldUpdate: false, reason: "unknown-current" }
  const latest = parseVersion(input.latestVersion)
  if (latest === null) return { shouldUpdate: false, reason: "unknown-latest" }
  if (compareVersions(latest, current) <= 0) return { shouldUpdate: false, reason: "up-to-date" }
  if (isBunGlobalEntrypoint(input.invokedPath, input.env ?? process.env)) {
    return { shouldUpdate: true, command: BUN_UPDATE_COMMAND, args: BUN_GLOBAL_UPDATE_ARGS, postUpdate: "bun-global-trust" }
  }
  return { shouldUpdate: true, command: input.command ?? DEFAULT_UPDATE_COMMAND, args: input.args ?? DEFAULT_UPDATE_ARGS, postUpdate: "none" }
}

function resolveCommand(env: NodeJS.ProcessEnv): string {
  return env.LAZYCODEX_AUTO_UPDATE_COMMAND?.trim() || DEFAULT_UPDATE_COMMAND
}

function resolveArgs(env: NodeJS.ProcessEnv): readonly string[] {
  if (env.LAZYCODEX_AUTO_UPDATE_ARGS_JSON) {
    const parsed: unknown = JSON.parse(env.LAZYCODEX_AUTO_UPDATE_ARGS_JSON)
    if (!Array.isArray(parsed) || parsed.some((value) => typeof value !== "string")) {
      throw new TypeError("LAZYCODEX_AUTO_UPDATE_ARGS_JSON must be a JSON string array")
    }
    return parsed
  }
  return DEFAULT_UPDATE_ARGS
}

function resolveCurrentVersion(env: NodeJS.ProcessEnv): string | undefined {
  if (env.LAZYCODEX_CURRENT_VERSION?.trim()) return env.LAZYCODEX_CURRENT_VERSION.trim()
  const pluginRoot = dirname(dirname(fileURLToPath(import.meta.url)))
  return (
    readVersionManifest(resolveInstalledVersionPath(env, pluginRoot)) ??
    readVersionManifest(join(pluginRoot, "..", "..", "..", "package.json")) ??
    readVersionManifest(join(pluginRoot, ".codex-plugin", "plugin.json"))
  )
}

function resolveLatestVersion(env: NodeJS.ProcessEnv): string | undefined {
  if (env.LAZYCODEX_LATEST_VERSION?.trim()) return env.LAZYCODEX_LATEST_VERSION.trim()
  const result = spawnSync("npm", ["view", "lazycodex-ai", "version", "--silent"], {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "ignore"],
  })
  if (result.status !== 0) return undefined
  const version = result.stdout.trim()
  return version.length > 0 ? version : undefined
}

async function handleBunGlobalTrust(input: {
  readonly env: NodeJS.ProcessEnv
  readonly log: (line: string) => void
  readonly commandRunner: RunCommand
  readonly isInteractive: boolean
}): Promise<void> {
  const packageNames = resolveKnownBunGlobalUntrustedPackages(input.env)
  if (packageNames.length === 0) return

  const trustArgs = [...BUN_GLOBAL_TRUST_ARGS, ...packageNames]
  const trustCommand = [BUN_UPDATE_COMMAND, ...trustArgs].join(" ")
  if (!input.isInteractive) {
    input.log(`Bun blocked LazyCodex-related postinstall scripts. Run this command to trust them:\n${trustCommand}`)
    return
  }

  if (await confirmBunGlobalTrust(packageNames)) {
    await input.commandRunner(BUN_UPDATE_COMMAND, trustArgs, { cwd: process.cwd(), env: input.env })
    return
  }
  input.log(`Skipped Bun postinstall trust. To run it later:\n${trustCommand}`)
}

function resolveKnownBunGlobalUntrustedPackages(env: NodeJS.ProcessEnv): readonly string[] {
  const result = spawnSync(BUN_UPDATE_COMMAND, BUN_GLOBAL_UNTRUSTED_ARGS, {
    encoding: "utf8",
    env,
    stdio: ["ignore", "pipe", "ignore"],
  })
  if (result.status !== 0) return []
  const names: string[] = []
  for (const match of result.stdout.matchAll(/^\.\/node_modules\/((?:@[^/\s]+\/)?[^\s]+)\s+@/gm)) {
    const packageName = match[1]
    if (packageName !== undefined && isKnownLazyCodexBunTrustPackage(packageName) && !names.includes(packageName)) {
      names.push(packageName)
    }
  }
  return names
}

async function confirmBunGlobalTrust(packageNames: readonly string[]): Promise<boolean> {
  const prompt = `Trust Bun postinstall scripts for ${packageNames.join(", ")}? [y/N] `
  const readline = createInterface({ input: process.stdin, output: process.stdout })
  try {
    const answer = (await readline.question(prompt)).trim().toLowerCase()
    return answer === "y" || answer === "yes"
  } finally {
    readline.close()
  }
}

function isKnownLazyCodexBunTrustPackage(packageName: string): boolean {
  return KNOWN_LAZYCODEX_BUN_TRUST_PACKAGES.has(packageName) ||
    KNOWN_LAZYCODEX_BUN_TRUST_PREFIXES.some((prefix) => packageName.startsWith(prefix))
}

function isBunGlobalEntrypoint(invokedPath: string | undefined, env: NodeJS.ProcessEnv): boolean {
  return isBunGlobalEntrypointPath(invokedPath, env)
}

function defaultRunCommandForManualUpdate(command: string, args: readonly string[], options: { readonly cwd: string; readonly env?: NodeJS.ProcessEnv }): Promise<void> {
  return new Promise((resolve, reject) => {
    const child = spawn(command, args, {
      cwd: options.cwd,
      env: options.env,
      stdio: "inherit",
      shell: false,
    })
    child.once("error", reject)
    child.once("close", (code) => {
      if (code === 0) {
        resolve()
        return
      }
      reject(new Error(`${command} ${args.join(" ")} exited with ${code ?? "unknown status"}`))
    })
  })
}

function parseVersion(version: string | undefined): Version | null {
  if (typeof version !== "string") return null
  const match = /^(\d+)\.(\d+)\.(\d+)(?:-([^+]+))?(?:\+.*)?$/.exec(version.trim())
  if (match === null) return null
  const major = Number.parseInt(match[1] ?? "", 10)
  const minor = Number.parseInt(match[2] ?? "", 10)
  const patch = Number.parseInt(match[3] ?? "", 10)
  const prerelease = match[4]
  return Number.isFinite(major) && Number.isFinite(minor) && Number.isFinite(patch)
    ? { major, minor, patch, prerelease }
    : null
}

function compareVersions(left: Version, right: Version): number {
  for (const key of ["major", "minor", "patch"] as const) {
    const leftValue = left[key]
    const rightValue = right[key]
    if (leftValue > rightValue) return 1
    if (leftValue < rightValue) return -1
  }
  if (left.prerelease === undefined && right.prerelease !== undefined) return 1
  if (left.prerelease !== undefined && right.prerelease === undefined) return -1
  if (left.prerelease !== undefined && right.prerelease !== undefined) {
    return left.prerelease.localeCompare(right.prerelease)
  }
  return 0
}

function resolveInstalledVersionPath(env: NodeJS.ProcessEnv, pluginRoot: string): string {
  if (env.LAZYCODEX_INSTALLED_VERSION_FILE?.trim()) return env.LAZYCODEX_INSTALLED_VERSION_FILE.trim()
  return join(pluginRoot, INSTALLED_VERSION_FILE)
}

function readVersionManifest(path: string): string | undefined {
  try {
    const parsed: unknown = JSON.parse(readFileSync(path, "utf8"))
    if (typeof parsed === "object" && parsed !== null && "version" in parsed && typeof parsed.version === "string") {
      return parsed.version
    }
    return undefined
  } catch (error) {
    if (error instanceof Error) return undefined
    return undefined
  }
}

